import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-a2-001","clusterId":"A","werkstueckRef":"A.12","stufe":1,"question":"Maja sagt: „Stell dir mal vor, die Geheimdienste hätten alles von langer Hand geplant, und dann passiert genau das, was man jetzt in den Nachrichten sieht. Passt doch alles zusammen, also muss es so gewesen sein.“ Woran erkennst du, dass das keine tragfähige Überlegung ist?","options":["Sie legt weder Annahmen noch Spielregeln fest und kreist um eine bereits feststehende Überzeugung, statt prüfbare Folgen herzuleiten.","Sie beruft sich auf das Urteil von Fachleuten für Geheimdienste statt auf Gründe, obwohl ein Expertenrang kein Argument ersetzt.","Sie verallgemeinert vom Fall aus den Nachrichten auf eine Regel für alle Geheimdienste, obwohl ein einzelner Fall keine Regel trägt.","Sie beruft sich darauf, dass viele Menschen solche Pläne vermuten, obwohl die Zahl der Anhänger nichts über den Wahrheitsgehalt sagt."],"correctIndex":0,"explanation":"Ein Gedankenexperiment legt die Annahme und die Spielregeln vorab fest und folgt dann konsequent der Logik, um Stimmigkeit und Folgen zu prüfen. Majas Überlegung tut das Gegenteil: Sie beginnt beim gewünschten Ergebnis und schmückt es aus. Dass „alles zusammenpasst“, ist bei einer frei erzählten Geschichte kein Wunder, denn sie lässt sich beliebig anpassen. Entscheidend ist, ob Regeln gelten und ob sich daraus Schlüsse ziehen lassen, die man nachprüfen kann; ein erfundenes Szenario ist dagegen nicht das Problem, auch Einstein stellte sich vor, einem Lichtstrahl hinterherzujagen. Und selbst ein sauber durchgeführtes Gedankenexperiment liefert keinen Befund über die Wirklichkeit, sondern prüft nur, ob eine Idee in sich stimmig ist. Der Hinweis auf Fachleute klingt nach solider Argumentation, doch Maja nennt keine Fachleute, sie malt sich nur etwas aus. Die Regel für alle Geheimdienste klingt nach einem typischen Fehlschluss, doch Maja spricht von einem Fall und leitet keine Regel ab. Der Verweis auf viele Anhänger klingt nach einem Argument, doch Maja beruft sich auf keine Verbreitung der Idee.","coreRule":"⚡ Ein Gedankenexperiment braucht klare Anfangsbedingungen und Regeln und leitet prüfbare Folgen her. Eine Geschichte, die nur eine fertige Überzeugung ausschmückt, ist kein Test.","quote":"","quoteLabel":"","beleg":"Werkstück A.12 (Kontext & Tiefe; Red Flag „Unstrukturierte Fantasie“; Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Maja beginnt beim gewünschten Ergebnis und schmückt es aus, statt Annahmen und Regeln vorab festzulegen und daraus Nachprüfbares herzuleiten. Dass „alles zusammenpasst“, ist bei einer frei erzählten Geschichte kein Wunder.","prueffrage":"Hätte Maja dieselbe Geschichte auch erzählen können, wenn in den Nachrichten etwas ganz anderes passiert wäre?","rueckmeldung":[{"option":1,"text":"Dass Expertenrang kein Argument ersetzt, stimmt. Maja nennt aber keine Fachleute, sie malt sich nur eine Geschichte aus. Der Fehler liegt im Vorgehen: Sie startet beim Wunschergebnis, statt Regeln festzulegen und Prüfbares herzuleiten."},{"option":2,"text":"Ein einzelner Fall trägt tatsächlich keine allgemeine Regel. Maja spricht aber nur von diesem einen Fall und leitet keine Regel für alle Geheimdienste ab. Der Fehler liegt anderswo: Ihre Geschichte folgt keinen festgelegten Regeln."},{"option":3,"text":"Die Zahl der Anhänger sagt nichts über den Wahrheitsgehalt, das ist richtig. Maja beruft sich aber auf keine Verbreitung der Idee, sie erzählt nur ihre Geschichte. Der Fehler liegt darin, dass diese bei einem Wunschergebnis beginnt."}],"familie":"zu-ende-denken","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Thought Experiments (überarb. 28.11.2023)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thought-experiment/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"9e3cb7f74995d3b5"}},{"id":"qx-a2-002","clusterId":"A","werkstueckRef":"A.12","stufe":2,"question":"Welcher Prüfschritt deckt am besten auf, ob diese Behauptung in sich stimmig ist?","scenario":"Eine Bekannte erklärt dir beim Kaffee: „Deine Gedanken erschaffen deine Realität. Wer fest genug an etwas denkt, bekommt es auch.“ Du willst die Behauptung prüfen, ohne gleich ein aufwendiges Experiment zu planen.","options":["Du nimmst an, sie gelte für alle Menschen gleichzeitig, und suchst nach Widersprüchen, etwa wenn zwei Menschen sich denselben einmaligen Lottogewinn vorstellen.","Du vergleichst eine Gruppe, die fest an etwas denkt, mit einer Kontrollgruppe, die das nicht tut, und zählst nach, in welcher Gruppe sich mehr Wünsche erfüllen.","Du fragst, ob die Bekannte an ihrer Aussage verdient oder sonst ein Eigeninteresse hat, und gewichtest ihre Behauptung danach, wem sie nützen würde.","Du prüfst, ob sich berichtete Erfolgsgeschichten einfacher durch Zufall oder Auswahl erklären lassen, und ziehst die einfachste passende Erklärung vor."],"correctIndex":0,"explanation":"Ein Gedankenexperiment macht eine Behauptung testbar, ohne dass man sie in der Wirklichkeit ausprobieren muss: Man setzt sie als wahr voraus und spielt durch, was daraus folgt. Gilt der Satz für alle 8 Milliarden Menschen, müsste derselbe einmalige Lottogewinn mehreren Menschen zufallen. Ein Diktator, der sich den Gehorsam aller wünscht, und ein Freiheitskämpfer, der sich die Freiheit aller wünscht, würden unvereinbare Realitäten erzeugen. Eine Behauptung, die im Maßstab in Widersprüche gerät, ist in sich nicht stimmig. Die anderen Schritte sind in anderer Lage nützlich, beantworten hier aber nicht die Frage nach der inneren Stimmigkeit: Eine Kontrollgruppe wäre genau das aufwendige Experiment, das du vermeiden willst. Das Eigeninteresse der Bekannten sagt nichts darüber, ob ihr Satz in sich stimmt, und ob sich Erfolge durch Zufall erklären ließen, zeigt nichts über die Logik der Behauptung.","coreRule":"⚡ Prüfe eine Behauptung, indem du sie als wahr annimmst und im großen Maßstab durchspielst: Bleibt sie widerspruchsfrei?","beleg":"Werkstück A.12 (Anwendung: Esoterik & New Age, „Gesetz der Anziehung“)","status":"entwurf","kurz":"Setzt du den Satz als wahr voraus und spielst durch, was für alle Menschen zugleich folgt, geraten die Wünsche in Konflikt, etwa beim einmaligen Lottogewinn. Das deckt die innere Unstimmigkeit auf, ohne dass du etwas ausprobieren musst.","prueffrage":"Erfährst du aus gezählten Erfolgen oder aus dem Ruf einer Person, ob der Satz sich selbst widerspricht?","rueckmeldung":[{"option":1,"text":"Ein Vergleich mit Kontrollgruppe wäre ein gutes Mittel, um die Wirkung zu testen. Du wolltest aber gerade kein aufwendiges Experiment planen, und er sagt auch nichts darüber, ob der Satz in sich stimmig ist."},{"option":2,"text":"Ein Eigeninteresse kann misstrauisch machen und ist in anderen Situationen ein brauchbarer Hinweis. Ob ein Satz in sich stimmig ist, zeigt es nicht, denn auch eine interessengeleitete Behauptung kann wahr sein."},{"option":3,"text":"Zufall und Auswahl erklären Erfolgsgeschichten oft einfacher, das ist ein nützlicher Gedanke. Hier liegen aber gar keine Berichte vor, und die Frage nach der Logik der Behauptung beantwortet dieser Schritt nicht."}],"familie":"zu-ende-denken","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Thought Experiments (überarb. 28.11.2023)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thought-experiment/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"a9b3ea2e7fa2bc22"}},{"id":"qx-a2-003","clusterId":"A","werkstueckRef":"A.12","stufe":3,"question":"Ein Redner sagt: „Mein Gedankenexperiment zeigt, dass Wasser ein Gedächtnis hat, denn man kann es widerspruchsfrei durchspielen.“ Was ist an diesem Schluss fehlerhaft?","options":["Dass sich die Idee vom Wassergedächtnis widerspruchsfrei durchspielen lässt, zeigt nur, dass sie denkbar und in sich stimmig ist, nicht dass sie in der Wirklichkeit zutrifft.","Er stützt sich auf einzelne Berichte von Menschen, die ein Wassergedächtnis erlebt haben wollen, statt auf systematische Daten, obwohl Einzelfälle verzerrt sein können.","Er beruft sich auf die weite Verbreitung des Glaubens ans Wassergedächtnis, obwohl die Zahl der Menschen, die etwas glauben, nichts über die Wahrheit sagt.","Er widerlegt eine Karikatur der Einwände von Physikern gegen das Wassergedächtnis statt ihrer eigentlichen Argumente, sodass ein Strohmann seinen Schluss trägt."],"correctIndex":0,"explanation":"Ein Gedankenexperiment prüft die logische Stimmigkeit einer Annahme, mehr nicht. Fällt eine Idee dabei durch, weil sie sich selbst widerspricht, muss man sie gar nicht erst an der Wirklichkeit testen. Besteht sie die Prüfung, ist sie damit noch nicht wahr: Nur weil eine Idee ein Gedankenexperiment überlebt, heißt das noch lange nicht, dass sie wahr ist. Ob Wasser ein Gedächtnis hat, entscheidet am Ende die Realität, nicht die Vorstellungskraft. Dabei sind Annahmen, die der Wirklichkeit widersprechen, durchaus erlaubt (Einstein ließ sich auf einem Lichtstrahl reiten), solange sie als Annahmen kenntlich bleiben und das Ergebnis nicht mit einem Beweis verwechselt wird. Einzelne Berichte wären ein bekannter Schwachpunkt, doch der Redner führt keine an. Die weite Verbreitung der Idee wäre ein schwaches Argument, doch er beruft sich nicht darauf. Eine Karikatur der Einwände von Physikern wäre ein Strohmann, doch der Redner nennt gar keine Gegenposition, die er verzerren könnte.","coreRule":"⚡ Überleben im Gedankenexperiment heißt „möglich“, nicht „wahr“; entscheiden muss die Realität.","beleg":"Werkstück A.12 (Red Flags; Der Kipppunkt)","status":"entwurf","kurz":"Dass sich eine Idee widerspruchsfrei durchspielen lässt, zeigt nur, dass sie denkbar und in sich stimmig ist. Der Fehler liegt darin, aus „kein Widerspruch im Kopf“ auf „trifft in der Wirklichkeit zu“ zu schließen.","prueffrage":"Welche Messung oder Beobachtung könnte zeigen, dass der Redner mit seiner Behauptung danebenliegt?","rueckmeldung":[{"option":1,"text":"Einzelne Berichte sind tatsächlich ein bekannter Schwachpunkt, nur führt der Redner gar keine an. Sein Argument ist allein, dass sich die Idee widerspruchsfrei durchspielen lässt, und dort liegt der Fehler."},{"option":2,"text":"Wer sich auf die Zahl der Gläubigen beruft, argumentiert schwach, denn Verbreitung sagt nichts über Wahrheit. Der Redner tut das aber nicht: Er stützt sich nur auf ein Gedankenexperiment, das er widerspruchsfrei durchspielt."},{"option":3,"text":"Ein Strohmann setzt eine Gegenposition voraus, die verzerrt wird. Der Redner nennt aber keinerlei Einwände von Physikern, die er karikieren könnte. Der Fehler steckt im Schluss vom Durchspielen auf die Wirklichkeit."}],"familie":"zu-ende-denken","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Thought Experiments (überarb. 28.11.2023)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thought-experiment/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"c7be192b9fe240f6"}},{"id":"qx-a2-004","clusterId":"A","werkstueckRef":"A.12","stufe":4,"question":"Wie belastbar ist das Ergebnis einer solchen Rechnung mit offengelegten, aber geschätzten Annahmen?","options":["Die Rechnung widerlegt die behauptete Täuschung, sofern das Ergebnis deutlich ausfällt und die Zahlen plausibel klingen.","Sie zeigt, welche Konsequenzen die Behauptung unter den genannten Annahmen hätte; weil die Annahmen offenliegen, kann jeder sie nachrechnen, ändern und angreifen.","Sie ist kaum aussagekräftig, weil geschätzte Zahlen zu ungenau sind, um daraus eine Schlussfolgerung zu ziehen.","Sie wird erst belastbar, wenn die Schätzungen durch gemessene Werte ersetzt sind und keine Annahme mehr offen ist."],"correctIndex":1,"explanation":"Eine Rechnung mit Schätzwerten ist kein Beweis, aber auch nicht wertlos. Sie macht aus einer vagen Vorstellung ein Modell: Die Annahmen stehen offen auf dem Tisch, und jeder kann prüfen, ob sie vernünftig sind, und sie verändern. Dass die Zahlen Schätzungen sind, entwertet die Rechnung nicht, solange die Annahmen sichtbar sind und überprüft werden können. Ein reales Beispiel: Der Forscher David Robert Grimes rechnete 2016 die Mondlandungsverschwörung so durch. Er setzte rund 411.000 Mitwissende an (die NASA-Beschäftigten im Spitzenjahr 1965) und schätzte das Risiko des Verrats bewusst niedrig. Selbst dann wäre der Schwindel nach knapp vier Jahren mit über 95 Prozent Wahrscheinlichkeit aufgeflogen. Grimes selbst nennt die Zahlen grobe Größenordnungen, und das Modell nimmt an, alle Gezählten wären eingeweiht. Der Wert liegt in der Nachprüfbarkeit der Annahmen, nicht in einem Beweis.","coreRule":"⚡ Ein Gedankenexperiment wird zum Modell, wenn seine Annahmen offenliegen und angreifbar sind.","beleg":"Werkstück A.12 (Anwendung: Verschwörungsmythen); Fn. ga-grimes (Grimes 2016, PLOS ONE 11(1), e0147905, S. 8 und S. 11)","status":"freigegeben","freigabe":{"datum":"2026-10-13","pruefsumme":"880871099472401a","vermerk":"Prüfpult"},"scenario":"Eine Forscherin schätzt für eine angebliche Jahrzehnte alte Täuschung grob die Zahl der Eingeweihten und das Risiko ein, dass jemand das Geheimnis ausplaudert. Sie rechnet beide Annahmen durch und legt sie in der Veröffentlichung offen. Ein Kritiker wendet ein: „Das sind doch nur geschätzte Zahlen, also ist die ganze Rechnung wertlos.“","kurz":"Die Rechnung ist kein Beweis, aber auch nicht wertlos: Sie zeigt, was die Behauptung unter den genannten Annahmen bedeuten würde. Weil diese offenliegen, kann jeder sie prüfen und ändern. Geschätzt heißt nicht wertlos, sondern angreifbar.","prueffrage":"Welche Zahlen stehen in der Rechnung, und würde sich das Ergebnis ändern, wenn man sie großzügig verschiebt?","rueckmeldung":[{"option":0,"text":"Ein deutliches Ergebnis wirkt wie ein Urteil. Doch die Rechnung zeigt nur, was unter den gewählten Annahmen folgt, und ist kein Beweis. Dass sie Zweifel begründet, heißt nicht, dass sie die Täuschung widerlegt."},{"option":2,"text":"Der Einwand hat einen wahren Kern: Schätzungen sind ungenau, und ein Beweis entsteht so nicht. Ungenau ist aber nicht wertlos, solange offenliegt, was angenommen wurde. Dann lässt sich prüfen, ob das Ergebnis auch bei anderen Zahlen hält."},{"option":3,"text":"Gemessene Werte wären natürlich besser. Wer Belastbarkeit aber erst ohne jede offene Annahme zugesteht, verlangt etwas, das kaum ein Modell erfüllt. Entscheidend ist, dass die Annahmen sichtbar und nachprüfbar sind, nicht dass sie gemessen sind."}],"familie":"zu-ende-denken","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Grimes, D. R. (2016): On the Viability of Conspiratorial Beliefs. PLOS ONE 11(1), e0147905","oeffentlich":true,"doi":"10.1371/journal.pone.0147905"},{"typ":"doi","kurz":"Grimes, D. R. (2016): Correction: On the Viability of Conspiratorial Beliefs. PLOS ONE 11(3), e0151003","oeffentlich":true,"doi":"10.1371/journal.pone.0151003"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"880871099472401a"}},{"id":"qx-a2-005","clusterId":"A","werkstueckRef":"A.13","stufe":1,"question":"Was würdest du als Nächstes tun?","options":["Genau beobachten, wohin die Leute beim Hinuntergehen schauen und was sie auf ihrem Weg erreichen wollen.","Zwei Treppen vergleichen, eine mit zusätzlichen Schildern, eine ohne, und die Unfallzahlen beider auswerten.","Die Unfälle über mehr Monate auswerten, um zufällige Schwankungen von einem echten Muster zu trennen.","Eine Prämie für unfallfreie Monate ausloben, damit die Leute einen Anreiz haben, aufmerksamer zu sein."],"correctIndex":0,"explanation":"Wenn ein Verhalten unerklärlich wirkt, ist „dumm und unachtsam“ die bequeme, aber leere Erklärung: Sie prüft nichts und erklärt nicht, warum drei Maßnahmen nichts geändert haben. Wer Menschen als vernünftig Handelnde annimmt, fragt stattdessen, welches Ziel ihr Verhalten sinnvoll macht, und beobachtet es. Naheliegend ist hier etwa, dass die Leute beim Hinuntergehen schon die belebte Kreuzung am Treppenende im Blick haben, um eine Lücke zu finden, und deshalb nicht auf die Stufen achten. Erst wenn man das Ziel kennt, lässt sich das System ändern, statt die Menschen ändern zu wollen.","coreRule":"⚡ Bevor du Menschen als dumm abstempelst, frag nach dem unsichtbaren Ziel hinter ihrem Verhalten.","quote":"Das Problem war nicht der Mensch, sondern die Treppe im Verhältnis zum Flur.","quoteLabel":"Merksatz:","beleg":"Werkstück A.13 (Einstiegsgeschichte „Die verfluchte Treppe“; Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"In einem Bürogebäude häufen sich die Unfälle auf einer steilen Treppe. Am Fuß der Treppe kreuzen sich zwei stark befahrene Hauptflure. Vorsicht-Schilder, hellere Beleuchtung und rutschfeste Streifen haben nichts geändert, die Unfallrate ist seit Monaten unverändert hoch. Ein Manager sagt: „Unsere Leute sind einfach zu dumm und unachtsam für eine Treppe.“","kurz":"Wenn drei Maßnahmen nichts ändern, trägt „zu dumm und unachtsam“ nicht, denn es erklärt nichts und prüft nichts. Besser ist die Frage, welches Ziel das Verhalten sinnvoll macht, und das zeigt genaues Beobachten, etwa der Blick zur belebten Kreuzung.","prueffrage":"Was haben Schilder, Beleuchtung und Streifen gemeinsam, und wurde vorher herausgefunden, warum die Leute gerade auf dieser Treppe stürzen?","rueckmeldung":[{"option":1,"text":"Ein Vergleich wirkt gründlich, doch dass Schilder nicht helfen, ist hier schon bekannt. Ein weiterer Test würde das nur wiederholen und nicht erklären, warum die Leute auf dieser Treppe stürzen."},{"option":2,"text":"Mehr Monate auszuwerten klingt nach sauberem Vorgehen. Die unveränderte Rate zeigt aber bereits ein Muster statt Zufall; zusätzliche Zahlen sagen weiterhin nicht, warum die Unfälle passieren."},{"option":3,"text":"Ein Anreiz scheint zumindest etwas zu bewirken. Er setzt aber bei einer Unachtsamkeit an, die bisher nur behauptet und nicht festgestellt wurde, und lässt offen, warum die bisherigen Maßnahmen nichts änderten."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The Correspondence Bias. Psychological Bulletin 117(1), 21–38 (Autorenkopie, Harvard)","oeffentlich":true,"url":"https://dtg.sites.fas.harvard.edu/Gilbert%20%26%20Malone%20%28CORRESPONDENCE%20BIAS%29.pdf","seite":"21","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"54c1ea8ba55010da"}},{"id":"qx-a2-006","clusterId":"A","werkstueckRef":"A.13","stufe":2,"question":"Welche Frage bringt dich am ehesten zu einer brauchbaren Erklärung seines Verhaltens?","scenario":"Dein Onkel lässt sich seit Monaten bei einem Energieheiler behandeln und geht für diese Beschwerden nicht mehr zum Arzt. Er ist sonst ein nüchterner, vernünftiger Mensch. Du willst verstehen, warum er so handelt.","options":["„Welche Belege gibt es für die Wirkung solcher Behandlungen, etwa Studien, Übersichtsarbeiten und Erfahrungsberichte?“","„Was verdient der Heiler an ihm, etwa durch Honorare, Zusatzverkäufe und Folgetermine, und was treibt ihn an?“","„Welche Wissenslücke hindert ihn, die fehlende Wirkung zu erkennen, etwa bei Placebo, Spontanheilung und Risiken?“","„Welches Problem löst der Heiler für ihn, etwa durch Zeit, Zuwendung, eine einfache Erzählung und Hoffnung?“"],"correctIndex":3,"explanation":"Wer ein Verhalten nur als Dummheit oder Charakterschwäche abtut, hat noch nichts erklärt. Die Frage nach dem Problem, das das Verhalten für die Person löst, macht sichtbar, was sie tatsächlich antreibt. Ein Heiler bietet oft ungeteilte Aufmerksamkeit, Empathie, eine verständliche Erzählung ohne Fachjargon und Hoffnung, wo die „Schulmedizin“ vielleicht nur noch von „Management“ spricht. Dann ist die Entscheidung des Onkels eher emotional und sozial rational als medizinisch dumm. Verstehen heißt dabei nicht gutheißen: Das Verständnis der Anreize ist der Schlüssel zu einem wirksamen Umgang mit dem Verhalten. Die Frage nach den Belegen klingt nach Sachlichkeit, klärt aber nur, ob die Methode wirkt, nicht, warum er sie wählt. Die Frage nach dem Verdienst des Heilers klingt nach gesundem Misstrauen, beschreibt aber dessen Motive, nicht die deines Onkels. Die Frage nach einer Wissenslücke klingt nach Aufklärung, übersieht aber, dass er sich sonst nüchtern und vernünftig verhält.","coreRule":"⚡ Frag, welches Bedürfnis ein Verhalten erfüllt, nicht, wie jemand so etwas glauben kann.","beleg":"Werkstück A.13 (Anwendung: Pseudomedizin; Aktivierungs-Frage)","status":"entwurf","kurz":"Wer sein Verhalten nur als Dummheit abtut, hat nichts erklärt. Fragst du, welches Problem der Heiler für deinen Onkel löst, etwa Zuwendung, Hoffnung und eine verständliche Erzählung, wird sichtbar, was ihn tatsächlich antreibt.","prueffrage":"Seit wann geht dein Onkel zum Heiler statt zum Arzt, und was hat sich für ihn damals verändert?","rueckmeldung":[{"option":0,"text":"Belege zu prüfen ist sinnvoll und sachlich. Sie zeigen aber nur, ob die Methode wirkt, nicht, warum dein Onkel sie wählt. Dafür musst du bei ihm und seiner Lage ansetzen."},{"option":1,"text":"Misstrauen gegenüber dem Heiler kann berechtigt sein. Seine Einnahmen und Motive erklären aber das Handeln des Heilers, nicht das deines Onkels. Gefragt ist, was ihn selbst antreibt."},{"option":2,"text":"Aufklärung kann hilfreich sein. Diese Frage unterstellt aber, dass es ihm an Wissen fehlt, und das passt schlecht zu einem sonst nüchternen, vernünftigen Menschen. So lässt sich sein Verhalten nicht erklären."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Mercer, S. W.; Reilly, D.; Watt, G. C. M. (2002): The importance of empathy in the enablement of patients attending the Glasgow Homoeopathic Hospital. Br J Gen Pract 52(484), 901–905 (Abstract, PubMed)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/12434958/","abruf":"2026-10-12"},{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The Correspondence Bias. Psychological Bulletin 117(1), 21–38 (Autorenkopie, Harvard)","oeffentlich":true,"url":"https://dtg.sites.fas.harvard.edu/Gilbert%20%26%20Malone%20%28CORRESPONDENCE%20BIAS%29.pdf","seite":"21","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"b1de01a47e73850e"}},{"id":"qx-a2-007","clusterId":"A","werkstueckRef":"A.13","stufe":3,"question":"Ein Kollege wirft dir vor: „Wenn du erklärst, warum Menschen extremistischen Ideologien folgen, entschuldigst du sie.“ Welche Antwort trifft den Denkfehler in diesem Vorwurf am besten?","options":["Der Vorwurf setzt Erklären mit Entschuldigen gleich; eine Erklärung nennt Ursachen, eine Entschuldigung spricht frei, und wer Ursachen kennt, kann Verhalten gezielter bekämpfen.","Der Vorwurf unterstellt, Extremismus habe eine einzige Ursache; wer Gründe nennt, vereinfache das Bild, und wer vereinfache, verfälsche damit die Wirklichkeit.","Der Vorwurf verwechselt Korrelation mit Kausalität; dass bestimmte Umstände und Extremismus zusammen auftreten, zeigt nicht, dass die Umstände ihn verursachen.","Der Vorwurf beruft sich auf die Mehrheitsmeinung, Extremisten verdienten keine Erklärung; dass viele Menschen so denken, sagt aber nichts über ihre Stichhaltigkeit."],"correctIndex":0,"explanation":"Der Vorwurf verwechselt zwei verschiedene Dinge: Verstehen, wie ein Verhalten zustande kommt, und Gutheißen, dass es richtig ist. Wer Anreize und Ursachen analysiert, beantwortet eine Sachfrage („Wie kommt es dazu?“), keine Wertungsfrage („Ist es in Ordnung?“). Man kann die systemischen Gründe für Rassismus untersuchen und ihn zugleich unmissverständlich bekämpfen. Ohne Verständnis der Ursachen bleibt die Gegenwehr dagegen oft wirkungslos, weil sie an den eigentlichen Anreizen vorbeigeht.","coreRule":"⚡ Anreize zu verstehen heißt nicht, das Verhalten gutzuheißen.","beleg":"Werkstück A.13 (Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Erklären beantwortet die Sachfrage, wie etwas zustande kommt; Entschuldigen wäre eine Wertung, dass es in Ordnung ist. Der Vorwurf wirft beides zusammen, obwohl man Ursachen kennen und das Verhalten dennoch klar ablehnen kann.","prueffrage":"Heißt eine Ärztin, die erklärt, wie eine Sucht entsteht, die Sucht damit gut?","rueckmeldung":[{"option":1,"text":"Dass Extremismus selten nur eine Ursache hat, stimmt. Der Kollege sagt aber nichts über die Zahl der Ursachen, sondern gleicht Erklären mit Entschuldigen an. Der Fehler liegt dort, nicht in einer Vereinfachung."},{"option":2,"text":"Das Begriffspaar klingt nach sauberem Denken, doch der Vorwurf behauptet keinen ursächlichen Zusammenhang zwischen Umständen und Extremismus. Er sagt etwas über das Erklären selbst. Der Fehler liegt also woanders."},{"option":3,"text":"Eine Mehrheitsmeinung wäre ein schwaches Argument, aber der Kollege beruft sich auf keine Mehrheit. Er setzt Erklären mit Entschuldigen gleich, und genau dort sitzt der Denkfehler."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Miller, A. G.; Gordon, A. K.; Buddie, A. M. (1999): Accounting for evil and cruelty: is to explain to condone? Personality and Social Psychology Review 3(3), 254–268 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1207/s15327957pspr0303_8","url":"https://pubmed.ncbi.nlm.nih.gov/15661676/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"d36ebe45a541a06a"}},{"id":"qx-a2-008","clusterId":"A","werkstueckRef":"A.13","stufe":4,"question":"Was ist an dieser Überlegung fehlerhaft, und was wäre der bessere nächste Schritt?","options":["Er schließt aus „Ich kenne den Zweck nicht“ auf „Es gibt keinen Zweck“; besser wäre, zuerst herauszufinden, wozu der Ablauf eingeführt wurde, und dann zu entscheiden.","Er rechnet den Zeitgewinn nicht gegen den besten anderen Einsatz der Zeit; besser wäre, zuerst zu bestimmen, wofür die gewonnenen Stunden am besten genutzt würden, und dann zu entscheiden.","Er schließt von diesem einen auffälligen Formularlauf auf Verschwendung in der ganzen Abteilung; besser wäre, zuerst alle Abläufe der Abteilung zu prüfen, und dann zu entscheiden.","Er entscheidet über die Köpfe der Beschäftigten hinweg; besser wäre, sie zuerst abstimmen zu lassen, ob sie den Formularlauf behalten wollen, und dann zu entscheiden."],"correctIndex":0,"explanation":"Dass niemand den Zweck nennen kann, zeigt nur, dass er nicht bekannt ist, nicht dass es keinen gibt. Ein Ablauf, der aufwendig und lästig wirkt, kann trotzdem ein Problem lösen, das man von außen nicht sieht (zum Beispiel eine frühere Panne oder eine Prüfpflicht; das sind hier nur denkbare Beispiele, über den konkreten Fall ist nichts bekannt). Wer ihn abschafft, ohne das zu klären, riskiert, genau dieses Problem zurückzuholen. Das ist die Logik von Chestertons Zaun: Man reißt einen Zaun quer über dem Weg erst ein, wenn man weiß, wozu er gebaut wurde. Das ist kein Verbot der Änderung, sondern die Forderung, zuerst den Zweck zu verstehen. Chesterton sprach von Einrichtungen und Gesetzen; die Übertragung auf Arbeitsabläufe ist eine Erweiterung. Die Frage nach dem besten anderen Einsatz der Zeit klingt nach Wirtschaftlichkeit, sagt aber nichts darüber, was der Formularlauf bisher verhindert. Die Prüfung aller Abläufe der Abteilung klingt gründlich, doch der Abteilungsleiter will nur diesen einen Formularlauf abschaffen, und sie klärt nicht, wozu er eingeführt wurde. Eine Abstimmung klingt demokratisch, nützt aber wenig, wenn schon jetzt niemand den Zweck kennt.","coreRule":"⚡ Aus „Ich sehe den Zweck nicht“ folgt nicht „Es gibt keinen“: Kläre erst, wozu etwas da ist, dann entscheide.","beleg":"Werkstück A.13 (Kontext & Tiefe); Fn. ga-chesterton (Chesterton 1929, The Thing, Nachdruck 1946, S. 29)","status":"entwurf","scenario":"Ein neuer Abteilungsleiter findet in seiner Abteilung einen dreifachen Formularlauf für jede Bestellung. Niemand kann ihm sagen, wozu er gut ist. Er sagt: „Das ist offensichtlich sinnloser Aufwand, ich schaffe das ab diese Woche ab.“","kurz":"Dass niemand den Zweck kennt, zeigt nur, dass er unbekannt ist, nicht dass es keinen gibt. Ein lästiger Ablauf kann ein unsichtbares Problem lösen; erst den Zweck zu klären, verhindert, es zurückzuholen.","prueffrage":"Seit wann arbeitet der Abteilungsleiter in dieser Abteilung, und wie viel von ihrer Geschichte kann er kennen?","rueckmeldung":[{"option":1,"text":"Zeitgewinn ist ein echter Gesichtspunkt, die Rechnung bleibt aber einseitig. Sie setzt den Aufwand des Formularlaufs an, kennt aber nicht, was er bisher verhindert, und über den Nutzen lässt sich erst sprechen, wenn der Zweck bekannt ist."},{"option":2,"text":"Gründlichkeit klingt vernünftig. Der Leiter will aber nur diesen einen Formularlauf abschaffen, und eine Prüfung aller Abläufe klärt nicht, wozu gerade dieser eingeführt wurde."},{"option":3,"text":"Die Belegschaft einzubeziehen ist grundsätzlich sinnvoll, hilft hier aber wenig: Wenn schon jetzt niemand den Zweck nennen kann, stimmen alle ohne das nötige Wissen ab, und der eigentliche Schluss vom Nichtwissen auf Zwecklosigkeit bleibt unberührt."}],"familie":"vorstellung-ist-kein-massstab","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Chesterton, G. K. (1929): The Thing. London: Sheed & Ward, Essay „The Drift from Domesticity“","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"0b050d97b9545a5f"}},{"id":"qx-a2-009","clusterId":"A","werkstueckRef":"A.14","stufe":2,"question":"Was ist an dieser Begründung fürs Weitermachen fehlerhaft, und welche Frage prüft stattdessen, ob du weitermachen solltest?","scenario":"Seit drei Jahren pflegst du die Website eines Vereins, die kaum jemand besucht. Du hast schon rund 400 Stunden hineingesteckt. Auf der nächsten Sitzung sagt ein Mitglied: „Nach all der Arbeit wäre es doch schade, jetzt aufzuhören. Mach weiter, dann hat sich alles gelohnt.“","options":["Sie stützt sich auf bereits geleistete Stunden, die sich nicht zurückholen lassen. Besser prüft die Frage: „Würde ich heute, ohne diese Vorgeschichte, mit dem Projekt anfangen?“","Sie stützt sich auf ein Gefühl statt auf Zahlen. Besser prüft die Frage: „Wie viele Besucher hatte die Seite im Schnitt pro Monat in den letzten drei Jahren?“","Sie stützt sich auf die Meinung eines einzelnen Mitglieds. Besser prüft die Frage: „Wie viele Mitglieder des Vereins wünschen sich, dass ich mit der Website weitermache?“","Sie stützt sich auf bloßes Durchhalten statt auf Verbesserung. Besser prüft die Frage: „Was müsste ich an der Seite ändern, damit sie endlich mehr Besucher anzieht?“"],"correctIndex":0,"explanation":"Das Argument begründet das Weitermachen mit dem, was schon investiert wurde: „Nach all der Arbeit …“. Das ist ein Red Flag der Versunkene-Kosten-Falle, denn die Begründung ist rückwärtsgewandt statt vorwärtsgewandt. Die Frage „Würde ich heute damit anfangen?“ blendet die Vergangenheit bewusst aus und bewertet ausschließlich die gegenwärtigen und zukünftigen Vor- und Nachteile. Lautet die Antwort „Nein“, ist das ein starkes Signal, dass dich nur die Vorgeschichte hält.","coreRule":"⚡ Frag nicht „Wie viel habe ich schon investiert?“, sondern „Würde ich heute damit anfangen?“","beleg":"Werkstück A.14 (Kernidee; Red Flags)","status":"entwurf","kurz":"Das Argument sagt nur, was schon investiert wurde, und blickt damit zurück. Ob Weitermachen sinnvoll ist, zeigt die Frage, ob du heute ohne die Vorgeschichte anfangen würdest. Antwortest du „Nein“, hält dich vermutlich nur das Bisherige.","prueffrage":"Was würde dem Verein fehlen, wenn die Website ab morgen nicht mehr gepflegt würde, und wer würde es bemerken?","rueckmeldung":[{"option":1,"text":"Zahlen helfen, die Lage einzuschätzen, und Besucherzahlen zählen dazu. Sie beschreiben aber nur die Vergangenheit. Der Fehler liegt in der rückwärtsgewandten Begründung, und die lässt sich mit diesen Zahlen nicht beheben."},{"option":2,"text":"Wie die Mitglieder zur Website stehen, ist durchaus interessant, ändert aber den Fehler nicht. Auch bei breiter Zustimmung bliebe das Argument rückwärtsgewandt, denn es verweist auf geleistete Stunden statt auf künftigen Nutzen."},{"option":3,"text":"Nach vorn zu schauen und Verbesserungen zu suchen, geht in die richtige Richtung. Die Frage setzt aber schon voraus, dass sich das Weitermachen lohnt. Ob es sich heute noch lohnt, prüft sie nicht."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost. OBHDP 35(1), 124–140 (Kopie auf einem Kursserver der Universität Klagenfurt, nicht die Verlagsfassung)","oeffentlich":true,"doi":"10.1016/0749-5978(85)90049-4","url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124–125","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"ab2efdccd5e6fb42"}},{"id":"qx-a2-010","clusterId":"A","werkstueckRef":"A.14","stufe":3,"question":"Wer wendet die Null-Basis-Frage falsch an?","scenario":"Im vierten Jahr deines Medizinstudiums wird die Prüfungsphase hart. Du bist erschöpft und überlegst, ob du dir die sogenannte Null-Basis-Frage stellen solltest: „Würde ich heute, ohne meine bisherige Zeit zu zählen, noch einmal mit diesem Studium anfangen?“ Vier Kommilitonen schildern, wie sie die Frage nutzen.","options":["Jule bricht ab, weil ihr die Prüfungsphase zu anstrengend ist, obwohl sich an Ziel und Aussichten nichts geändert hat.","Tom wägt bei der Frage ausdrücklich auch die künftigen Vor- und Nachteile einer Fortsetzung ab.","Lena stellt die Frage auch einem Bekannten, der seit Jahren Geld in ein Hobbyprojekt steckt und überlegt, ob es sich künftig noch lohnt.","Jonas gibt eine liebgewonnene Gewohnheit auf, weil er auf die Frage ehrlich „Nein“ antwortet."],"correctIndex":0,"explanation":"Die Null-Basis-Frage soll versunkene Kosten und bloße Trägheit ausblenden und prüfen, ob eine Fortsetzung zu den heutigen Umständen und dem heutigen Wissen passt. Sie ist kein Freibrief, bei der ersten Anstrengung aufzugeben. Wer ein langes, schwieriges Vorhaben abbricht, obwohl sich nur die Mühe und nicht die Lage oder das Wissen geändert haben, wendet sie falsch an. Ausdauer ist für langfristige Ziele nötig. Tom, Lena und Jonas nutzen die Frage so, wie sie gedacht ist: Sie beurteilen die Zukunft statt der Vergangenheit und ziehen ehrlich Konsequenzen.","coreRule":"⚡ Der Check prüft veränderte Umstände, er ersetzt nicht Ausdauer bei Anstrengung.","beleg":"Werkstück A.14 (Der Kipppunkt)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Die Null-Basis-Frage prüft, ob eine Fortsetzung zu heutigen Umständen und heutigem Wissen passt. Wer abbricht, nur weil es anstrengender wird, obwohl sich Lage und Wissen nicht geändert haben, verwechselt Mühe mit einem Grund zum Aufhören.","prueffrage":"Was weiß jede Person heute über ihr Vorhaben, das sie zu Beginn noch nicht wusste, und worauf stützt sie ihre Entscheidung?","rueckmeldung":[{"option":1,"text":"Die Frage blendet bereits investierte Zeit und Mühe aus, nicht die Zukunft. Gerade der Blick auf künftige Vor- und Nachteile ist ihr Zweck; wer so abwägt wie Tom, nutzt sie richtig."},{"option":2,"text":"Dass Lena die Frage auf das Hobbyprojekt eines Bekannten überträgt, wirkt zunächst ungewöhnlich. Die Frage zielt dort aber genau auf den künftigen Nutzen und lässt das bisher hineingesteckte Geld außen vor; das ist ihr Sinn."},{"option":3,"text":"Ein ehrliches „Nein“ ernst zu nehmen, ist gewollt, besonders bei Gewohnheiten, die oft nur aus Trägheit weiterlaufen. Dass Jonas Konsequenzen zieht, ist daher kein Fehler, sondern der Zweck der Frage."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost. OBHDP 35(1), 124–140 (Kopie auf einem Kursserver der Universität Klagenfurt, nicht die Verlagsfassung)","oeffentlich":true,"doi":"10.1016/0749-5978(85)90049-4","url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"125","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"65ba6fd81e60baf8"}},{"id":"qx-a2-011","clusterId":"A","werkstueckRef":"A.14","stufe":4,"question":"Eine Frau hängt seit zehn Jahren einer Lehre an, in die sie viel Geld und Lebenszeit gesteckt hat. Ein Freund fragt sie: „Stell dir vor, du hörtest heute zum ersten Mal davon. Würden dich die Beweise, die dir jetzt präsentiert werden, überzeugen, dein Leben dafür umzukrempeln?“ Warum ist diese Frage hier hilfreich, aber für sie zugleich besonders schwer zu beantworten?","options":["Sie prüft die Lehre allein anhand heutiger Beweise ohne Vorgeschichte; ein „Nein“ würde aber heißen, dass sie zehn Jahre lang falsch entschieden hat.","Sie rechnet der Frau vor, wie viel Geld und Zeit sie bereits verloren hat; dieser Verlust lässt sich aber nicht mehr beziffern.","Sie zwingt die Frau, ihre Zweifel vor den anderen Anhängern auszusprechen; das fällt ihr schwer, weil sie Ablehnung fürchtet.","Sie blendet die Vorgeschichte aus; bei Überzeugungen lässt sich diese aber nie von der heutigen Beweislage trennen."],"correctIndex":0,"explanation":"Die Frage löscht die Vergangenheit aus der Entscheidungs-Gleichung: Nur heutige Belege und künftiger Nutzen zählen, bisherige Investitionen nicht mehr. Genau das macht sie stark gegen die Versunkene-Kosten-Falle. Bei lange gehegten Überzeugungen ist sie aber schwer anzuwenden, denn ein „Nein“ hieße, jahrelang an einer schlechten Entscheidung festgehalten zu haben. Das erzeugt kognitive Dissonanz, und um ihr Selbstbild als gute Entscheiderin zu schützen, suchen Menschen in dieser Lage oft lieber Gründe, an der Lehre festzuhalten. Die Frage rechnet dabei keine Verluste vor, muss vor niemandem beantwortet werden, und die Trennung von Vorgeschichte und heutiger Beweislage ist schwer, aber nicht unmöglich.","coreRule":"⚡ Der Null-Basis-Check fragt: „Würde ich heute damit anfangen?“ Bei festgefahrenen Überzeugungen ist er kraftvoll, aber schwer anzuwenden.","beleg":"Werkstück A.14 (Anwendung: festgefahrene Überzeugungen; Verbindungen: Kognitive Dissonanz)","status":"entwurf","scenario":"","kurz":"Die Frage zählt nur heutige Belege und künftigen Nutzen, nicht das bereits Investierte. Schwer fällt die Antwort, weil ein „Nein“ hieße, zehn Jahre lang falsch entschieden zu haben, und dagegen sträubt sich das Selbstbild als kluge Entscheiderin.","prueffrage":"Was soll die Frau nach der Frage ihres Freundes in ihre Antwort einbeziehen, und was ausdrücklich nicht?","rueckmeldung":[{"option":1,"text":"Geld und Zeit stecken tatsächlich in der Lehre. Die Frage rechnet sie aber nicht vor, sie lässt sie bewusst außen vor. Schwer wird die Antwort, weil ein „Nein“ das Selbstbild als kluge Entscheiderin träfe."},{"option":2,"text":"Ablehnung durch andere Anhänger kann real sein. Doch die Frage stellt ihr ein Freund, nicht die Gruppe, und vor den Anhängern muss sie nichts aussprechen. Die Hürde liegt im Inneren: Ein „Nein“ würde ihr Bild als gute Entscheiderin erschüttern."},{"option":3,"text":"Dass die Frage die Vorgeschichte ausblendet, stimmt. Doch Vorgeschichte und heutige Beweislage lassen sich trennen, wenn auch mühsam. Schwer fällt die Antwort, weil ein „Nein“ eine frühere Entscheidung als schlecht entlarven würde."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Harmon-Jones, E.; Mills, J. (2019): An Introduction to Cognitive Dissonance Theory and an Overview of Current Perspectives on the Theory. In: Harmon-Jones, E. (Hg.): Cognitive Dissonance, 2. Aufl., APA (Leseprobe auf apa.org)","oeffentlich":true,"doi":"10.1037/0000135-001","url":"https://www.apa.org/pubs/books/Cognitive-Dissonance-Intro-Sample.pdf","seite":"3; 6–7","abruf":"2026-10-12"},{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost. OBHDP 35(1), 124–140 (Kopie auf einem Kursserver der Universität Klagenfurt, nicht die Verlagsfassung)","oeffentlich":true,"doi":"10.1016/0749-5978(85)90049-4","url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124","abruf":"2026-10-12"},{"typ":"doi","kurz":"Festinger, L. (1957): A Theory of Cognitive Dissonance. Stanford University Press","oeffentlich":false,"doi":"10.1515/9781503620766"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"b507faf2f5b56d72"}},{"id":"qx-a2-012","clusterId":"A","werkstueckRef":"A.15","stufe":1,"question":"Eine Kollegin sagt: „Ein Schluss ist genau dann deduktiv, wenn er vom Allgemeinen zum Besonderen geht, und genau dann induktiv, wenn er vom Besonderen zum Allgemeinen geht.“ Du sollst prüfen, ob das stimmt. Welche Frage trennt deduktive und induktive Schlüsse am besten?","options":["Geht der Schluss von „alle A“ auf einen Einzelfall oder von mehreren Einzelfällen auf alle, also vom Allgemeinen zum Besonderen oder umgekehrt? Daran erkennt man zuverlässig die Schlussart.","Muss die Konklusion bei wahren Prämissen wahr sein (wie bei A, B und C) oder bleibt sie nur wahrscheinlich (wie bei der nächsten Spinne)? Daran erkennt man zuverlässig die Schlussart.","Stimmen die Prämissen, gilt also wirklich „alle A sind B“ und haben die zehn Spinnen acht Beine, oder sind sie falsch? Daran erkennt man zuverlässig die Schlussart.","Stimmt die Konklusion, sind also alle A auch C und hat die nächste Spinne acht Beine, oder widerspricht sie den Tatsachen? Daran erkennt man zuverlässig die Schlussart."],"correctIndex":1,"explanation":"Die Richtungsregel scheitert an beiden Beispielen. Schluss (1) ist deduktiv, bleibt aber zwischen allgemeinen Sätzen. Schluss (2) ist induktiv, bleibt aber bei Einzelfällen, nämlich von bisher untersuchten Spinnen auf die nächste. Verlässlich trennt etwas anderes: Bei einem deduktiven Schluss muss die Konklusion wahr sein, wenn die Prämissen wahr sind. Bei einem induktiven Schluss bleibt sie auch bei wahren Prämissen nur wahrscheinlich, denn die nächste Spinne könnte eine Ausnahme sein. Die Richtung ist deshalb nur eine Faustregel. Die Wahrheit der Prämissen oder der Konklusion gehört zu einer anderen Frage, nämlich ob ein Schluss stichhaltig ist: Auch ein deduktiver Schluss kann falsche Prämissen haben und bleibt dennoch deduktiv, und ein induktiver kann aus wahren Prämissen eine falsche Konklusion ziehen.","coreRule":"⚡ Deduktion zwingt, Induktion macht wahrscheinlich; die Richtung ist nur eine Faustregel.","beleg":"Werkstück A.15 (Kernidee); Fn. ga-deduktion-richtung (Shanahan, Internet Encyclopedia of Philosophy, Abschn. 9)","status":"entwurf","scenario":"Zwei Schlüsse zur Prüfung:\\n(1) „Alle A sind B, alle B sind C, also sind alle A auch C.“\\n(2) „Die zehn Spinnen, die ich bisher untersucht habe, haben acht Beine. Also hat auch die nächste Spinne, die ich finde, acht Beine.“","kurz":"Entscheidend ist, ob die Konklusion bei wahren Prämissen wahr sein muss oder nur wahrscheinlich bleibt. Die Richtung ist bloß eine Faustregel: Schluss (1) bleibt zwischen allgemeinen Sätzen und ist doch deduktiv, Schluss (2) bleibt bei Einzelfällen und ist induktiv.","prueffrage":"Wovon handeln Prämissen und Konklusion in Schluss (1) und in Schluss (2): von allen Fällen einer Art oder von einzelnen Dingen?","rueckmeldung":[{"option":0,"text":"Die Richtung gibt oft einen Hinweis und ist die Faustregel, die die Kollegin nennt. Doch sie versagt an beiden Beispielen: Schluss (1) bleibt zwischen allgemeinen Sätzen, Schluss (2) geht von Einzelfällen auf den nächsten Einzelfall."},{"option":2,"text":"Ob die Prämissen stimmen, ist wichtig, aber für eine andere Frage, nämlich ob ein Schluss stichhaltig ist. Auch ein deduktiver Schluss mit falschen Prämissen bleibt deduktiv, die Schlussart hängt also nicht daran."},{"option":3,"text":"Ob die Konklusion stimmt, klärt die Schlussart nicht: Ein induktiver Schluss kann aus wahren Prämissen eine falsche Konklusion ziehen, und bei falschen Prämissen kann auch ein deduktiver Schluss eine wahre liefern. Zudem lässt sich die nächste Spinne beim Schließen noch nicht prüfen."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shanahan, T.: Deductive and Inductive Arguments. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/deductive-inductive-arguments/","abruf":"2026-10-07"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"37aa8f2684a8a26a"}},{"id":"qx-a2-013","clusterId":"A","werkstueckRef":"A.15","stufe":2,"question":"Was ist an diesem Schluss falsch?","scenario":"Dein Mitbewohner kommt nass nach Hause. Du denkst: „Wenn es regnet, wird man nass. Er ist nass. Also hat es geregnet.“","options":["Er ist ungültig, weil er aus der einen Beobachtung eines nassen Mitbewohners ein Gesetz für alle nass Heimkehrenden ableitet.","Er ist ungültig, weil dein Mitbewohner auch aus anderem Grund nass sein kann und „Es hat geregnet“ daher nicht zwingend folgt.","Er ist ungültig, weil „Es hat geregnet“ nur wiederholt, was „Wenn es regnet, wird man nass“ schon als Behauptung enthält.","Er ist ungültig, weil er aus fehlendem Regen folgert, dass dein Mitbewohner trocken sein müsste (Verneinung des Vorderglieds)."],"correctIndex":1,"explanation":"„Wenn es regnet, wird man nass“ und „Er ist nass“ erlauben nicht den Schluss „Es hat geregnet“: Das ist der klassische Fehlschluss der Bejahung der Folge. Nass kann auch jemand sein, den ein Rasensprenger getroffen hat oder der mit einem Eimer übergossen wurde. Eine gültige Deduktion wäre zwingend; diese ist es nicht. Verallgemeinert wird hier nichts, denn der Schluss geht von einer Regel auf einen Einzelfall. Ein Zirkelschluss liegt auch nicht vor, denn „Es hat geregnet“ steht in der ersten Aussage nicht als Behauptung, sondern nur als Bedingung. Und von ausbleibendem Regen ist gar nicht die Rede.","coreRule":"⚡ Aus „Wenn A, dann B“ und „B“ folgt nicht „A“.","beleg":"Werkstück A.15 (Denkweg 1); Fn. ga-bejahung (Dowden, Internet Encyclopedia of Philosophy, „Affirming the Consequent“)","status":"entwurf","kurz":"Aus „Regen macht nass“ und „er ist nass“ folgt nicht, dass es geregnet hat, denn nass wird man auch durch einen Rasensprenger oder einen Eimer Wasser. Der Fehler: Aus der Folge wird rückwärts auf eine bestimmte Ursache geschlossen.","prueffrage":"Ist die Straße vor der Tür nass, und sind andere, die gerade von draußen kommen, ebenfalls nass?","rueckmeldung":[{"option":0,"text":"Hier wird nichts verallgemeinert: Der Schluss geht von einer Regel auf einen einzelnen Fall, nicht von einem Fall auf ein Gesetz. Ungültig ist er trotzdem, aber aus einem anderen Grund."},{"option":2,"text":"Der Regen kommt in beiden Aussagen vor, das erweckt den Eindruck einer Wiederholung. In der Regel steht „Es hat geregnet“ aber nur als Bedingung, nicht als Behauptung, daher ist es kein Zirkelschluss."},{"option":3,"text":"Ausbleibender Regen kommt im Gedankengang gar nicht vor. Dieser Fehlschluss wäre „Es regnet nicht, also ist er trocken“. Hier wird dagegen aus der Folge „nass“ rückwärts auf den Regen geschlossen."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Affirming the Consequent“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-07"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"f4a440f83e7c937f"}},{"id":"qx-a2-014","clusterId":"A","werkstueckRef":"A.15","stufe":3,"question":"Ein Mitglied einer Gruppe argumentiert: „Alles, was unser Anführer sagt, ist wahr. Der Anführer sagt, die Welt gehe nächste Woche unter. Also geht sie unter.“ Du sollst die Schwachstelle benennen. Wo setzt du an?","options":["Bei der Form des Schlusses: Er schließt von der Folge auf die Bedingung und ist deshalb logisch ungültig.","Bei der Konklusion, denn aus einer Allaussage darf man grundsätzlich keinen Schluss auf einen Einzelfall ziehen.","Bei den Beobachtungen: Der Anführer hat bisher zu wenige Weltuntergänge erlebt, um sich sicher sein zu können.","Bei der ersten Aussage: Der Schluss folgt sauber aus ihr, aber niemand hat belegt, dass der Anführer immer recht hat."],"correctIndex":3,"explanation":"Formal ist der Schluss gültig: Wenn wirklich alles wahr ist, was der Anführer sagt, und er den Weltuntergang ankündigt, dann folgt der Weltuntergang zwingend. Der Aufbau entspricht dem klassischen „Alle Menschen sind sterblich, Sokrates ist ein Mensch, also ist Sokrates sterblich“. Ein gültiger Schluss ist aber nur so verlässlich wie seine Ausgangsaussage, und genau die ist hier unbelegt und in dieser Absolutheit kaum haltbar: Kein Mensch irrt nie. Wer nur die Form prüft, findet keinen Fehler und lässt das Gedankengebäude unangetastet. Die Prüfung muss bei der Prämisse ansetzen: Woher weiß man, dass der Anführer immer recht hat, und gibt es Belege für das Gegenteil, etwa frühere Vorhersagen, die nicht eingetroffen sind? Die anderen Ansätze scheitern: Der Schluss bejaht nicht die Folge, aus einer Allaussage darf man sehr wohl auf Einzelfälle schließen, und von Beobachtungen oder Stichproben ist hier gar nicht die Rede.","coreRule":"⚡ Prüfe bei einem logischen Argument immer auch die Prämissen, nicht nur die Form.","beleg":"Werkstück A.15 (Anwendung: Sekten & Kulte; Red Flags; Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Der Schluss ist formal gültig, trägt aber nur so weit wie seine Ausgangsaussage. Dass der Anführer immer recht hat, ist unbelegt und kaum haltbar. Wer nur die Form prüft, findet keinen Fehler und übersieht die schwache Stelle.","prueffrage":"Wenn die erste und die zweite Aussage stimmen, muss dann auch die dritte stimmen?","rueckmeldung":[{"option":0,"text":"Bei einem Fehlschluss lohnt sich der Blick auf die Form, doch hier wird nicht von der Folge auf die Bedingung geschlossen, sondern von der Bedingung auf die Folge. Die Form ist gültig, der Fehler steckt woanders."},{"option":1,"text":"Die Konklusion ist das Unglaubliche am Satz, deshalb setzt man gern dort an. Aus einer Allaussage darf man aber sehr wohl auf einen Einzelfall schließen, so funktionieren gültige Schlüsse; der Mangel liegt in der Allaussage selbst."},{"option":2,"text":"Behauptungen auf Belege zu prüfen, ist richtig. Von Beobachtungen oder Stichproben ist hier aber keine Rede, und Weltuntergänge lassen sich ohnehin nicht sammeln. Zu prüfen ist die erste Aussage: Woher weiß man, dass der Anführer immer recht hat?"}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shanahan, T.: Deductive and Inductive Arguments. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/deductive-inductive-arguments/","abruf":"2026-10-07"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"b47fe6e40350d3da"}},{"id":"qx-a2-015","clusterId":"A","werkstueckRef":"A.15","stufe":4,"question":"Welche Aussage über den Schluss der Ärztin ist richtig?","options":["Sie schließt auf die beste Erklärung aller Beobachtungen; das Ergebnis ist nur wahrscheinlich und kann durch weitere Befunde widerlegt werden.","Sie verallgemeinert aus vielen beobachteten Fällen eine neue Regel (Induktion); je mehr Fälle vorliegen, desto besser ist die Regel gestützt.","Sie wendet eine bekannte Regel auf diesen Einzelfall an (Deduktion); dabei steckt die Schlussfolgerung schon vollständig in den Prämissen.","Sie überträgt das Ergebnis eines früher behandelten, ähnlichen Patienten auf diesen Fall (Analogie); je ähnlicher, desto stärker der Schluss."],"correctIndex":0,"explanation":"Der Schluss geht von mehreren Beobachtungen auf die Erklärung, die sie am besten verbindet. Er liefert nur Wahrscheinliches: Fieber, Husten und Gliederschmerzen passen auch zu anderen Erkrankungen, und ein weiterer Befund, etwa ein negativer Test, könnte die Diagnose kippen. Man nennt das einen Schluss auf die beste Erklärung; er ist eng verwandt mit dem, was der Philosoph Charles S. Peirce Abduktion nannte. Eine Induktion bildet aus vielen Fällen eine Regel, hier wird aber eine Diagnose für einen einzelnen Patienten gestellt. Bei einer Deduktion läge die Diagnose schon in den Prämissen, hier steht sie aber nirgends fest. Von einem früher behandelten, ähnlichen Patienten ist im Szenario keine Rede.","coreRule":"⚡ Frag bei einem Schluss auf eine Ursache: Ist er zwingend oder nur wahrscheinlich, und welche Erklärung passt zu allen Beobachtungen am besten?","beleg":"Werkstück A.15 (Denkweg 2); Fn. ga-abduktion (Douven, Stanford Encyclopedia of Philosophy, „Abduction“, Abschn. 1.1)","status":"entwurf","scenario":"Eine Ärztin sieht einen Patienten mit Fieber, Husten und Gliederschmerzen. In der Nachbarschaft sind mehrere Grippefälle bekannt. Sie schließt: „Das ist sehr wahrscheinlich Grippe.“","kurz":"Die Ärztin sucht die Erklärung, die Fieber, Husten, Gliederschmerzen und die Grippefälle in der Nachbarschaft am besten verbindet. Das ergibt nur Wahrscheinliches, denn ein negativer Test könnte die Diagnose kippen, anders als bei einem zwingenden Schluss.","prueffrage":"Worauf stützt die Ärztin ihr Urteil im Einzelnen, und was davon hat sie selbst gezählt oder getestet?","rueckmeldung":[{"option":1,"text":"Mehr Fälle stützen eine Regel tatsächlich besser. Hier wird aber keine neue Regel gebildet, sondern für einen einzelnen Patienten die passendste Erklärung gesucht; die Fälle in der Nachbarschaft sind dafür ein Hinweis."},{"option":2,"text":"Bei einer Deduktion folgt der Schluss zwingend aus den Prämissen. Hier gibt es keine Regel, nach der diese Beschwerden immer Grippe bedeuten, und die Ärztin sagt selbst nur „sehr wahrscheinlich“; ein negativer Test könnte die Diagnose kippen."},{"option":3,"text":"Eine Analogie stützt sich auf einen konkreten früheren Vergleichsfall, und je ähnlicher dieser ist, desto stärker der Schluss. Ein solcher Patient kommt im Szenario aber nicht vor; die Ärztin wertet die Beschwerden und die Grippefälle in der Nachbarschaft aus."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Douven, I.: Abduction. Stanford Encyclopedia of Philosophy (überarb. 2025)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/abduction/","abruf":"2026-10-07"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"239c64eca5842aa4"}},{"id":"qx-a2-016","clusterId":"A","werkstueckRef":"A.16","stufe":1,"question":"Zwei Menschen streiten heftig darüber, ob ein bestimmtes Nahrungsergänzungsmittel Krebs heilt. Die eine Person verweist auf mehrere unabhängige Studien, die andere sagt: „Mein Bauchgefühl und der Rat meines Gurus sagen mir, dass es wirkt.“ Der Streit dreht sich im Kreis. Was ist die hilfreichste Reaktion?","options":["Beide tragen weitere Studien und Einzelberichte zum Mittel zusammen, bis die Faktenlage auf einer Seite so erdrückend ist, dass die andere sie nicht mehr ablehnen kann.","Beide klären zuerst, mit welchem Verfahren sich bei einem angeblichen Krebsmittel zuverlässig zwischen Wirkung und Einbildung unterscheiden lässt.","Beide prüfen zuerst, ob hinter den Studien finanzielle Interessen stehen, weil Geldgeber Ergebnisse beeinflussen können, und werten sie danach neu aus.","Beide einigen sich auf eine Mittelposition, etwa dass das Mittel vielleicht ein wenig wirkt, damit sich jede Seite im Ergebnis wiederfinden kann."],"correctIndex":1,"explanation":"Wenn zwei Seiten ihre Behauptungen mit völlig unterschiedlichen Verfahren rechtfertigen (hier: überprüfbare Daten gegen Bauchgefühl und Autorität), führt ein Streit über Einzelfakten selten weiter, denn jede Seite lässt andere Belege gelten. Erst wenn geklärt ist, welches Verfahren die Frage überhaupt entscheiden kann, kommt man weiter. Ob ein Stoff Krebs heilt, lässt sich nur mit öffentlich überprüfbaren Daten, Beobachtungen und Experimenten klären: Intuition kann helfen einzuschätzen, ob man einer Person vertraut, aber nicht, ob ein Molekül einen Tumor heilt. Mehr Studien und Berichte zu sammeln ändert daran nichts, solange das Verfahren strittig ist. Die Geldgeber von Studien zu prüfen ist sonst ein guter Schritt, hier aber sind die Studien als unabhängig beschrieben, und die andere Seite lässt Studien ohnehin nicht als Maßstab gelten. Und eine Mittelposition hilft bei einer prüfbaren Sachfrage nicht, weil Entgegenkommen nicht entscheidet, ob ein Stoff wirkt.","coreRule":"⚡ Frag nicht nur „Was weißt du?“, sondern „Woher weißt du es?“ Wer über die Methode der Wahrheitsfindung streitet, streitet nicht mehr im Kreis.","beleg":"Werkstück A.16 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Der Streit kommt erst voran, wenn beide klären, womit sich die Frage überhaupt entscheiden lässt. Solange eine Seite Daten, die andere Bauchgefühl und Autorität gelten lässt, ändern auch mehr Belege nichts.","prueffrage":"Was hat der bisherige Austausch von Argumenten bewirkt, und woran ist er jedes Mal hängengeblieben?","rueckmeldung":[{"option":0,"text":"Mehr Studien zu sammeln wirkt gründlich. Wer Bauchgefühl und Autorität als Maßstab gelten lässt, wird aber auch erdrückend viele Daten beiseiteschieben. Solange das Verfahren strittig ist, ändert zusätzliches Material nichts."},{"option":2,"text":"Geldgeber zu prüfen ist sonst ein guter Schritt, weil Finanzierung Ergebnisse färben kann. Hier sind die Studien aber als unabhängig beschrieben, und das Problem liegt tiefer: Die andere Seite lässt Studien ohnehin nicht als Maßstab gelten."},{"option":3,"text":"Eine Mitte zu suchen wirkt fair und entschärft den Streit. Ob ein Stoff Krebs heilt, ist aber eine prüfbare Sachfrage, und die klärt sich nicht durch Entgegenkommen. Ein „vielleicht ein wenig“ wäre eine Behauptung, die niemand belegt hat."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-07"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"3449e15b53685717"}},{"id":"qx-a2-017","clusterId":"A","werkstueckRef":"A.16","stufe":2,"question":"Was ist jetzt der klügste nächste Schritt?","scenario":"Du diskutierst seit einer Stunde mit einem Bekannten über einen Verschwörungsmythos. Du bringst Studien, er winkt ab: „Die gehören doch alle zum System.“ Jede neue Quelle wird auf dieselbe Weise abgelehnt.","options":["Die aussagekräftigste Studie heraussuchen und ihre Methode Schritt für Schritt erklären, damit er die Belege endlich versteht und anerkennt.","Euch auf eine Mittelposition einigen, etwa dass an dem Mythos ein wahrer Kern sein könnte, damit das Gespräch freundlich endet.","Zuerst über die Methode sprechen: Welches Verfahren halten wir beide in dieser Frage für das verlässlichste, und was würde ihn umstimmen?","Nachzeichnen, wer den Mythos zuerst verbreitet hat und welche Interessen dahinterstanden, damit er die Herkunft der Behauptung einordnen kann."],"correctIndex":2,"explanation":"Wenn jede Gegenevidenz von vornherein als Teil der Verschwörung gilt, können weitere Fakten nichts bewirken: Ihr benutzt zwei verschiedene Verfahren, um zwischen wahr und falsch zu unterscheiden. Solange das nicht geklärt ist, redet ihr aneinander vorbei, weil jede Seite andere Beweise gelten lässt. Sinnvoll ist deshalb, zuerst die Methode zu besprechen: Wie lässt sich in dieser Art von Frage am verlässlichsten die Wahrheit herausfinden, und unter welchen Umständen würde er seine Meinung ändern? Eine einzelne Studie genauer zu erklären hilft nicht, denn er zweifelt nicht am Verständnis, sondern lehnt die Quellen als Gruppe ab. Eine Mittelposition passt nicht, weil es bei einer Sachfrage kein halbes Wahr gibt. Und die Herkunft des Mythos zu erzählen liefert nur weiteren Stoff, den er auf dieselbe Weise abtun würde.","coreRule":"⚡ Wenn Fakten nichts bewirken, klärt zuerst die Methode der Wahrheitsfindung.","quote":"","quoteLabel":"","beleg":"Werkstück A.16 (Anwendung; Red Flags; Anti-Denkmuster)","status":"entwurf","kurz":"Wenn jede Gegenevidenz schon als Teil der Verschwörung gilt, bewirken weitere Fakten nichts, denn ihr nutzt verschiedene Verfahren für wahr und falsch. Klärt deshalb zuerst die Methode und was ihn umstimmen würde.","prueffrage":"Wie hat er auf jede bisher genannte Studie reagiert, und hat sich daran im Lauf der Stunde etwas geändert?","rueckmeldung":[{"option":0,"text":"Eine gut erklärte Methode wirkt wie der Schlüssel zum Verständnis. Er zweifelt aber nicht am Verständnis, sondern lehnt Studien als Gruppe ab; auch die beste würde auf dieselbe Weise abgetan."},{"option":1,"text":"Ein freundliches Ende ist ein guter Wunsch. Bei einer Sachfrage gibt es aber kein halbes Wahr, und der Kompromiss ließe die zwei verschiedenen Verfahren unberührt, mit denen ihr wahr und falsch unterscheidet."},{"option":3,"text":"Wer den Ursprung eines Mythos kennt, kann ihn oft besser einordnen. Hier liefert die Herkunft aber nur weiteren Stoff, den er mit „gehört zum System“ genauso abtun würde wie die Studien."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-07"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"b1327fd91946ba97"}},{"id":"qx-a2-018","clusterId":"A","werkstueckRef":"A.16","stufe":3,"question":"Du steigst in ein Flugzeug und vertraust der Pilotin, ohne ihre Berechnungen nachzuprüfen. Ein Bekannter sagt: „Das ist doch genauso unkritisch wie der blinde Glaube an einen Guru. Wer wirklich rational ist, vertraut nur dem, was er selbst überprüft hat.“ Was ist an seinem Einwand fehlerhaft?","options":["Er setzt jedes Vertrauen in Fachleute mit blindem Guruglauben gleich, obwohl entscheidend ist, ob die Quelle nachprüfbar, korrigierbar und für die Frage geeignet ist (falsche Analogie).","Er beruft sich auf das bloße Ansehen von Fachleuten, ohne zu prüfen, ob die Pilotin für diese Frage tatsächlich Fachwissen hat, und stützt sich nur auf deren Ruf (Autoritätsargument).","Er malt eine unbelegte Kette von Folgen aus: Wer der Pilotin vertraue, werde bald jedem Sektenführer blind folgen, und am Ende stehe vollständige Gefolgschaft (Dammbruchargument).","Er schließt von der Verbreitung einer Haltung auf ihre Richtigkeit: Weil die meisten Fluggäste der Pilotin vertrauen, müsse dieses Vertrauen gerechtfertigt sein (Mehrheitsargument)."],"correctIndex":0,"explanation":"Vertrauen ohne eigene Nachprüfung ist nicht automatisch ein Denkfehler. Einer erfahrenen Pilotin vertrauen wir, weil ihr Können geprüft wurde, ihre Arbeit kontrolliert wird und Fehler auffallen und korrigiert werden können. Beim Guru gilt dagegen oft: Zweifel ist verboten, und widersprüchliche Evidenz wird umgedeutet, bis sie wieder zur Lehre passt. Der Bekannte gleicht beide Fälle einander an, obwohl sie sich in genau diesen Merkmalen unterscheiden. Entscheidend ist also, ob die Quelle nachprüfbar und korrigierbar ist und ob die Methode zur Art der Frage passt. Problematisch wird es dort, wo Bauchgefühl oder unprüfbare Autorität Sachfragen beantworten sollen, etwa ob ein Molekül ein Krebsgeschwür heilt oder ob Impfungen sicher sind. Der Bekannte beruft sich dabei weder auf eine Autorität noch auf die Mehrheit. Auch eine Kette immer größerer Folgen malt er nicht aus.","coreRule":"⚡ Vertrauen in Autorität und Intuition ist nicht per se falsch: Es kommt darauf an, ob die Quelle nachprüfbar und korrigierbar ist und zur Art der Frage passt. Fragen, die nur Daten beantworten, entscheiden weder Gefühl noch Guru.","beleg":"Werkstück A.16 (Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Der Einwand gleicht zwei verschiedene Fälle an: Der Pilotin vertraust du, weil ihr Können geprüft wird und Fehler auffallen und korrigiert werden können, beim Guru ist Zweifel verboten. Entscheidend ist, ob die Quelle nachprüfbar und korrigierbar ist.","prueffrage":"Wie viel von dem, was der Bekannte täglich für wahr hält, hat er selbst überprüft?","rueckmeldung":[{"option":1,"text":"Hier liegt eine Verwechslung vor: Der Bekannte stützt sich gar nicht auf eine Autorität, er lehnt Vertrauen in Fachleute ab. Wahr ist, dass Fachwissen zur konkreten Frage passen muss, aber der Fehler liegt in der Gleichsetzung zweier Fälle."},{"option":2,"text":"Von Folgen, die immer größer werden, ist in seinem Einwand keine Rede. Er setzt zwei Fälle gleich, die Pilotin und den Guru, statt eine Entwicklung bis zur Gefolgschaft auszumalen. Eine Eskalation wird nirgends behauptet."},{"option":3,"text":"Auf die Zahl der Vertrauenden stützt sich hier niemand. Das Vertrauen in die Pilotin gründet sich laut Erklärung auf geprüftes Können und kontrollierte, korrigierbare Arbeit. Dass viele ihr vertrauen, ist weder sein Argument noch der Grund für das Vertrauen."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Epistemological Problems of Testimony (2021)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/testimony-episprob/","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-07"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"3dd563732eef4037"}},{"id":"qx-a2-019","clusterId":"A","werkstueckRef":"A.16","stufe":4,"question":"Welche Frage deckt am besten auf, ob die Behauptung des Anbieters wissenschaftlich begründet ist oder nur so klingt?","options":["Wie anerkannt ist der Entwickler der Methode in seinem Fachgebiet, und seit wann ist er dort tätig?","Wie viele Kundinnen und Kunden haben die Methode angewendet, und wie zufrieden waren sie im Durchschnitt?","Wie schlüssig und widerspruchsfrei erklärt der Anbieter, warum die Methode wirken soll, und wie fachkundig klingt das?","Unter welchen Ergebnissen wäre die Methode widerlegt, und kann das jemand unabhängig vom Anbieter nachprüfen?"],"correctIndex":3,"explanation":"Entscheidend ist die Methode der Begründung, nicht das Vokabular. Der Anbieter ahmt die Sprache der Wissenschaft nach (Studien, Fachjargon), stützt sich aber auf Autorität (den Entwickler) und Intuition (die Erlebnisberichte der Kunden). Eine wissenschaftliche Begründung erkennt man an zwei Merkmalen: Sie ist falsifizierbar, man kann also sagen, welches Ergebnis sie widerlegen würde, und sie ist öffentlich überprüfbar, jeder kann die Prüfung wiederholen. Der Ruf eines Entwicklers ersetzt keine Prüfung, denn Ansehen ist Autorität und kein Beleg. Viele zufriedene Berichte sind Anekdoten, die jede Behauptung stützen können. Und eine schlüssig und fachkundig klingende Erklärung zeigt nur, dass der Anbieter die Sprache der Wissenschaft beherrscht, nicht dass die Methode wirkt.","coreRule":"⚡ Prüfe nicht den Jargon, sondern auf welcher Methode eine Behauptung wirklich ruht.","beleg":"Werkstück A.16 (Anwendung: Pseudowissenschaft; Weg 1 bis 3; Prinzipien Falsifizierbarkeit und öffentliche Überprüfbarkeit)","status":"entwurf","scenario":"Ein Anbieter wirbt für seine „Energie-Methode“. Er verweist auf „Studien“ und benutzt viel Fachjargon. Fragt man, warum die Methode wirkt, antwortet er: „So hat es der Entwickler der Methode festgelegt, und unsere Kundinnen und Kunden berichten begeistert von ihren Erfahrungen.“","kurz":"Wissenschaftlich begründet ist eine Behauptung, wenn sie sagt, was sie widerlegen würde, und andere die Prüfung unabhängig wiederholen können. Der Anbieter stützt sich dagegen auf Autorität und Erlebnisberichte und ahmt nur die Sprache der Wissenschaft nach.","prueffrage":"Welche Gründe nennt der Anbieter, wenn man ihn nach der Wirkung fragt, und woher stammt jeder davon?","rueckmeldung":[{"option":0,"text":"Wie anerkannt der Entwickler ist, sagt etwas über den Mann, aber nichts über die Methode. Ansehen ist Autorität und kein Beleg: Auch ein angesehener Entwickler muss zeigen, wie man seine Behauptung prüfen könnte."},{"option":1,"text":"Dass viele zufrieden sind, kann stimmen, und diese Erfahrungen sind echt. Erlebnisberichte sind aber Anekdoten ohne Vergleich: Sie können jede Behauptung stützen und zeigen nicht, dass die Methode die Ursache war."},{"option":2,"text":"Eine Erklärung, die in sich stimmig und fachkundig klingt, macht Eindruck. Sie zeigt aber nur, dass jemand die Fachsprache beherrscht. Ob die Methode wirkt, entscheidet sich erst an einer Prüfung, die widerlegen könnte."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-07"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"561df50db7d11725"}},{"id":"qx-a2-020","clusterId":"A","werkstueckRef":"A.17","stufe":1,"question":"Eine Studentin sagt: „Ich hab den Text zweimal gelesen, aber ich kapier ihn nicht, ich bin einfach schlecht in Statistik.“ Was würde jemand mit gutem Blick auf das eigene Denken stattdessen tun?","options":["Sie fragt sich, an welcher Stelle des Statistik-Textes sie den Faden verloren hat, und sucht gezielt eine einfachere Erklärung genau dafür.","Sie liest den Statistik-Text ein drittes Mal von vorn, diesmal langsamer und mit Stift in der Hand, weil Wiederholung das Verständnis festigt.","Sie legt fest, wie viele Seiten des Statistik-Textes sie pro Tag liest, und trägt feste Lesezeiten ein, damit sie den Stoff rechtzeitig schafft.","Sie vergleicht ihr Lesetempo mit dem ihrer Kommilitonen und übt gezielt schnelleres Lesen, weil sie sich im Vergleich zu langsam fühlt."],"correctIndex":0,"explanation":"„Ich hab’s nicht verstanden“ ist ein pauschales Urteil, aus dem sich nichts ableiten lässt. Wer das eigene Verstehen überwacht, benennt, wo genau es abgerissen ist, und sucht gezielt eine andere Quelle für genau diesen Abschnitt. Nochmaliges Lesen von vorn hilft, wenn man einen Text nur überflogen hat, hier hat sie ihn aber schon zweimal gelesen, ohne die Stelle zu finden. Zeitplanung regelt, wie viel sie liest, nicht ob sie es versteht. Und schnelleres Lesen löst kein Verständnisproblem, denn sie scheitert nicht am Tempo.","coreRule":"⚡ Gutes Denken über das eigene Denken bedeutet: genau benennen, wo es hakt, und dann die Strategie wechseln, statt sich pauschal als „schlecht darin“ abzustempeln.","quote":"","quoteLabel":"","beleg":"Werkstück A.17 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Aus „Ich bin schlecht in Statistik“ lässt sich nichts ableiten. Wer sein Verstehen im Blick hat, findet die Stelle, an der der Faden riss, und holt sich dafür gezielt eine andere Erklärung, statt sich pauschal zu verurteilen.","prueffrage":"Was hat die Studentin bisher unternommen, um den Text zu verstehen, und was hat sich zwischen erstem und zweitem Lesen geändert?","rueckmeldung":[{"option":1,"text":"Ein dritter Durchgang mit Stift wirkt gründlich, und Wiederholung hilft, wenn man einen Text nur überflogen hat. Nach zwei Lesungen ohne Fund der Lücke bringt dasselbe von vorn aber wenig; es fehlt die Suche nach der Stelle, an der es hakt."},{"option":2,"text":"Feste Lesezeiten sorgen dafür, dass der Stoff rechtzeitig gelesen wird. Das regelt aber nur die Menge. Ob der Text verstanden wird, bleibt davon unberührt, und genau das ist hier das Problem."},{"option":3,"text":"Wer sich langsam fühlt, vermutet leicht ein Tempoproblem. Sie hat den Text aber zweimal gelesen und scheitert am Verstehen, nicht an der Geschwindigkeit; schnelleres Lesen würde die Lücke nicht schließen."}],"familie":"wissensgrenze-benennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"O’Leary, A. J.; Sloutsky, V. M.: Carving metacognition at its joints: Protracted development of component processes. Child Development 88(3), 1015–1032 (PMC)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5397377/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Flavell, J. H. (1979): Metacognition and Cognitive Monitoring: A New Area of Cognitive-Developmental Inquiry. American Psychologist 34, 906–911","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"af7bfee679dcbbbd"}},{"id":"qx-a2-021","clusterId":"A","werkstueckRef":"A.17","stufe":2,"question":"Du liest einen Fachtext und verlierst im Abschnitt über Statistik den Faden. Welche Reaktion nutzt das Nachdenken über das eigene Lernen am besten?","scenario":"Du arbeitest dich durch einen Fachtext. Der Anfang war klar, doch im Abschnitt über Statistik kommst du nicht mehr mit. Du hast noch eine knappe Stunde Zeit.","options":["Du teilst die knappe Stunde in feste Zeitblöcke ein und liest in jedem Block ein festes Stück des Textes weiter.","Du benennst, bis wohin im Statistik-Abschnitt du folgen konntest, und gehst genau diesen Abschnitt noch einmal gezielt an.","Du beginnst den Text noch einmal von vorn und liest ihn Absatz für Absatz, bis du bei jeder Stelle sicher bist.","Du liest zügig bis zum Textende weiter, weil sich die Statistik später aus dem Zusammenhang erklären könnte, und prüfst erst am Ende."],"correctIndex":1,"explanation":"Wer sein eigenes Verständnis überwacht, merkt nicht nur, dass etwas nicht klappt, sondern kann genau sagen, wo es aussetzt. Erst diese Genauigkeit erlaubt eine passende Gegenmaßnahme: den fraglichen Abschnitt noch einmal ansehen oder eine einfachere Quelle suchen. Und Weiterlesen ohne Prüfung setzt nicht an der Stelle an, an der das Verständnis tatsächlich abbrach.","coreRule":"⚡ Benenne genau, wo dein Verständnis endet, und passe dann deine Strategie an.","beleg":"Werkstück A.17 (Anwendung: Beim Lernen & Verstehen; Red Flags)","status":"entwurf","kurz":"Wer genau benennen kann, wo das Verständnis aussetzt, kann gezielt gegensteuern. Bloßes Gefühl, nicht mitzukommen, führt dagegen zu ungezielten Reaktionen wie Neustart, Zeitplan oder Weiterlesen.","prueffrage":"Wie viel Zeit bleibt dir, und für welchen Teil des Textes brauchst du sie wirklich?","rueckmeldung":[{"option":0,"text":"Feste Zeitblöcke helfen, die Stunde zu nutzen. Sie sagen aber nichts darüber, ob du den Stoff verstanden hast, und lassen die Stelle unberührt, an der du den Faden verloren hast."},{"option":2,"text":"Gründlichkeit ist an sich gut. Doch ein Neustart verbraucht die knappe Stunde auch auf Abschnitte, die du längst verstanden hast, statt dort anzusetzen, wo es hakt."},{"option":3,"text":"Manchmal klärt sich Unklares im weiteren Text. Ohne Prüfung bleibt aber offen, ob das passiert, und die Lücke wächst eventuell, weil du nicht dort ansetzt, wo das Verständnis abbrach."}],"familie":"wissensgrenze-benennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"O’Leary, A. J.; Sloutsky, V. M.: Carving metacognition at its joints: Protracted development of component processes. Child Development 88(3), 1015–1032 (PMC)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5397377/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Flavell, J. H. (1979): Metacognition and Cognitive Monitoring: A New Area of Cognitive-Developmental Inquiry. American Psychologist 34, 906–911","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"99761592859dd3ee"}},{"id":"qx-a2-022","clusterId":"A","werkstueckRef":"A.17","stufe":3,"question":"Was erklärt das am besten?","options":["Ihre Selbstprüfung im Spiel ist zu ungenau: Sie müsste vor jedem Wurf gründlicher und länger über ihre Strategie nachdenken, dann würde die Unsicherheit verschwinden.","Die Selbstprüfung kommt am falschen Ort und zur falschen Zeit: Wo Sekundenbruchteile zählen, kostet sie Reaktionszeit, und die Torhüterin zögert.","Im Spiel bricht ihre Konzentration unter dem Druck des Spielstands ein (Leistungsangst), und das hat mit der Selbstprüfung nichts zu tun.","Die Erkenntnisse aus Training, Pause und Videoanalyse lassen sich nicht auf die Spielsituation übertragen, daher zögert sie bei jedem Wurf."],"correctIndex":1,"explanation":"Nachdenken über das eigene Denken (Fachbegriff: Metakognition) kann in Situationen hinderlich sein, die schnelle, intuitive Entscheidungen erfordern; Sport und Notfälle sind typische Beispiele. Solche Selbstprüfung ist langsam und anstrengend: Wo Sekundenbruchteile zählen, kostet sie Zeit, man analysiert, statt zu reagieren, und zögert. Das Werkzeug an sich bleibt nützlich, es kommt auf den passenden Ort und Zeitpunkt an, etwa im Training oder in der Pause. Noch mehr Nachdenken im Spiel würde das Zögern verstärken, denn gerade die Prüfung vor jedem Wurf kostet Zeit. Mit Wettkampfdruck lässt sich die Unsicherheit nicht erklären, denn von Druck ist im Szenario keine Rede; sie entsteht, seit sie auch im Spiel jeden Wurf prüft. Und Training und Videoanalyse bringen ihr ja nachweislich viel, es fehlt also nicht an Übertragbarkeit, sondern am Zeitpunkt der Prüfung.","coreRule":"⚡ Selbstprüfung gehört in ruhige Momente; wo Sekundenbruchteile zählen, zählt das Handeln.","beleg":"Werkstück A.17 (Der Kipppunkt; Anwendung)","status":"entwurf","scenario":"Die Torhüterin einer Handballmannschaft will nach jedem Gegentor ihre Entscheidungen verbessern. Im Training, in der Halbzeitpause und bei der Videoanalyse prüft sie ihre Entscheidungen gründlich, und dort bringt ihr das viel. Inzwischen prüft sie auch im Spiel bei jedem Wurf zuerst, was sie gerade denkt und fühlt, welche Strategie sie nutzt und ob die zu ihr passt. Das Team kassiert viele Tore, sie wirkt unsicher.","quote":"","quoteLabel":"","kurz":"Selbstprüfung ist langsam, und im Spiel zählen Sekundenbruchteile: Wer vor jedem Wurf erst analysiert, reagiert zu spät und zögert. Das Werkzeug taugt, aber nur zur passenden Zeit, etwa im Training oder in der Pause.","prueffrage":"Wie hat die Torhüterin gehalten, bevor sie im Spiel mit dieser Selbstprüfung begann, und wie seitdem?","rueckmeldung":[{"option":0,"text":"Gründliche Selbstprüfung bringt ihr ja nachweislich viel, deshalb liegt der Ausbau nahe. Im Spiel kostet aber gerade die Prüfung vor jedem Wurf Zeit; mehr davon würde das Zögern eher verstärken als beheben."},{"option":2,"text":"Druck beim Spielstand kann Sportler tatsächlich aus der Bahn werfen. Im Szenario ist davon aber keine Rede: Die Unsicherheit tritt auf, seit sie im Spiel jeden Wurf prüft. Das spricht für die Prüfung als Ursache, nicht gegen sie."},{"option":3,"text":"Dass Gelerntes im Spiel nicht ankommt, wäre ein plausibler Grund für Unsicherheit. Training, Pause und Video bringen ihr aber nachweislich viel; es fehlt nicht an Übertragbarkeit, sondern am Zeitpunkt der Prüfung."}],"familie":"wissensgrenze-benennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Worthy, D. A.; Markman, A. B.; Maddox, W. T. (2009): Choking and excelling under pressure in experienced classifiers. Attention, Perception & Psychophysics 71(4), 924–935 (PMC)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2708085/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"450","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"4c10b89875a6ee90"}},{"id":"qx-a2-023","clusterId":"A","werkstueckRef":"A.18","stufe":1,"question":"Zwei Personen reagieren auf eine neue Meldung: „Ein Präparat soll Erkältungen halbieren.“ Person A sagt: „Zeig mir eine kontrollierte Studie, die das belegt. Bis dahin halte ich die Aussage für unbewiesen. Wenn die Daten stimmen, ändere ich meine Meinung.“ Person B sagt: „Das ist Unsinn, das stimmt nie. Egal, welche Studie du bringst: Die ist gekauft.“ Was unterscheidet die beiden Haltungen im Kern?","options":["A macht sein Urteil von einer kontrollierten Studie abhängig und würde es ändern; B hat das Ergebnis schon festgelegt und wertet jede Studie vorab als gekauft ab.","A zeigt Autoritätsgläubigkeit, weil er Studien über sein eigenes Urteil stellt; B denkt selbstständig und lässt sich von Studien nichts vorschreiben.","A und B unterscheiden sich nur im Ton: Beide halten die Meldung für unbewiesen, B drückt seine Skepsis bloß schroffer aus als A.","A vertraut der Meldung, solange keine Studie sie widerlegt; B misstraut ihr, solange keine Studie sie belegt; beide suchen nur Bestätigung ihrer Haltung."],"correctIndex":0,"explanation":"Person A legt fest, was sie überzeugen würde, und hält ihr Urteil bis dahin zurück. Das ist eine Methode: Die Stärke der Überzeugung richtet sich nach der Stärke der Belege. Person B hat die Schlussfolgerung schon gefasst und arbeitet sich rückwärts: Jeder widersprechende Beleg wird im Voraus abgewertet, damit das Ergebnis nicht gefährdet wird. Eine solche Position ist gegen Evidenz immun und deshalb keine Prüfung, sondern die Verteidigung eines fertigen Ergebnisses.","coreRule":"⚡ Ein Skeptiker prüft mit offener Methode und kann sagen, was ihn umstimmen würde; ein Leugner verteidigt ein fertiges Ergebnis.","quote":"","quoteLabel":"","beleg":"Werkstück A.18 (Kernidee; Kontext & Tiefe); Fn. ga-leugnung (Hansson 2017, Studies in History and Philosophy of Science 63, S. 39–47)","status":"entwurf","scenario":"","kurz":"A legt fest, welcher Beleg ihn überzeugen würde, und hält sein Urteil bis dahin offen. B steht mit seinem Ergebnis schon fest und wertet jede Studie vorab ab, sodass ihn keine Evidenz mehr erreichen kann. Das ist der Unterschied zwischen Prüfen und Verteidigen.","prueffrage":"Was sagt jede der beiden Personen über eine Studie, die es noch gar nicht gibt?","rueckmeldung":[{"option":1,"text":"Dass A sich an Studien orientiert, kann nach Unterordnung aussehen. Er macht aber nur sein Urteil von Belegen abhängig und bleibt offen, während B sich von keiner Studie mehr bewegen lässt und deshalb gerade nicht frei denkt."},{"option":2,"text":"Beide lehnen die Meldung zunächst ab, daher wirkt der Unterschied wie bloße Schärfe im Ton. A hält sie aber für unbewiesen und änderte seine Meinung durch eine gute Studie, B hält sie für falsch und nähme selbst die beste Studie nicht an."},{"option":3,"text":"A nennt keine Gewissheit, sondern hält die Meldung für unbewiesen, statt ihr bis zu einer Widerlegung zu glauben, und er sagt, welche Daten ihn überzeugen würden. Nur bei B stimmt, dass er bloß seine Haltung bestätigt sehen will."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-07"},{"typ":"doi","kurz":"Hansson, S. O. (2017): Science denial as a form of pseudoscience. Studies in History and Philosophy of Science Part A 63, 39–47","oeffentlich":false,"doi":"10.1016/j.shpsa.2017.05.002"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"3d624004b3917d78"}},{"id":"qx-a2-024","clusterId":"A","werkstueckRef":"A.18","stufe":2,"question":"Welche Frage prüft seine Behauptung am besten?","scenario":"Auf einer Feier erzählt dir ein Astrologe begeistert, die Stellung der Planeten sage seit Jahren zuverlässig voraus, was im Leben seiner Kundschaft geschieht.","options":["„Kannst du mir Fälle nennen, in denen deine Vorhersagen eingetroffen sind, und wie viele waren es?“","„Welche Ausbildung hast du, und in welchen Medien wurdest du als Experte zitiert?“","„Wie wirken die Planeten auf mich, und gibt es Tests mit Treffern über dem Zufall?“","„Wie lange gibt es die Astrologie schon, und in wie vielen Kulturen wird sie bis heute genutzt?“"],"correctIndex":2,"explanation":"Eine Behauptung wird geprüft, indem man fragt, welcher Mechanismus sie erklären soll und ob kontrollierte Studien zeigen, dass die Vorhersagen besser sind als reiner Zufall. Einzelne eingetroffene Vorhersagen sind kein Beleg, denn ohne Vergleich mit dem Zufall lässt sich nicht sagen, ob die Treffer mehr sind als Glück. Fragen nach Ausbildung oder Medienauftritten prüfen die Person, nicht die Behauptung. Alter und Verbreitung einer Praxis sagen nichts darüber, ob sie wirkt. Astrologie hat in kontrollierten Tests bisher keine Treffer über dem Zufall gezeigt. Die Frage nach solchen Tests lässt das Gegenüber selbst nachsehen, statt es nur abzuwerten.","coreRule":"⚡ Frag nach Mechanismus und kontrollierten Tests, nicht nach dem Ruf des Behauptenden.","beleg":"Werkstück A.18 (Anwendung: Gegenüber Pseudowissenschaft & Esoterik; Red Flags)","status":"entwurf","kurz":"Eine Behauptung prüft man, indem man nach einem erklärenden Mechanismus und nach kontrollierten Tests fragt, deren Treffer über dem Zufall liegen. Einzelne eingetroffene Vorhersagen, Titel oder Alter beweisen nichts, weil sie keinen Vergleich mit dem Zufall liefern.","prueffrage":"Welche Vorhersagen hat er in den letzten Jahren gemacht, und wurden sie aufgeschrieben, bevor sich zeigte, ob sie eintreffen?","rueckmeldung":[{"option":0,"text":"Nach konkreten Fällen zu fragen, wirkt greifbar und ist besser als blindes Vertrauen. Gezählt werden aber nur die Treffer, ohne Fehlschläge und ohne Vergleich mit dem Zufall. Bei vagen Vorhersagen trifft immer etwas ein, auch ohne Wirkung."},{"option":1,"text":"Ausbildung und Medienauftritte lassen sich leicht erfragen und klingen nach Seriosität. Sie sagen aber etwas über die Person und nicht darüber, ob die Vorhersagen besser sind als der Zufall. Die Behauptung selbst bleibt damit ungeprüft."},{"option":3,"text":"Alter und weite Verbreitung sind überprüfbare Tatsachen und beeindrucken leicht. Ob eine Praxis wirkt, sagt das jedoch nicht: Auch Irrtümer können sehr alt sein und in vielen Kulturen gepflegt werden."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Dean, G.; Kelly, I. W. (2003): Is astrology relevant to consciousness and psi? (Nachdruck auf astrology-and-science.com)","oeffentlich":true,"url":"https://astrology-and-science.com/D-psia1.htm","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Dean, G.; Kelly, I. W. (2003): Is astrology relevant to consciousness and psi? Journal of Consciousness Studies 10(6–7), 175–198","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"aeaf8eb109ef871e"}},{"id":"qx-a2-025","clusterId":"A","werkstueckRef":"A.18","stufe":3,"question":"Jemand sagt: „Es gibt keine absolute Gewissheit, also ist die Kugelgestalt der Erde ebenso gut begründet wie die Scheibe.“ Was ist an diesem Schluss fehlerhaft?","options":["Er fordert zu Recht Belege für beide Seiten, wendet diese Forderung aber nur auf die Kugelgestalt an.","Er behandelt Quellen und Motive der Wissenschaft pauschal als verdächtig, statt Belege zu prüfen.","Er folgert aus fehlender absoluter Gewissheit, dass alle Behauptungen gleich gut belegt sind.","Er verlässt sich auf eine einzelne Autorität, statt die Behauptung selbst zu prüfen."],"correctIndex":2,"explanation":"Dass es keine absolute Gewissheit gibt, stimmt, aber daraus folgt nicht, dass alle Behauptungen gleich unsicher wären. Es gibt verlässliche Methoden, um gut begründetes, wenn auch vorläufiges Wissen zu gewinnen, und die Stärke einer Überzeugung sollte der Stärke der Belege entsprechen. Für die Kugelgestalt der Erde sprechen unabhängige Belege aus vielen Richtungen, etwa Satellitenbilder, Erdumrundungen und der runde Erdschatten bei Mondfinsternissen; für die Scheibe gibt es nichts Vergleichbares. Beide gleichzusetzen ist kein Skeptizismus, sondern gibt das Prüfen auf: Hier kippt der Zweifel in die Haltung, dass gar kein Wissen möglich sei. Ein echter Skeptiker fragt, welche Belege jeweils vorliegen, und stuft sein Vertrauen danach ab.","coreRule":"⚡ Skeptizismus misst Überzeugung an der Stärke der Belege; Gleichmacherei ist keiner.","beleg":"Werkstück A.18 (Der Kipppunkt; Kontext & Tiefe: Proportionalität)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Dass es keine absolute Gewissheit gibt, stimmt, macht aber nicht alle Behauptungen gleich unsicher: Entscheidend ist die Stärke der Belege, und die ist bei der Kugelgestalt ungleich größer. Wer alles gleichsetzt, ist nicht skeptisch, sondern gibt das Prüfen auf.","prueffrage":"Welche Belege lassen sich für jede der beiden Behauptungen tatsächlich nennen, und wie viele sind es?","rueckmeldung":[{"option":0,"text":"Belege von beiden Seiten zu verlangen, ist grundsätzlich fair. Im Satz steht aber keine einseitige Forderung: Er stellt beide Behauptungen gleich, weil nichts absolut gewiss sei. Der Fehler liegt in diesem Schluss, nicht in einem Doppelstandard."},{"option":1,"text":"Quellen und Motive kritisch anzusehen, gehört zum guten Prüfen, und manchmal wird es übertrieben. Der Satz greift aber weder Quellen noch Motive an, sondern schließt allein aus fehlender absoluter Gewissheit auf Gleichwertigkeit."},{"option":3,"text":"Selbst zu prüfen, statt einer einzelnen Autorität zu folgen, ist ein guter Grundsatz. Hier beruft sich der Sprecher aber auf keine Autorität, sondern auf ein allgemeines Prinzip, das er zu weit treibt."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Hume, D.: An Enquiry Concerning Human Understanding, Sect. X „Of Miracles“, Part I (Project Gutenberg, Ausg. Selby-Bigge)","oeffentlich":true,"url":"https://www.gutenberg.org/files/9662/9662-h/9662-h.htm","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"3cd1c60724ea0d91"}},{"id":"qx-a2-026","clusterId":"A","werkstueckRef":"A.18","stufe":4,"question":"Warum ist das Vorgehen von Prüfer B das methodisch bessere?","options":["Prüfer B legt die Regeln und Erfolgskriterien vorab fest; so kann der Test am Mann eine echte Fähigkeit belegen oder die Behauptung scheitern lassen, ohne dass das Ergebnis nachträglich zurechtgebogen wird.","Prüfer B bleibt gegenüber dem Mann freundlich und respektvoll; so fühlt dieser sich ernst genommen und führt seine Wünschelrute bereitwilliger und entspannter vor.","Prüfer B lässt den Test oft wiederholen, bis sich ein stabiles Muster zeigt; so gleichen sich Zufallstreffer des Mannes in der Gesamtzahl der Versuche aus.","Prüfer B zieht erfahrene Wünschelrutengänger als Beurteiler hinzu; so wird der Mann nach den Maßstäben derer geprüft, die sich mit der Wünschelrute auskennen."],"correctIndex":0,"explanation":"Wer von vornherein weiß, dass jemand betrügt, und dann nur nach dem Trick sucht, kann nichts anderes finden als eine Bestätigung seiner Annahme. Das mag als Entlarvung brillant sein, ist aber keine Untersuchung, denn die Schlussfolgerung stand schon fest. Ein vorab vereinbarter, fairer Test ist ergebnisoffen: Besteht der Prüfling unter kontrollierten Bedingungen, muss man die eigene Meinung ändern; besteht er nicht, bleibt die Behauptung unbewiesen, und kein Prüfer hat sich sein Urteil nachträglich zurechtgelegt. So arbeitete auch der Zauberkünstler James Randi, dessen Millionen-Dollar-Herausforderung nach diesem Prinzip aufgebaut war und bis zu ihrem Ende 2015 von niemandem bestanden wurde. Respekt gegenüber dem Mann ist wichtig, macht den Test aber nicht aussagekräftiger. Wiederholungen sind in Tests sinnvoll, davon ist hier aber nicht die Rede, und sie ersetzen nicht die vorab vereinbarten Regeln. Und nicht die Maßstäbe der Praktiker entscheiden, sondern die vorab festgelegten Erfolgskriterien.","coreRule":"⚡ Echte Skepsis lässt dem Behauptenden eine faire Chance, sich zu bewähren.","beleg":"Werkstück A.18 (Einstiegsgeschichte); Fn. ga-randi (Houdini † 1926, Randi * 1928; Zuspitzung, keine wörtlich belegte Aussage)","status":"entwurf","scenario":"Ein Mann behauptet, er könne mit einer Wünschelrute Wasseradern unter der Erde aufspüren. Zwei Prüfer sollen die Behauptung untersuchen. Prüferin A sagt: „Das ist Schwindel. Ich beobachte ihn, bis ich den Trick finde, mit dem er die Leute täuscht.“ Prüfer B sagt: „Wir legen vorab gemeinsam fest, was als Erfolg zählt, schließen Tricks aus und testen ihn unter diesen Bedingungen.“","kurz":"Ein vorab vereinbarter Test ist ergebnisoffen: Besteht der Mann, muss man umdenken, scheitert er, bleibt die Behauptung unbewiesen. Wer nur nach dem Trick sucht, kann bloß die eigene Annahme bestätigen.","prueffrage":"Was genau soll der Mann bei Prüfer B tun, und woran liest man danach ab, ob er Erfolg hatte?","rueckmeldung":[{"option":1,"text":"Respekt gehört zu einem fairen Umgang. Wie aussagekräftig ein Test ist, hängt aber nicht von der Stimmung des Prüflings ab, sondern davon, ob Regeln und Erfolgskriterien vorab feststehen."},{"option":2,"text":"Wiederholungen können Zufallstreffer tatsächlich ausgleichen. Davon ist im Szenario aber keine Rede, und sie ersetzen nicht, dass Regeln und Erfolgskriterien vor dem Test vereinbart werden."},{"option":3,"text":"Fachkundige Beurteiler scheinen den Mann fair zu behandeln. Entscheidend sind aber nicht die Maßstäbe derer, die mit der Rute arbeiten, sondern die vorab festgelegten Kriterien dafür, was als Erfolg zählt."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Wikipedia: One Million Dollar Paranormal Challenge","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/One_Million_Dollar_Paranormal_Challenge","abruf":"2026-10-04"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"738d46e438874196"}},{"id":"qx-a2-027","clusterId":"A","werkstueckRef":"A.19","stufe":1,"question":"Bevor du am Abend deinem Bauchgefühl folgst: Welche Frage hilft dir am meisten zu beurteilen, ob es für diese Entscheidung verlässlich ist?","options":["Wie stark und eindeutig fühlt sich mein Bauchgefühl bei Wahl und Behandlung an, und wie lange hält dieses Gefühl schon an?","Wie gut könnte ich meine Entscheidung bei Wahl und Behandlung vor anderen begründen, und wäre ich bereit, sie öffentlich zu vertreten?","Wie hoch sind die Kosten eines Irrtums bei Wahl oder Behandlung, und ist das ein Bereich, in dem sich mein Bauchgefühl bewährt hat?","Wie viele andere Menschen würden in dieser Lage wohl genauso entscheiden wie ich, und wie sicher wirken sie dabei?"],"correctIndex":2,"explanation":"Schnelle Faustregeln wie das Bauchgefühl sind nützlich, wenn ein Fehler wenig kostet: Wer bei Marmelade danebengreift, verliert kaum etwas. Bei einer Wahl oder einer Behandlung kann ein Irrtum dagegen schwere Folgen haben; je mehr auf dem Spiel steht, desto weniger sollte man sich ungeprüft auf eine Faustregel verlassen. Deshalb prüfst du zuerst, was auf dem Spiel steht und ob sich dein Bauchgefühl in diesem Bereich schon bewährt hat. Ist der Einsatz hoch und fehlt diese Bewährung, lohnt sich eine langsamere, gründlichere Prüfung anhand von Daten und Alternativen. Weder ein starkes, lang anhaltendes Gefühl der Sicherheit noch die Zahl der Menschen, die genauso entscheiden würden, zeigt, ob das Bauchgefühl richtigliegt. Auch die Frage, wie gut sich die Entscheidung vor anderen begründen lässt, ist als Rechenschaft sinnvoll, sagt aber nichts darüber, ob das Gefühl in diesem Bereich treffsicher ist.","coreRule":"⚡ Faustregeln sind meist gut genug, aber je höher die Kosten eines Fehlers, desto eher lohnt die langsame Prüfung.","quote":"Der Kipppunkt ist die Relevanz der Entscheidung.","quoteLabel":"Zum Weiterdenken:","beleg":"Werkstück A.19 (Kernidee; Kontext & Tiefe); Fn. ga-heuristiken (Tversky/Kahneman 1974, Science 185, S. 1124)","status":"entwurf","scenario":"Zwei Situationen am selben Tag: Im Supermarkt greifst du ohne Nachdenken zur Marmeladensorte, die du kennst. Am Abend soll dein Bauchgefühl entscheiden, ob du einem Kandidaten bei einer wichtigen Wahl deine Stimme gibst oder einer teuren medizinischen Behandlung zustimmst.","kurz":"Entscheidend ist, was bei einem Irrtum auf dem Spiel steht und ob sich dein Gefühl in diesem Bereich schon bewährt hat. Bei Marmelade kostet ein Fehlgriff wenig, bei Wahl oder Behandlung kann er schwer wiegen; dann braucht es mehr als ein bloß starkes Gefühl.","prueffrage":"Wie oft hast du bei Marmelade und wie oft bei Wahlen oder Behandlungen schon aus dem Bauch entschieden, und wie ging es aus?","rueckmeldung":[{"option":0,"text":"Ein starkes, lang anhaltendes Gefühl fühlt sich nach Verlässlichkeit an, doch die Stärke misst nur, wie sicher du dich fühlst. Ob das Gefühl in diesem Bereich schon einmal richtiglag, zeigt sie nicht."},{"option":1,"text":"Eine Entscheidung begründen zu können, ist als Rechenschaft sinnvoll. Es sagt aber nicht, ob dein Bauchgefühl in diesem Bereich treffsicher ist, und genau darum geht es hier."},{"option":3,"text":"Dass viele andere ähnlich entscheiden würden und dabei sicher wirken, beruhigt leicht. Es zeigt aber nicht, ob das Bauchgefühl richtigliegt, und ersetzt nicht die Frage nach Einsatz und Bewährung."}],"familie":"faustregel-oder-rechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Kahneman, D.; Klein, G. (2009): Conditions for intuitive expertise: a failure to disagree. American Psychologist 64(6), 515–526 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/19739881/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"465","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124","seite":"1124"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"aed1ef92f4b7e549"}},{"id":"qx-a2-028","clusterId":"A","werkstueckRef":"A.19","stufe":2,"question":"Warum ist es hier vernünftig, einfach die bekannte Marke zu nehmen, statt alle Sorten zu vergleichen?","scenario":"Im Supermarkt stehst du vor einem Regal mit 50 Marmeladensorten und greifst ohne langes Nachdenken zu deiner gewohnten Marke.","options":["Dir schmeckt die gewohnte Marke, und was dir schmeckt, ist unter den 50 Sorten auch die objektiv beste.","Ein Fehlgriff kostet wenig, ein Vergleich aller 50 Sorten dagegen unverhältnismäßig viel Zeit und Mühe.","Bei 50 Sorten greift die Mehrheit zur bekannten Marke, und ihre Wahl zeigt, welche Sorte die beste ist.","Du hast die gewohnte Marke oft gekauft, und ein Wechsel zu einer der 49 anderen würde diese Käufe entwerten."],"correctIndex":1,"explanation":"Faustregeln sind mentale Abkürzungen, die in den meisten Fällen „gut genug“ sind, aber nicht optimal und nicht fehlerfrei. Entscheidend ist das Verhältnis von Aufwand und Einsatz: Bei der Marmelade ist ein möglicher Fehler trivial, während ein vollständiger Vergleich aller 50 Sorten viel Zeit und Energie kostet. Wer vor jedem Regal alles durchrechnen wollte, käme im Alltag kaum zum Handeln. Anders sieht es aus, wenn viel auf dem Spiel steht, etwa bei einer medizinischen Entscheidung: Dort lohnt sich der Wechsel zum langsamen, genauen Prüfen, weil ein Fehler teuer wäre. Der eigene Geschmack klingt nach einem guten Maßstab, sagt aber nichts über die 49 Sorten, die du nie probiert hast. Die Wahl der Mehrheit klingt nach geprüfter Qualität, doch von anderen Käufern ist im Szenario keine Rede, und Beliebtheit ist kein Maß für Güte. Treue zu früheren Käufen klingt nach Konsequenz, aber das Geld dafür ist ausgegeben und spricht nicht für künftige Käufe.","coreRule":"⚡ Bei geringem Einsatz ist die Faustregel klug, bei hohem Einsatz lohnt das genaue Rechnen.","beleg":"Werkstück A.19 (Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","kurz":"Die Abkürzung ist vernünftig, weil ein Fehlgriff bei Marmelade wenig kostet, ein voller Vergleich aller 50 Sorten aber viel Zeit und Energie. Das Verhältnis von Aufwand und Einsatz entscheidet, nicht die Qualität der Marke. Steht viel auf dem Spiel, lohnt sich genaues Prüfen.","prueffrage":"Wie oft hat dich die gewohnte Marke schon enttäuscht, und was hast du dann getan?","rueckmeldung":[{"option":0,"text":"Dass dir die Marke schmeckt, zählt für deine Wahl durchaus. Über die 49 Sorten, die du nie probiert hast, sagt es aber nichts, deshalb lässt sich die Marke damit nicht als objektiv beste ausgeben."},{"option":2,"text":"Was die Mehrheit wählt, wirkt wie geprüfte Qualität. Von anderen Käufern ist im Szenario aber gar nicht die Rede, und Beliebtheit allein sagt nichts darüber, welche Sorte tatsächlich die beste ist."},{"option":3,"text":"Wer eine Marke oft gekauft hat, kennt sie, und das wirkt wie ein Grund zur Treue. Doch das Geld für frühere Käufe ist ausgegeben und spricht nicht für künftige. Ein Wechsel würde sie auch gar nicht entwerten."}],"familie":"faustregel-oder-rechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Bounded Rationality (überarb. 2024)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/bounded-rationality/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"483","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"11f331c07d0b4f2b"}},{"id":"qx-a2-029","clusterId":"A","werkstueckRef":"A.19","stufe":3,"question":"Wozu rätst du ihr in dieser Lage?","options":["Sie ist sich absolut sicher; dieses starke Gefühl zeigt, dass die Faustregel hier trägt, also kann sie den Vertrag noch heute unterschreiben.","Sie hat schon viele Verträge abgeschlossen; ihr Bauchgefühl speist sich aus Erfahrung, also kann sie auf Vergleichsangebote verzichten.","Sie hat noch zwei Wochen Zeit; statt fünf Minuten sollte sie eine Stunde in Ruhe über den Vertrag nachdenken und dann ihrem Gefühl folgen.","Der Vertrag bindet die Firma für Jahre, und die Frist lässt Zeit; also sollte sie die Details prüfen und Vergleichsangebote einholen."],"correctIndex":3,"explanation":"Faustregeln sind schnell und meist gut genug, aber ihre Fehler sind vorhersagbar. Ob du ihnen trauen darfst, hängt davon ab, was ein Fehler kostet: Beim Marmeladenkauf ist er trivial, bei einem Vertrag, der die Firma jahrelang bindet, kann er schwer wiegen. Dann lohnt sich der Wechsel ins langsame, analytische Denken, zumal die Frist von zwei Wochen Zeit zum Prüfen lässt. Ein starkes Sicherheitsgefühl spricht nicht für die Faustregel: Gerade wer bei einer schnellen Entscheidung in komplexer Lage absolut sicher ist, sollte misstrauisch werden. Auch viel Erfahrung ändert nichts daran, dass hier ein Fehler teuer wäre und eine Prüfung möglich ist; das Bauchgefühl ersetzt sie nicht. Und eine Stunde Grübeln hilft wenig, denn es kommt nicht auf die Dauer an, sondern auf die Art der Prüfung: Daten, Vergleiche, Gegenfragen.","coreRule":"⚡ Je höher der Einsatz, desto weniger darfst du dich auf die schnelle Faustregel verlassen.","beleg":"Werkstück A.19 (Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"Eine Kollegin will in fünf Minuten über einen Vertrag entscheiden, der die Firma mehrere Jahre bindet. Sie hat schon viele Verträge abgeschlossen und sagt: „Ich habe sofort ein gutes Gefühl dabei, das passt. Ich bin mir absolut sicher.“ Detailprüfung oder Vergleichsangebote gab es nicht. Die Frist für die Unterschrift endet erst in zwei Wochen.","quote":"","quoteLabel":"","kurz":"Bei einem Vertrag, der die Firma jahrelang bindet, wäre ein Fehler teuer, und zwei Wochen Frist erlauben eine echte Prüfung. Das starke Gefühl ist dabei kein Gegenargument, es ersetzt Details und Vergleiche nicht.","prueffrage":"Was würde ein Fehler bei dieser Unterschrift kosten, und wie viel Zeit bleibt, ihn zu vermeiden?","rueckmeldung":[{"option":0,"text":"Große Sicherheit fühlt sich wie ein gutes Zeichen an. Sie sagt aber nur etwas über das Gefühl, nicht über den Vertrag, und bei einer schnellen Entscheidung in komplexer Lage ist sie eher ein Grund für Misstrauen."},{"option":1,"text":"Erfahrung macht das Bauchgefühl durchaus wertvoller als bei Anfängern. Sie ändert aber nichts daran, dass ein Fehler hier teuer wäre und eine Prüfung möglich ist; das Gefühl ersetzt keine Vergleiche."},{"option":2,"text":"Mehr Zeit zu nehmen und die Frist zu nutzen ist ein Fortschritt gegenüber fünf Minuten. Entscheidend ist aber nicht, wie lange man nachdenkt, sondern was man prüft: Daten, Vergleiche, Gegenfragen. Eine Stunde Grübeln mit anschließendem Gefühlsurteil leistet das nicht."}],"familie":"faustregel-oder-rechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Kahneman, D.; Klein, G. (2009): Conditions for intuitive expertise: a failure to disagree. American Psychologist 64(6), 515–526 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/19739881/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"465, 472","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"e713df9ad09b12d8"}},{"id":"qx-a2-030","clusterId":"A","werkstueckRef":"A.19","stufe":4,"question":"Welcher Denkfehler steckt im Argument des Freundes?","options":["Er nimmt an, die erste Erklärung, die er gehört hat, sei die richtige, und passt seine Einschätzung nur geringfügig an.","Er hält die Verschwörungserklärung für häufig, weil ihm viele Fälle von geheimen Plänen leicht einfallen.","Er hält die Erklärung für glaubwürdig, weil sie ihm aus früheren Gesprächen und Berichten schon vertraut vorkommt.","Er schließt von der Größe des Ereignisses auf eine ebenso große, geordnete Ursache, ohne diese zu prüfen."],"correctIndex":3,"explanation":"Der Freund verlässt sich auf eine Faustregel: Ein großes Ereignis muss auch eine ebenso große Ursache haben. Geplant war der Anschlag zwar, aber von al-Qaida mit 19 Attentätern und nicht von allmächtigen Hintermännern im Verborgenen. Die gewaltigen Folgen sagen also wenig darüber, wie groß und mächtig die Urheber sind; das Gefühl, eine riesige Wirkung verlange eine riesige Ursache, ersetzt keine Prüfung an Belegen. Die anderen Antworten beschreiben andere Denkfehler (Anker, leichte Erinnerbarkeit, Vertrautheit), die im Argument gar nicht vorkommen: Der Freund beruft sich weder auf eine zuerst gehörte Erklärung noch auf erinnerte Einzelfälle noch auf Bekanntes, sondern allein auf die Größe des Ereignisses.","coreRule":"⚡ Wenn eine Erklärung überzeugt, weil sie so groß ist wie das Ereignis, frage nach Belegen statt nach Stimmigkeit.","beleg":"Werkstück A.19 (Anwendung: Bei Verschwörungsmythen; Kontext & Tiefe: Repräsentativitätsheuristik)","status":"entwurf","scenario":"Nach dem Anschlag vom 11. September 2001 verbreitet sich die Behauptung, dahinter müsse ein langfristig geplanter, geheimer Plan mächtiger Hintermänner stecken. Ein Freund sagt: „So etwas Riesiges kann doch unmöglich einfach so passiert sein.“","kurz":"Der Freund schließt von der Größe des Ereignisses auf eine ebenso große, geordnete Ursache. Das fühlt sich stimmig an, ersetzt aber keine Prüfung an Belegen: Riesige Folgen beweisen keine mächtigen Hintermänner.","prueffrage":"Was müsste man über die Täter eines Anschlags wissen, um zu beurteilen, wie mächtig und gut organisiert sie waren?","rueckmeldung":[{"option":0,"text":"Sich an eine zuerst gehörte Erklärung zu klammern, ist ein bekannter Fehler. Davon ist hier aber nichts zu sehen: Der Freund beruft sich nicht darauf, was er zuerst gehört hat, sondern auf die schiere Größe des Ereignisses."},{"option":1,"text":"Dass uns auffällige Einzelfälle leicht einfallen und deshalb häufiger wirken, ist ein echter Denkfehler. Der Freund nennt aber keine Einzelfälle und schätzt keine Häufigkeit; sein ganzer Gedanke hängt an der Größe des Ereignisses."},{"option":2,"text":"Vertraut Klingendes wirkt oft glaubwürdiger, das ist ein bekannter Effekt. Der Freund begründet seine Haltung aber nicht damit, dass er die Geschichte schon kennt, sondern damit, dass etwas so Großes nicht zufällig geschehen könne."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Brotherton, R.; French, C. C. (2014): Belief in Conspiracy Theories and Susceptibility to the Conjunction Fallacy. Applied Cognitive Psychology 28, 238–248 (Repositorium Goldsmiths)","oeffentlich":true,"url":"https://eprints-gro.gold.ac.uk/10794/1/acp2995.pdf","seite":"238","abruf":"2026-10-12"},{"typ":"url","kurz":"National Commission on Terrorist Attacks Upon the United States: The 9/11 Commission Report, Executive Summary","oeffentlich":true,"url":"https://www.9-11commission.gov/report/911Report_Exec.htm","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"7ab9641d917dd846"}},{"id":"qx-a2-031","clusterId":"A","werkstueckRef":"A.20","stufe":1,"question":"Welche Antwort erklärt am besten, warum die Ärzte damals Semmelweis’ Idee nicht prüften, sondern als „sinnlosen Lärm“ abtaten?","options":["Die Idee der Leichenteilchen passte nicht in den unausgesprochenen Rahmen aus Miasmen und Säftelehre, den alle für selbstverständlich hielten, und galt nicht als ernsthafte Hypothese.","Die Ärzte hielten die Idee der Leichenteilchen insgeheim für möglich, wollten aber ihr Ansehen vor den Kollegen nicht gefährden und wiesen sie deshalb bewusst ab, ohne sie zu prüfen.","Die Ärzte konnten die Chlorkalk-Waschung fachlich nicht einordnen, weil ihnen das Wissen über Krankheitsursachen fehlte, und verwarfen die Idee aus schlichter Überforderung.","Die Ärzte beurteilten die Idee nach ihrem Urheber: Weil der Arzt jung war und im Fach noch nichts galt, nahmen sie seine Aussagen über die Leichenteilchen von vornherein nicht ernst."],"correctIndex":0,"explanation":"Die Ablehnung lässt sich am sparsamsten so erklären: Ein System selbstverständlicher Annahmen (Krankheit durch Miasmen oder Säfteungleichgewicht) bestimmt, was überhaupt als sinnvolle Idee zählt. Innerhalb dieses Rahmens war „Leichenteilchen an den Händen“ keine falsche Hypothese, sondern unverständlich. Solche Rahmen sind meist unbewusst, die Beteiligten halten sie schlicht für „normal“. Das erklärt auch, warum Fakten allein den Streit nicht entschieden: Erst Jahrzehnte später, mit Pasteurs Keimtheorie, wurde Semmelweis’ Idee bestätigt. Ganz unschuldig war Semmelweis allerdings nicht: Er veröffentlichte spät, konnte die Wirkung des Chlorkalks nicht erklären und beschimpfte Kritiker. Auch gekränkter Stolz und Standesdenken der Ärzte spielten mit; das Paradigma erklärt vor allem, warum die Idee als absurd galt. Gekränkter Stolz spielte zwar mit, die Idee galt als Beleidigung des Ärztestandes. Option 1 unterstellt aber mehr: Die Ärzte hätten die Idee insgeheim für möglich gehalten und bewusst unterdrückt. Das widerspricht der Beschreibung als ehrlich und erklärt nicht, warum die Idee selbst als absurd galt. Fachliche Überforderung klingt einleuchtend, doch es sind erfahrene Ärzte, die sich am Wissensstand ihrer Zeit orientieren. Dass der Urheber jung war, kann mitgespielt haben, erklärt aber nicht, warum die Idee selbst als absurd galt, nämlich weil sie dem Weltbild widersprach.","coreRule":"⚡ Ein Paradigma ist die unsichtbare Karte, nach der ein Fach navigiert: Es entscheidet mit, was als sinnvolle Idee gilt, noch bevor jemand prüft.","beleg":"Werkstück A.20 (Kernidee; Kontext & Tiefe); Fn. ga-kuhn (Kuhn 1962, The Structure of Scientific Revolutions)","status":"entwurf","scenario":"Wien, 1847: Viele Wöchnerinnen sterben am Kindbettfieber. Ein junger Arzt behauptet, unsichtbare Leichenteilchen an den Händen der Ärzte seien die Ursache, und verlangt, dass sich alle vor jeder Untersuchung die Hände in Chlorkalklösung waschen. Seine Kollegen halten das für absurd und beleidigend. Dabei sind sie weder dumm noch unehrlich, sondern erfahrene Ärzte, die sich an dem orientieren, was zu ihrer Zeit als gesichertes Wissen gilt: Krankheiten entstehen durch schlechte Luft (Miasmen) oder ein Ungleichgewicht der Körpersäfte.","quote":"","quoteLabel":"","kurz":"Die Ärzte lehnten die Idee ab, weil sie nicht in den Rahmen passte, den alle für selbstverständlich hielten: Krankheit durch Miasmen oder Säfte. Darin galt „Leichenteilchen an den Händen“ nicht als falsche Hypothese, sondern als unverständlich. Den Rahmen selbst bemerkt man meist nicht.","prueffrage":"Wofür hielten die Kollegen die Forderung, und wie würdest du reagieren, wenn du nur ihr damaliges Wissen hättest?","rueckmeldung":[{"option":1,"text":"Sorge ums Ansehen ist ein verbreitetes menschliches Motiv und wirkt deshalb plausibel. Die Ärzte gelten hier aber als ehrlich, und sie hielten die Idee für absurd, nicht heimlich für möglich. Wer so überzeugt ist, muss nichts bewusst verdrängen."},{"option":2,"text":"Mangelndes Wissen erscheint als naheliegende Erklärung für Ablehnung. Es waren aber erfahrene Ärzte, die den Wissensstand ihrer Zeit anwendeten. Nicht Unwissen, sondern ein anderer Rahmen machte die Idee für sie unverständlich."},{"option":3,"text":"Dass der Arzt jung und noch unbekannt war, kann durchaus mitgespielt haben. Damit ist aber nicht erklärt, warum die Idee selbst als absurd galt. Das lag daran, dass sie dem damaligen Weltbild widersprach, und nicht am Alter des Urhebers."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bird, A.: Thomas Kuhn. Stanford Encyclopedia of Philosophy (überarb. 2025)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thomas-kuhn/","abruf":"2026-10-07"},{"typ":"doi","kurz":"Best, M.; Neuhauser, D. (2004): Ignaz Semmelweis and the birth of infection control. Quality & Safety in Health Care 13(3), 233–234","oeffentlich":true,"doi":"10.1136/qshc.2004.010918","seite":"233–234","abruf":"2026-10-12"},{"typ":"doi","kurz":"Schreiner, S. (2020): Ignaz Semmelweis: a victim of harassment? Wiener Medizinische Wochenschrift 170(11–12), 293–302","oeffentlich":true,"doi":"10.1007/s10354-020-00738-1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v6","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"924fc93f0b2670b1"}},{"id":"qx-a2-033","clusterId":"A","werkstueckRef":"A.20","stufe":3,"question":"Wie ist das Verhalten dieser Fachgesellschaft zu beurteilen, und welcher Schritt wäre sinnvoll?","options":["Das Verhalten ist problematisch, weil die seit Jahren gehäuften Abweichungen ohne Prüfung als Messfehler wegerklärt und die Forscherin ausgegrenzt werden. Sinnvoll wäre, die Daten unabhängig nachzuprüfen.","Das Verhalten ist unproblematisch, weil die Theorie im Alltag gut funktioniert und die meisten Mitglieder gern damit arbeiten. Sinnvoll wäre, die Abweichungen weiter als Messfehler zu verbuchen.","Das Verhalten ist problematisch, weil sich die Abweichungen seit Jahren häufen und ungeklärt bleiben. Sinnvoll wäre, die Theorie vorsorglich zu verwerfen, bis die Messungen geklärt sind.","Das Verhalten ist unproblematisch, weil eine Tagung ihre Beiträge frei auswählen darf und die Forscherin keinen Anspruch auf eine Einladung hat. Sinnvoll wäre, die Einladungspraxis beizubehalten."],"correctIndex":0,"explanation":"Ein gemeinsamer Theorierahmen ist nützlich: Er erspart es, bei jeder Beobachtung die Grundlagen neu zu verhandeln, und macht die Arbeit an Detailproblemen effizient. Dass die Theorie meist funktioniert und von vielen geteilt wird, spricht also nicht gegen sie, aber auch nicht gegen die Prüfung von Abweichungen. Problematisch wird ein Rahmen, wenn Abweichungen nicht mehr untersucht, sondern ungeprüft wegerklärt und Kritiker nicht mehr als Herausforderer, sondern als Feinde behandelt werden: Dann erstarrt er zum Dogma. Genau das passiert hier: Die Daten werden ungeprüft abgetan, die Forscherin wird ausgegrenzt. Sinnvoll ist deshalb, die Daten unabhängig nachzuprüfen; ob die Theorie angepasst oder gar ersetzt werden muss, zeigt erst diese Prüfung. Dass die Theorie im Alltag funktioniert, klingt nach einem guten Grund zum Weitermachen, doch ohne Nachprüfung ist „Messfehler“ nur eine Vermutung. Die Theorie sofort zu verwerfen klingt konsequent, geht aber zu weit, denn ob sie angepasst oder ersetzt werden muss, zeigt erst die Prüfung. Ein freies Einladungsrecht der Tagung klingt nach einem legitimen Grund, ändert aber nichts daran, dass die Daten ungeprüft abgetan werden.","coreRule":"⚡ Ein Rahmen wird zum Dogma, wenn er Abweichungen und Kritiker bekämpft, statt sie zu untersuchen.","beleg":"Werkstück A.20 (Der Kipppunkt; Das Adaptive Talent; Kontext & Tiefe; Einleitung zu Semmelweis)","status":"entwurf","scenario":"In einer Fachgesellschaft häufen sich seit Jahren Messergebnisse, die zur herrschenden Theorie nicht passen. Der Vorstand erklärt sie regelmäßig zu Messfehlern, ohne die Daten nachzuprüfen. Eine Forscherin, die die Abweichungen systematisch untersuchen will, gilt als Querulantin; ihre Beiträge werden nicht mehr zu Tagungen eingeladen. Im Alltag funktioniert die Theorie sonst gut, und die meisten Mitglieder arbeiten gern damit.","kurz":"Ein Rahmen wird zum Dogma, wenn Abweichungen ungeprüft als Messfehler gelten und Kritiker ausgegrenzt werden. Weil erst eine unabhängige Nachprüfung zeigt, ob die Theorie angepasst werden muss, ist sie der sinnvolle Schritt, nicht das Weitermachen und nicht das Verwerfen.","prueffrage":"Wie lange häufen sich die Abweichungen schon, und was ist mit der Forscherin geschehen, die sie untersuchen wollte?","rueckmeldung":[{"option":1,"text":"Dass die Theorie im Alltag gut funktioniert und viele gern mit ihr arbeiten, spricht tatsächlich nicht gegen sie. Ohne Nachprüfung bleibt „Messfehler“ aber nur eine Vermutung, und die gehäuften Abweichungen bleiben ungeklärt."},{"option":2,"text":"Dass die jahrelang gehäuften Abweichungen ein Problem sind, stimmt. Die Theorie vorsorglich zu verwerfen geht jedoch zu weit, denn sie funktioniert meist gut; ob sie angepasst oder ersetzt werden muss, zeigt erst die Prüfung."},{"option":3,"text":"Eine Tagung darf ihre Beiträge grundsätzlich frei auswählen, einen Anspruch auf Einladung hat niemand. Das beantwortet aber nicht, warum die Daten ungeprüft als Messfehler abgetan werden; genau dort liegt das Problem."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bird, A.: Thomas Kuhn. Stanford Encyclopedia of Philosophy (überarb. 2025)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thomas-kuhn/","abruf":"2026-10-07"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"3ed93866252b9df4"}},{"id":"qx-a2-034","clusterId":"A","werkstueckRef":"A.20","stufe":4,"question":"Ein Anbieter wirbt für sein „neues Paradigma“ und sagt: „Wer zweifelt, ist noch im alten Denken gefangen.“ Wie bewertest du das?","options":["Als Warnzeichen: Eine Neuerung überzeugt durch bessere Erklärungen; der Satz macht den Anspruch gegen Kritik unangreifbar.","Als Fehlschluss aus der Mehrheit: Der Anbieter schließt von der Verbreitung seiner Idee auf deren Wahrheit.","Als überzeugend: Der Anbieter zeigt damit, welche Probleme das alte Modell hat und wie sein neues sie löst.","Als Hinweis auf Mut: Neue Ideen stoßen anfangs oft auf Ablehnung, und der Widerstand spricht eher für den Anbieter."],"correctIndex":0,"explanation":"Wer Zweifel als Zeichen von Befangenheit abwertet, macht seine Behauptung unprüfbar: Jeder Einwand wird zum Beweis, dass der Kritiker „es nicht verstanden hat“. Eine echte Neuerung in der Wissenschaft setzt sich anders durch: Sie erklärt Beobachtungen, an denen das Alte scheitert, und leistet dabei fast alles, was das Alte leistete. Selbst dann gehen manchmal einzelne Erklärungen verloren, aber nicht der Großteil des Bewährten. Entscheidend ist, ob eine Neuerung mehr erklärt und prüfbar ist. Dass Neues anfangs auf Widerstand stößt, stimmt oft, ist aber kein Gütezeichen: Auch Semmelweis’ Idee setzte sich erst später durch, als sie erklärt werden konnte.","coreRule":"⚡ Eine Neuerung überzeugt durch bessere Erklärungen, nicht dadurch, Kritik zu entwerten.","beleg":"Werkstück A.20 (Anwendung: Bei Pseudowissenschaften & Esoterik; Red Flags: „Kritik wird als Beweis dafür abgetan, dass der Kritiker noch im alten Paradigma gefangen ist“); Fn. ga-kuhn (Kuhn 1962; Bird, SEP „Thomas Kuhn“, Abschn. 2: Kuhn-loss)","status":"entwurf","kurz":"Wer Zweifel als Befangenheit abtut, macht seine Behauptung unprüfbar, denn jeder Einwand gilt dann als Beweis, dass der Kritiker nichts verstanden hat. Eine echte Neuerung überzeugt dagegen, weil sie mehr erklärt und sich prüfen lässt.","prueffrage":"Was erfährt man aus dem Satz des Anbieters über sein Produkt selbst, und was nur über die Zweifler?","rueckmeldung":[{"option":1,"text":"Vom Anbieter ist hier nur zu hören, wer zweifelt, sei befangen. Auf viele Anhänger oder weite Verbreitung beruft er sich nicht. Der Fehler liegt woanders: Kritik wird von vornherein entwertet, die Behauptung so unprüfbar."},{"option":2,"text":"Das klingt nach einem Argument, doch im Satz kommt weder ein Problem des alten Modells noch eine Lösung vor. Er zeigt also nichts davon. Eine echte Neuerung erklärt, woran das Alte scheitert, und bewahrt dabei fast alles Bewährte."},{"option":3,"text":"Dass Neues oft zuerst auf Widerstand stößt, stimmt. Widerstand ist aber kein Gütezeichen: Semmelweis setzte sich erst durch, als seine Idee erklärt werden konnte. Der Satz hier lässt gar keine Prüfung mehr zu."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bird, A.: Thomas Kuhn. Stanford Encyclopedia of Philosophy (überarb. 2025), Abschn. 2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thomas-kuhn/","abruf":"2026-10-07"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"546ddca77e63bc42"}},{"id":"qx-a2-035","clusterId":"A","werkstueckRef":"A.21","stufe":1,"question":"Du bekommst eine Wette angeboten: Münzwurf, bei Kopf gewinnst du 150 Euro, bei Zahl verlierst du 100 Euro. Du lehnst ab, obwohl du bei vielen Wiederholungen im Schnitt Geld gewinnen würdest. Wie lässt sich deine Ablehnung am besten erklären?","options":["Menschen scheuen Wetten mit unbekannten Chancen, und bei der Münze deiner Freundin kennst du sie nicht, obwohl der Durchschnitt positiv ist.","Der Gewinn von 150 Euro käme erst später, der Verlust von 100 Euro sofort, und Späteres zählt weniger (Gegenwartsverzerrung), obwohl der Durchschnitt positiv ist.","Menschen überschätzen kleine Wahrscheinlichkeiten, sodass dir der seltene Verlust von 100 Euro größer erscheint, als er ist, obwohl der Durchschnitt positiv ist.","Ein möglicher Verlust von 100 Euro wiegt psychologisch schwerer als die Aussicht auf einen Gewinn von 150 Euro, obwohl der Durchschnitt positiv ist."],"correctIndex":3,"explanation":"Der Durchschnittswert der Wette liegt bei +25 Euro (0,5 × 150 − 0,5 × 100). Trotzdem lehnen die meisten Menschen ab, weil ein möglicher Verlust von 100 Euro stärker wiegt als ein gleich großer Gewinn. Das ist Verlustaversion, ein Kernstück der Prospect Theory von Kahneman und Tversky: Entschieden wird nicht über absolute Endzustände, sondern über Gewinne und Verluste relativ zu einem Referenzpunkt (dem, was man schon hat). In der Messung von 1992 zählte ein Verlust etwa doppelt so stark wie ein gleich hoher Gewinn. Die Scheu vor unbekannten Chancen klingt vorsichtig, scheitert aber daran, dass die Münze fair ist und die Chancen bekannt sind. Die Überschätzung kleiner Wahrscheinlichkeiten ist ein bekannter Effekt, passt aber nicht, weil 50 Prozent keine kleine Wahrscheinlichkeit sind. Die Gegenwartsverzerrung klingt einleuchtend, doch Gewinn wie Verlust träten sofort ein.","coreRule":"⚡ Verluste wiegen meist schwerer als gleich große Gewinne (in der klassischen Messung etwa doppelt), deshalb lehnen viele auch Wetten mit positivem Durchschnitt ab.","beleg":"Werkstück A.21 (Einstiegsgeschichte; Kernidee); Fn. ga-prospect (Kahneman/Tversky 1979, Econometrica 47(2), S. 279; Tversky/Kahneman 1992, S. 311)","status":"entwurf","scenario":"Eine Freundin schlägt dir vor: „Wir werfen eine faire Münze. Bei Kopf zahle ich dir 150 Euro, bei Zahl zahlst du mir 100 Euro.“ Du merkst, dass du eigentlich keine Lust darauf hast, obwohl du nachrechnest, dass du im Durchschnitt 25 Euro pro Wurf gewinnen würdest.","kurz":"Ein möglicher Verlust von 100 Euro wiegt für die meisten schwerer als ein Gewinn von 150 Euro. Man liest die Wette nicht als „im Schnitt +25 Euro“, sondern als Gewinne und Verluste vom aktuellen Stand aus, und Verluste zählen stärker (Verlustaversion).","prueffrage":"Was ergibt 0,5 × 150 − 0,5 × 100, und reicht dieses Ergebnis, damit du zusagst?","rueckmeldung":[{"option":0,"text":"Unbekannte Chancen schrecken Menschen tatsächlich ab. Hier ist die Münze aber fair, und die 50:50-Chance ist bekannt. Die Scheu muss also einen anderen Grund haben."},{"option":1,"text":"Spätere Belohnungen zählen oft weniger, aber dafür müssten Gewinn und Verlust zu verschiedenen Zeiten eintreten. Hier käme beides sofort, also kann ein Zeitunterschied die Ablehnung nicht erklären."},{"option":2,"text":"Seltene Ereignisse werden oft überschätzt. Ein Verlust bei 50 Prozent ist aber nicht selten, sondern genauso wahrscheinlich wie der Gewinn. Die Ablehnung kann daher nicht von einer verzerrten Seltenheit kommen."}],"familie":"verlust-und-gewinn-abwaegen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"461–462","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1992): Advances in Prospect Theory: Cumulative Representation of Uncertainty. Journal of Risk and Uncertainty 5(4), 297–323","oeffentlich":false,"doi":"10.1007/BF00122574","seite":"311"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v6","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"0c6f17b9586d5319"}},{"id":"qx-a2-036","clusterId":"A","werkstueckRef":"A.21","stufe":2,"question":"Ein Anleger hat zwei Aktien: eine liegt 30 % im Plus, die andere 30 % im Minus. Er muss eine davon verkaufen und sagt: „Die Gewinneraktie nehme ich mit, die Verliererin behalte ich, die erholt sich schon wieder.“ Welche Erklärung für dieses Verhalten passt zu dem, was die Prospect Theory über Entscheidungen unter Unsicherheit beschreibt?","scenario":"Ein Anleger besitzt zwei Aktien: Die eine liegt 30 % im Plus, die andere 30 % im Minus. Er muss eine verkaufen und entscheidet sich für die Gewinneraktie. Die Verliereraktie behält er und sagt: „Die erholt sich schon wieder.“","options":["Er rechnet nüchtern mit dem erwarteten Endvermögen und kommt zu dem Ergebnis, dass die Verliereraktie mit ihren 30 % Minus die besseren Aussichten hat als die Gewinneraktie.","Im Plus will er den sicheren Gewinn festhalten, im Minus wagt er lieber das Risiko eines noch größeren Verlusts, um die Chance auf Rückkehr zum Einstandskurs zu wahren.","Er überschätzt seine Fähigkeit, Kurse vorherzusagen (Selbstüberschätzung), und glaubt deshalb fest, gerade die Verliereraktie mit ihren 30 % Minus werde sich bald erholen.","Er sucht nur Meldungen, die seine Hoffnung auf eine Erholung der Verliereraktie mit ihren 30 % Minus bestätigen, und blendet alle anderen aus (Bestätigungsfehler)."],"correctIndex":1,"explanation":"Die Prospect Theory beschreibt ein asymmetrisches Risikoverhalten: Im Bereich der Gewinne bevorzugen Menschen den sicheren, kleineren Gewinn, im Bereich der Verluste nehmen sie lieber ein größeres Risiko in Kauf, um den Verlust vielleicht ganz zu vermeiden. Der Referenzpunkt ist dabei der Einstandskurs. Deshalb werden Gewinne oft zu früh realisiert und Verluste zu lange gehalten. Der Satz „die erholt sich schon wieder“ ist selbst ein Warnzeichen: Er begründet das Festhalten mit der Hoffnung, nicht mit einer Prüfung der Aussichten. Die klärende Frage lautet: „Würde ich diese Aktie heute zu diesem Kurs neu kaufen?“ Wenn nicht, spricht wenig fürs Halten. Wenn ja, ist das Halten begründet, aber dann nicht wegen des Verlusts. Die nüchterne Rechnung mit dem Endvermögen klingt vernünftig, behandelt aber Gewinn und Verlust gleich und kann nicht erklären, warum er die Gewinneraktie anders behandelt als die Verliereraktie. Selbstüberschätzung beim Vorhersagen klingt plausibel, erklärt aber nicht, warum er im Plus anders handelt als im Minus. Ein Bestätigungsfehler kann das Festhalten stützen, nennt aber keinen Grund, die Gewinneraktie zu verkaufen.","coreRule":"⚡ Gewinne sichern wir zu früh, Verluste halten wir zu lange.","beleg":"Werkstück A.21 (Kontext & Tiefe, Pfeiler 3; Anwendung: finanzielle Entscheidungen); Fn. ga-prospect-gewichtung (Kahneman/Tversky 1979, S. 268–269)","status":"entwurf","kurz":"Entscheidend ist der Einstandskurs als Referenzpunkt: Im Plus nehmen Menschen oft lieber den sicheren Gewinn, im Minus eher das größere Risiko. So erklärt sich, warum er beide Aktien so unterschiedlich behandelt.","prueffrage":"Was tut der Anleger mit der Gewinneraktie, was mit der Verliererin, und womit begründet er das Halten?","rueckmeldung":[{"option":0,"text":"Eine nüchterne Rechnung mit dem Endvermögen klingt vernünftig. Sie behandelt aber Gewinn und Verlust gleich und erklärt daher nicht, warum er die beiden Aktien so verschieden anfasst. Dass die Verliereraktie die besseren Aussichten hat, sagt auch nichts im Szenario."},{"option":2,"text":"Selbstüberschätzung kann den Glauben an die Erholung durchaus stützen. Sie erklärt aber nicht, warum er im Plus anders entscheidet als im Minus; genau dieser Unterschied ist hier das Auffällige."},{"option":3,"text":"Ein Bestätigungsfehler kann das Festhalten an der Verliereraktie stützen. Er liefert aber keinen Grund, die Gewinneraktie zu verkaufen, und lässt den Unterschied zwischen Plus und Minus unerklärt."}],"familie":"verlust-und-gewinn-abwaegen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"461–462","abruf":"2026-10-12"},{"typ":"url","kurz":"Odean, T.: Are Investors Reluctant to Realize Their Losses? (Autorenseite, UC Berkeley)","oeffentlich":true,"url":"https://faculty.haas.berkeley.edu/odean/papers/disposition/disposition.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kahneman, D.; Tversky, A. (1979): Prospect Theory: An Analysis of Decision under Risk. Econometrica 47(2), 263–291","oeffentlich":false,"doi":"10.2307/1914185","seite":"268"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"a06981ccf4304654"}},{"id":"qx-a2-037","clusterId":"A","werkstueckRef":"A.21","stufe":3,"question":"Was ist an der Aussage des Kollegen fehlerhaft?","scenario":"Eine Beraterin legt einem Kunden zwei Aufgaben vor. Aufgabe 1: Du erhältst zuerst 1.000 € und wählst dann zwischen A) garantiert weiteren 500 € und B) Münzwurf: bei Kopf weitere 1.000 €, bei Zahl nichts. Aufgabe 2: Du erhältst zuerst 2.000 € und wählst dann zwischen C) garantiert 500 € Verlust und D) Münzwurf: bei Kopf 1.000 € Verlust, bei Zahl nichts. In einem Test wählt die Mehrheit bei Aufgabe 1 die sichere Option A und bei Aufgabe 2 den Münzwurf D. Ein Kollege sagt: „Die Leute haben eben zwei unterschiedliche Situationen bewertet, das ist völlig vernünftig.“","options":["Er übersieht, dass A und C beide garantiert 1.500 € bedeuten und B und D beide im Schnitt 1.500 €; nur die Rahmung als Gewinn oder Verlust unterscheidet die beiden Aufgaben.","Er übersieht, dass B im Schnitt 2.000 € bringt, A aber nur garantierte 1.500 €; wer in Aufgabe 1 die sichere Option A wählt, handelt unvernünftig, ganz unabhängig von Aufgabe 2.","Er übersieht, dass D im Schnitt nur 1.000 € übrig lässt, die sichere Option C aber 1.500 €; wer in Aufgabe 2 den Münzwurf D wählt, handelt unvernünftig, ganz unabhängig von Aufgabe 1.","Er übersieht, dass Menschen Zufall grundsätzlich scheuen: Wer in Aufgabe 1 die sichere Option A wählt, zeigt Zufallsscheu und hätte deshalb auch in Aufgabe 2 den Münzwurf D meiden müssen."],"correctIndex":0,"explanation":"Rechne die Endzustände durch: Bei A hast du garantiert 1.000 € + 500 € = 1.500 €, bei C garantiert 2.000 € − 500 € = 1.500 €. Bei B ergibt sich je zur Hälfte 2.000 € oder 1.000 €, bei D je zur Hälfte 1.000 € oder 2.000 €, also im Schnitt jeweils 1.500 €. Aufgabe 1 und Aufgabe 2 sind daher in der Sache identisch. Trotzdem wählen die meisten bei der Gewinnrahmung die sichere Option und bei der Verlustrahmung den Münzwurf. Das ist kein vernünftiger Unterschied in der Lage, sondern ein Rahmungseffekt: Wer von einem Referenzpunkt aus in Gewinnen denkt, meidet Risiko; wer in Verlusten denkt, geht es ein, um den sicheren Verlust zu vermeiden. Wäre die Wahl rein vom Endzustand bestimmt, müsste sie in beiden Aufgaben gleich ausfallen. Der Hinweis auf einen höheren Schnitt von B klingt nach einer Rechnung, doch B bringt im Schnitt 1.500 €, genau wie A. Der Hinweis auf einen niedrigeren Schnitt von D scheitert ebenso, denn D lässt im Schnitt 1.500 € übrig wie C. Wer Zufall grundsätzlich scheute, hätte auch in Aufgabe 2 die sichere Option gewählt, die Mehrheit wählte dort aber den Münzwurf.","coreRule":"⚡ Gleiche Fakten, andere Rahmung: Prüfe zuerst die Endzustände. Ändert sich die Entscheidung nur durch die Formulierung als Gewinn oder Verlust, steuert der Referenzpunkt dein Risikoverhalten.","beleg":"Werkstück A.21 (Das Härten im Feuer: Die Schmiede-Übung; Red Flags)","status":"entwurf","kurz":"Beide Aufgaben führen zu denselben Endzuständen: garantiert 1.500 € oder je zur Hälfte 1.000 € oder 2.000 €. Die unterschiedlichen Wahlen kommen nur von der Rahmung als Gewinn oder Verlust. Wer die Situationen für verschieden hält, hat sie nicht bis zum Ende durchgerechnet.","prueffrage":"Mit welchem Betrag gehst du in jeder der vier Varianten nach der Entscheidung nach Hause?","rueckmeldung":[{"option":1,"text":"Dass sich ein Münzwurf lohnen könnte, wirkt auf den ersten Blick plausibel. Rechnet man aber die Endzustände durch, ergibt B je zur Hälfte 2.000 € oder 1.000 €, im Schnitt also 1.500 €, genau wie das sichere A."},{"option":2,"text":"Hier wird die Verlustseite falsch gerechnet. Nach dem Verlust von 1.000 € bleiben 1.000 € übrig, ohne Verlust 2.000 €. D ergibt im Schnitt also 1.500 €, genau wie die sichere Option C."},{"option":3,"text":"Dass die Wahl von A nach Zufallsscheu aussieht, ist nachvollziehbar. Aber dieselbe Mehrheit wählt in Aufgabe 2 den Münzwurf. Eine feste Scheu vor Zufall würde das nicht erklären, ein Wechsel mit der Rahmung dagegen schon."}],"familie":"rahmen-wechseln","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"461–463","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kahneman, D.; Tversky, A. (1979): Prospect Theory: An Analysis of Decision under Risk. Econometrica 47(2), 263–291","oeffentlich":false,"doi":"10.2307/1914185","seite":"268"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"bca906711a266b58"}},{"id":"qx-a2-038","clusterId":"A","werkstueckRef":"A.21","stufe":4,"question":"Wie sollte das Team jetzt vorgehen?","options":["Den Verlust-Slogan sofort für alle Besucher einführen, weil die Theorie gut belegt ist und Vorsorge-Studien nichts über Käufe aussagen.","Den Gewinn-Slogan behalten, weil die Auswertung der Vorsorge-Studien einen Vorteil der Gewinn-Version zeigt, der auch für Käufe gilt.","Beide Slogans an zufällig geteilten Besuchergruppen testen, weil die Theorie für diesen Shop nur eine plausible Erwartung liefert.","Die Slogan-Frage ruhen lassen, weil eine Theorie über Risiko-Entscheidungen grundsätzlich nichts über die Wirkung von Werbesätzen sagt."],"correctIndex":2,"explanation":"Aus einer gut belegten Theorie über Entscheidungen unter Unsicherheit folgt nicht automatisch, dass ein bestimmter Werbesatz besser verkauft. Zwischen Theorie und Anwendung liegen viele Zwischenschritte: Wie nehmen Menschen die Botschaft wahr, wie viel Aufmerksamkeit schenken sie ihr, welche Alternativen haben sie? Die Metaanalyse, auf die die Kollegin anspielt (O'Keefe und Jensen 2007, 93 Studien mit 21.656 Teilnehmenden zu Vorsorge-Botschaften, also nicht zu Werbung), fand einen sehr kleinen Vorteil des Gewinn-Frames (r = 0,03). Das lässt sich nicht direkt auf Kaufverhalten übertragen, zeigt aber, dass Frame-Effekte klein und uneinheitlich sein können. Die Erwartung des Teams ist daher eine plausible Hypothese, keine gesicherte Wirkung; da der Shop beide Versionen zufällig verteilen kann, lässt sie sich mit einem Vergleichstest messen. Dass die Vorsorge-Befunde nicht übertragbar sind, stimmt zwar, macht die Theorie aber noch nicht zur gemessenen Wirkung. Umgekehrt gilt auch der winzige Gewinn-Vorteil aus der Gesundheitsforschung nicht einfach für Käufe, und dass die Theorie gar nichts aussage, verwirft eine brauchbare Hypothese, die sich hier leicht prüfen ließe.","coreRule":"⚡ Was eine Theorie nahelegt, muss sich in der Praxis erst messen lassen.","beleg":"Werkstück A.21 (Anwendung: Im Marketing); Fn. ga-framing-persuasion (O'Keefe/Jensen 2007, Journal of Health Communication 12(7), S. 623–644)","status":"entwurf","scenario":"Ein Marketingteam will im Onlineshop den Slogan „Jetzt kaufen und 20 % sparen!“ durch „Verpass nicht die Chance, 20 % zu sparen!“ ersetzen. Begründung: Bei Entscheidungen unter Risiko wiegen Verluste nachweislich schwerer als gleich hohe Gewinne. Eine Kollegin wendet ein, eine Auswertung vieler Studien zu Botschaften über Krankheitsvorsorge habe kaum einen Unterschied zwischen beiden Formulierungen gefunden, eher einen winzigen Vorteil für die Gewinn-Version. Der Shop kann jeden Slogan einem zufällig ausgewählten Teil der Besucher zeigen.","kurz":"Die Theorie liefert für diesen Shop nur eine plausible Erwartung, keine gemessene Wirkung, und Frame-Effekte können klein und uneinheitlich sein. Weil sich beide Slogans zufällig verteilen lassen, lässt sich die Frage direkt am eigenen Publikum prüfen.","prueffrage":"Wer hat den Unterschied zwischen beiden Slogans an genau diesen Besuchern und ihren Käufen schon einmal gemessen?","rueckmeldung":[{"option":0,"text":"Dass Vorsorge-Studien nicht auf Käufe übertragbar sind, stimmt. Daraus folgt aber keine gesicherte Wirkung der Theorie auf diesen Slogan, sie bleibt eine plausible Erwartung, die sich hier leicht prüfen ließe."},{"option":1,"text":"Ein winziger Vorteil in der Gesundheitsforschung ist kein Befund über Käufe. Er stammt aus einem anderen Anwendungsfeld und sagt nur, dass Frame-Effekte klein und uneinheitlich sein können, nicht, welcher Slogan hier besser verkauft."},{"option":3,"text":"Richtig ist, dass die Theorie allein keine Werbewirkung belegt. Zu sagen, sie sage „grundsätzlich nichts“, geht aber zu weit: Sie liefert eine brauchbare Hypothese, die sich im Shop direkt testen lässt."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"O’Keefe, D. J.; Jensen, J. D. (2007): The relative persuasiveness of gain-framed and loss-framed messages for encouraging disease prevention behaviors: a meta-analytic review. Journal of Health Communication 12(7), 623–644 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/17934940/","abruf":"2026-10-12"},{"typ":"doi","kurz":"O’Keefe, D. J.; Jensen, J. D. (2007), Verlagsfassung","oeffentlich":false,"doi":"10.1080/10810730701615198"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"1a161a3dd54178e4"}},{"id":"qx-a2-039","clusterId":"A","werkstueckRef":"A.22","stufe":1,"question":"Ein Video-Kommentar zu einer Termitenburg lautet: „So ein Bauwerk mit Belüftungsschächten und Kühlsystem braucht zwingend einen Gesamtplan. Irgendwo muss der gespeichert sein, sonst wäre das reiner Zufall.“ Was ist an dieser Schlussfolgerung fehlerhaft?","options":["Sie setzt voraus, dass komplexe Ordnung einen zentralen Plan braucht. Sie kann aber aus einfachen Regeln und Wechselwirkungen vieler Tiere entstehen, ohne dass irgendwo ein Gesamtplan existiert.","Sie verallgemeinert vom Bau einer einzelnen Termitenburg auf alle Termitenarten. Dabei kann jede Art anders bauen, sodass sich aus einem Beispiel kein Schluss auf einen Gesamtplan ziehen lässt.","Sie übersieht, dass der Plan im Erbgut jeder Termite gespeichert ist und Schritt für Schritt in Bauverhalten übersetzt wird, sodass der Gesamtplan nicht irgendwo, sondern in Tausenden Tieren liegt.","Sie übersieht, dass die Zweckmäßigkeit nur scheinbar ist: Belüftung und Kühlung ergäben sich zufällig, und der Betrachter läse im Nachhinein einen Zweck in das ganze Bauwerk hinein."],"correctIndex":0,"explanation":"Der Schluss „komplexes Ergebnis, also muss es einen Plan geben“ ist ein Fehlschluss. Einzelne Tiere folgen simplen Regeln und kennen weder Belüftungsschacht noch Gesamtform. Erst das Zusammenspiel vieler Individuen erzeugt Strukturen auf der höheren Ebene, die man aus der Untersuchung eines einzelnen Tieres nicht vorhersagen könnte. Das nennt man Emergenz. Ein zentraler Plan ist dafür nicht nötig. Eine sinnvolle Gegenprobe ist die Frage, welche einfachen Regeln und Wechselwirkungen das Ergebnis erzeugen könnten. Der Verallgemeinerungseinwand klingt nach einem bekannten Denkfehler, trifft aber nicht, denn der Kommentar spricht über dieses eine Bauwerk. Ein Plan im Erbgut klingt nach einem gespeicherten Bauplan, widerspricht aber der Beschreibung, dass jedes Tier nur einfachen Reaktionsregeln folgt. Der Gedanke, der Zweck sei nur hineingelesen, klingt nach einem bekannten Fehler, doch Belüftung und Temperaturregelung sind im Szenario als tatsächliche Leistung des Baus beobachtet.","coreRule":"⚡ Komplexe Ordnung braucht keinen zentralen Plan: Sie kann aus den Beziehungen einfacher Teile entstehen.","beleg":"Werkstück A.22 (Einstiegsgeschichte; Kernidee)","status":"entwurf","scenario":"Eine Termitenkolonie besteht aus Tausenden Tieren. Jedes folgt nur einfachen Reaktionsregeln, etwa „Lege Material ab, wo schon Material liegt“ oder „Folge dem Duftsignal der Nachbarn“. Beobachtet wird: Das Gesamtbauwerk ist komplex und zweckmäßig, etwa mit Belüftung und Temperaturregelung.","kurz":"Aus einem komplexen Ergebnis folgt nicht, dass irgendwo ein Gesamtplan existiert. Tiere mit einfachen Regeln können durch ihr Zusammenspiel Strukturen erzeugen, die keines von ihnen kennt. „Plan oder Zufall“ ist daher keine echte Alternative.","prueffrage":"Weiß eine einzelne Termite, wie der fertige Bau aussehen soll, und woran würdest du das erkennen?","rueckmeldung":[{"option":1,"text":"Ein einzelnes Beispiel zu verallgemeinern wäre ein Fehler, aber der Kommentar tut das gar nicht: Er spricht nur über dieses eine Bauwerk. Der Einwand klingt nach einem bekannten Denkfehler, trifft hier aber nicht."},{"option":2,"text":"Verhalten hat durchaus erbliche Anteile, das macht den Gedanken plausibel. Dann läge der Plan aber nur an anderer Stelle, und das Szenario beschreibt ja gerade, dass jedes Tier nur einfachen Reaktionsregeln folgt, nicht einem Bauplan."},{"option":3,"text":"Menschen lesen tatsächlich gern im Nachhinein Absicht in Dinge hinein. Hier ist die Leistung aber als beobachtet beschrieben: Belüftung und Temperaturregelung funktionieren. Die Alternative zum Plan ist auch nicht Zufall, sondern Regeln, die im Zusammenspiel wirken."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Calovi, D. S. u. a. (2019): Surface curvature guides early construction activity in mound-building termites. Phil. Trans. R. Soc. B 374","oeffentlich":true,"doi":"10.1098/rstb.2018.0374","abruf":"2026-10-12"},{"typ":"url","kurz":"O'Connor, T.: Emergent Properties. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/properties-emergent/","abruf":"2026-10-12"},{"typ":"url","kurz":"Reynolds, C. W.: Boids (Background and Update), red3d.com","oeffentlich":true,"url":"https://www.red3d.com/cwr/boids/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"4e20d99223bac3a9"}},{"id":"qx-a2-040","clusterId":"A","werkstueckRef":"A.22","stufe":2,"question":"Ein Redner sagt: „Wasser ist nass, obwohl weder Wasserstoff noch Sauerstoff nass sind. Das beweist, dass man nichts verstehen kann, wenn man nur die Einzelteile untersucht.“ Wo liegt der Fehler in dieser Schlussfolgerung?","options":["Er begeht einen Zusammensetzungsfehlschluss: Er schließt von den Eigenschaften der Gase Wasserstoff und Sauerstoff auf die des Wassers, obwohl beides verschieden sein kann.","Er geht zu weit: Dass sich die Nässe des Wassers nicht aus Wasserstoff und Sauerstoff allein ablesen lässt, heißt nicht, dass die Einzelteile unwichtig sind.","Er benutzt „nass“ in zwei Bedeutungen: einmal für die Gase Wasserstoff und Sauerstoff, einmal für das flüssige Wasser, sodass der Schluss auf einer Mehrdeutigkeit beruht.","Er unterschätzt, dass sich Nässe mit genügend Rechenleistung exakt aus einem einzelnen H₂O-Molekül vorhersagen lässt, sodass die Untersuchung der Einzelteile doch genügt."],"correctIndex":1,"explanation":"Die Beobachtung stimmt: Wasserstoff ist ein brennbares Gas, Sauerstoff nährt Feuer, aber Wasser ist flüssig, hat Oberflächenspannung und macht Dinge nass. Ein einzelnes H₂O-Molekül ist nicht nass; die Eigenschaft zeigt sich erst im Zusammenspiel unzähliger Moleküle, die über Wasserstoffbrücken aneinander haften. Der Fehler liegt im Sprung von „nicht an einem einzelnen Teil ablesbar“ zu „Teile untersuchen bringt nichts“. Gerade die Kräfte zwischen den Molekülen erklären, warum Wasser Tropfen bildet und Oberflächen benetzt: Nässe widerspricht der Chemie nicht, sie baut auf ihr auf. Wer verstehen will, muss also die Teile und ihr Zusammenspiel untersuchen, nicht das eine statt des anderen. Der Zusammensetzungsfehlschluss klingt nach einem bekannten Denkfehler, trifft aber nicht: Der Redner schließt nicht von den Gasen auf das Wasser, er betont ja gerade den Unterschied. Der Vorwurf der Mehrdeutigkeit klingt scharfsinnig, doch „nass“ wird durchgehend im selben Sinn verwendet. Die Hoffnung auf Rechenleistung klingt nach dem Programm der Reduktion, scheitert aber daran, dass sich Nässe aus einem einzelnen Molekül nicht ablesen lässt, so viel man auch rechnet.","coreRule":"⚡ Eine emergente Eigenschaft steckt in den Beziehungen der Teile, nicht in den Teilen selbst, und sie baut auf den Gesetzen der Teile auf, statt ihnen zu widersprechen.","beleg":"Werkstück A.22 (Einstiegsgeschichte, Das Wasser; Anti-Denkmuster: Konsistenz)","status":"entwurf","scenario":"","kurz":"Dass Nässe an einem einzelnen Teil nicht ablesbar ist, heißt nicht, dass das Untersuchen der Teile nichts bringt. Die Kräfte zwischen den Molekülen erklären die Nässe: Verstehen braucht die Teile und ihr Zusammenspiel.","prueffrage":"Woher stammt das heutige Wissen darüber, warum Wasser Tropfen bildet und Oberflächen benetzt?","rueckmeldung":[{"option":0,"text":"Dieser Fehlschluss schließt von den Teilen auf das Ganze. Der Redner tut das nicht, er betont ja gerade, dass Wasser etwas anderes ist als seine Bestandteile. Der Fehler liegt an anderer Stelle: im Sprung zur Aussage, Teile zu untersuchen bringe nichts."},{"option":2,"text":"Ein Doppelsinn würde bedeuten, dass „nass“ mal Verschiedenes meint. Hier steht das Wort aber durchgehend im selben Sinn: Die Gase sind nicht nass, das Wasser ist es. Der Schluss scheitert daher nicht an der Wortwahl."},{"option":3,"text":"Ein einzelnes H₂O-Molekül ist nicht nass. Die Eigenschaft zeigt sich erst im Zusammenspiel vieler Moleküle, und das lässt sich nicht aus einem Molekül ablesen, wie viel man auch rechnet. Richtig ist, dass die Teile wichtig sind, aber allein genügen sie nicht."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"USGS Water Science School: Adhesion and Cohesion Water","oeffentlich":true,"url":"https://www.usgs.gov/special-topics/water-science-school/science/adhesion-and-cohesion-water","abruf":"2026-10-12"},{"typ":"url","kurz":"USGS Water Science School: Surface Tension and Water","oeffentlich":true,"url":"https://www.usgs.gov/special-topics/water-science-school/science/surface-tension-and-water","abruf":"2026-10-12"},{"typ":"url","kurz":"O'Connor, T.: Emergent Properties. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/properties-emergent/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"f2341e8c76ee0617"}},{"id":"qx-a2-041","clusterId":"A","werkstueckRef":"A.22","stufe":3,"question":"Du hörst in einer Diskussion diese Erklärung: „Wie die Methode wirkt? Das ist eine emergente Eigenschaft des Quantenfeldes.“ Was ist an dieser Antwort der entscheidende Schwachpunkt?","options":["Die Antwort benennt keinen Mechanismus: Es bleibt offen, welche Wechselwirkungen welcher Teile die behauptete Wirkung erzeugen sollen.","Die Antwort ist zu fachsprachlich gehalten; sobald sie in Alltagssprache formuliert wäre, wäre die Behauptung überprüfbar und damit belegt.","Die Antwort setzt voraus, dass Emergenz nur in lebenden Systemen vorkommt, während Felder und Teilchen nie neue Eigenschaften zeigen.","Die Antwort scheitert, weil sich emergente Eigenschaften grundsätzlich nicht erklären lassen und jede Erklärung deshalb unzulässig ist."],"correctIndex":0,"explanation":"Emergenz beschreibt nur, dass auf einer höheren Ebene Eigenschaften auftauchen, die einzelne Teile nicht zeigen. Sie erklärt nichts, solange offen bleibt, wie das geschieht. Ein Verkehrsforscher kann die Regeln nennen, nach denen aus dem Verhalten einzelner Fahrer ein Stau entsteht. Wer dagegen nur sagt „Das ist emergent“, ersetzt den Mechanismus durch ein Etikett und beendet die Diskussion, statt sie zu beginnen. Prüffragen: Welche Interaktionen zwischen welchen Komponenten erzeugen die Wirkung? Und widerspricht sie bekannten physikalischen Gesetzen? Echte Emergenz baut auf den Gesetzen der unteren Ebene auf und bricht sie nicht.","coreRule":"⚡ „Es ist emergent“ ist keine Erklärung, solange kein Mechanismus benannt wird.","quote":"Das ist eine emergente Eigenschaft des Quantenfeldes.","quoteLabel":"Beispielantwort:","beleg":"Werkstück A.22 (Anwendung: Pseudowissenschaftlicher Missbrauch; Der Kipppunkt; Aktivierungs-Frage 1)","status":"entwurf","scenario":"Eine Anbieterin von „Energieheilung“ wird gefragt, wie ihre Methode funktioniert. Sie antwortet: „Das ist eine emergente Eigenschaft des Quantenfeldes.“ Danach geht das Gespräch zu einem anderen Thema über.","kurz":"„Emergent“ besagt nur, dass auf höherer Ebene neue Eigenschaften auftreten, nicht wie. Ohne Angabe, welche Wechselwirkungen welcher Teile die Wirkung erzeugen, ersetzt das Etikett den Mechanismus und beendet die Diskussion.","prueffrage":"Was sagt die Anbieterin nach diesem Satz noch über ihre Methode, und was weiß man danach mehr als vorher?","rueckmeldung":[{"option":1,"text":"Fachwörter können Leere tatsächlich verdecken. Einfachere Sprache macht eine Behauptung aber noch nicht überprüfbar, geschweige denn belegt; dafür bräuchte es einen benannten Mechanismus, und genau der fehlt."},{"option":2,"text":"Emergenz ist nicht auf Lebewesen beschränkt, auch die Nässe von Wasser entsteht erst aus dem Zusammenspiel vieler Teilchen. Zudem setzt der Satz das gar nicht voraus: Er schreibt die Emergenz ja einem Quantenfeld zu."},{"option":3,"text":"Emergente Eigenschaften lassen sich oft gut erklären, etwa über die Regeln, nach denen einzelne Fahrer einen Stau erzeugen. Nicht das Erklären ist unzulässig, sondern das bloße Etikett „emergent“ ohne jede Erklärung."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Craver, C.; Tabery, J.; Illari, P.: Mechanisms in Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/science-mechanisms/","abruf":"2026-10-12"},{"typ":"url","kurz":"O'Connor, T.: Emergent Properties. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/properties-emergent/","abruf":"2026-10-12"},{"typ":"url","kurz":"Reynolds, C. W.: Boids (Background and Update), red3d.com","oeffentlich":true,"url":"https://www.red3d.com/cwr/boids/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"66ad8cabbb2bfd50"}},{"id":"qx-a2-042","clusterId":"A","werkstueckRef":"A.22","stufe":4,"question":"Ein Anbieter erklärt, sein „energetisiertes“ Wasser heile Beschwerden. Auf die Rückfrage nach dem Wirkmechanismus sagt er: „Das ist eine emergente Eigenschaft des Wassers, die man nicht auf einzelne Moleküle zurückführen kann.“ Welche Rückfrage prüft diese Behauptung am besten?","options":["Welche Wechselwirkungen zwischen welchen Bestandteilen des Wassers sollen die Heilwirkung erzeugen, und passt das zu den bekannten Gesetzen der Physik?","Wie viele Kundinnen und Kunden haben das energetisierte Wasser schon gekauft, und wie zufrieden äußern sie sich über die Wirkung auf ihre Beschwerden?","Welche anerkannten Fachleute haben das Wort „emergent“ schon einmal für Eigenschaften von Wasser verwendet, und wie wurde es dort gebraucht?","Lässt sich die behauptete Heilwirkung durch genaue Untersuchung eines einzelnen Wassermoleküls vorhersagen, und wie genau müsste man dazu messen?"],"correctIndex":0,"explanation":"Das Wort „emergent“ beschreibt nur, dass auf höherer Ebene etwas Neues entsteht; es erklärt nichts. Seriöse Forschung fragt deshalb nach den Interaktionen, die eine emergente Eigenschaft erzeugen. Nässe ist ein Beispiel: Sie entsteht aus dem Zusammenspiel unzähliger Wassermoleküle und ihrer Wasserstoffbrückenbindungen und widerspricht der Chemie nicht. Ein Verkehrsforscher kann die Regeln nennen, aus denen ein Stau entsteht. Wer „Emergenz“ ruft, aber keinen Mechanismus nennen kann oder ein Phänomen behauptet, das bekannten Gesetzen widerspricht, benutzt das Wort als Diskussionsende statt als Forschungsfrage. Die Rückfrage nach Mechanismus und Vereinbarkeit mit den Gesetzen trennt beides. Die Frage nach Kundenzahl und Zufriedenheit klingt nach einer Praxisprüfung, sagt aber nichts über den Mechanismus. Die Frage nach Fachleuten, die das Wort benutzt haben, klingt nach Absicherung, doch dass andere es benutzen, beweist nichts. Die Untersuchung eines einzelnen Moleküls klingt gründlich, wäre aber der falsche Test, weil emergente Eigenschaften gerade nicht aus einer einzelnen Komponente ablesbar sind.","coreRule":"⚡ „Emergent“ ist eine Beschreibung, keine Erklärung: Verlange den Mechanismus und prüfe, ob er den bekannten Gesetzen widerspricht.","beleg":"Werkstück A.22 (Red Flags; Anti-Denkmuster, Aktivierungs-Frage 2)","status":"entwurf","scenario":"","kurz":"„Emergent“ benennt nur, dass auf höherer Ebene etwas Neues entsteht, und erklärt nichts. Deshalb muss man nach den Wechselwirkungen fragen, die den Effekt erzeugen, und danach, ob das zur Physik passt. Wer das Wort ruft, ohne das zu können, beendet damit die Diskussion.","prueffrage":"Was genau müsste im Wasser anders sein, damit sich ein Unterschied zu gewöhnlichem Wasser nachweisen ließe?","rueckmeldung":[{"option":1,"text":"Viele zufriedene Kunden wirken wie ein Praxistest, doch Zufriedenheit kann auch von Erwartung oder vom natürlichen Verlauf der Beschwerden kommen. Über den Mechanismus, um den es hier geht, sagt sie nichts."},{"option":2,"text":"Dass Fachleute das Wort „emergent“ benutzen, ist an sich nicht ungewöhnlich, belegt aber nichts über dieses Wasser. Ein Wort wird nicht dadurch erklärend, dass andere es verwenden; entscheidend ist, ob der Anbieter den Effekt selbst begründen kann."},{"option":3,"text":"Genaues Messen am einzelnen Molekül klingt gründlich, setzt aber voraus, dass sich die Eigenschaft aus einer Komponente ablesen lässt. Emergente Eigenschaften wie Nässe entstehen jedoch erst aus dem Zusammenspiel vieler Teile, dieser Test sucht also an der falschen Stelle."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Craver, C.; Tabery, J.; Illari, P.: Mechanisms in Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/science-mechanisms/","abruf":"2026-10-12"},{"typ":"url","kurz":"O'Connor, T.: Emergent Properties. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/properties-emergent/","abruf":"2026-10-12"},{"typ":"url","kurz":"USGS Water Science School: Adhesion and Cohesion Water","oeffentlich":true,"url":"https://www.usgs.gov/special-topics/water-science-school/science/adhesion-and-cohesion-water","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"2fffeb627fbf7683"}},{"id":"qx-a2-043","clusterId":"A","werkstueckRef":"A.23","stufe":1,"question":"Eine Analystin sagt über diese Aktie: „Der Kurs steigt seit Wochen gleichmäßig, jede Woche um etwa zwei Prozent. Das System ist stabil, also wird das noch lange so weitergehen.“ Welche Frage prüft am besten, ob dieses System kurz vor einem Umschlag stehen könnte?","options":["Wie stark schwankt der Kurs im Vergleich zu den Wochen davor, und wie schnell erholt er sich von kleinen Rückschlägen?","Wer treibt im Forum die Stimmung an, und verdient diese Person daran, wenn weitere Anleger die Aktie kaufen?","Wie wahrscheinlich ist es, dass ein so gleichmäßiger Anstieg allein durch Zufall entsteht, und wie sicher ist der Trend?","Welche Nachricht aus dem Unternehmen erklärt den Anstieg, und lässt sich diese Nachricht aus einer unabhängigen Quelle bestätigen?"],"correctIndex":0,"explanation":"Ein stetiger Anstieg beweist keine Stabilität: Systeme verändern sich oft lange gleichmäßig und kippen dann in einem Sprung, wie ein Glas, das zentimeterweise über den Tisch geschoben wird, bis die Kante erreicht ist. Die Schilderung zeigt typische Zutaten: Ein verstärkender Motor läuft (die Angst, etwas zu verpassen, treibt neue Käufer an), die Bremsen versagen (Gegenstimmen werden ausgegrenzt) und die Spannung wächst (Kredite machen das System anfällig). Wie nah die Kante ist, zeigt sich aber am besten am Verhalten des Systems selbst: Nahe an einem Umschlag erholt es sich oft langsamer von kleinen Störungen, und die Schwankungen nehmen zu. Schwankung und Erholung verraten allerdings nicht, wann das System kippt, und sie können Fehlalarm geben. Ein Blick auf die Interessen hinter der Stimmung ist ein guter Quellencheck, sagt aber nichts über die Nähe zum Umschlag. Ob ein so gleichmäßiger Anstieg Zufall sein könnte, ist hier nicht die Frage, denn es geht um die Stabilität eines Anstiegs, der schon wochenlang sichtbar ist. Und eine Nachricht, die den Anstieg erklärt, klärt seine Ursache, aber nicht, wie nah die Kante ist.","coreRule":"⚡ Stetig heißt nicht stabil: Frag nach Motoren, Bremsen und Spannung, und beobachte, wie schnell sich das System von kleinen Störungen erholt.","beleg":"Werkstück A.23 (Kontext & Tiefe: Indikatoren 1 bis 3)","status":"entwurf","scenario":"Im Chat eines Anlegerforums zu einer bestimmten Aktie wächst die Zahl der Beiträge, in denen Leute schreiben, sie wollten „auf keinen Fall den Zug verpassen“. Kritische Stimmen werden dort ausgelacht oder gesperrt. Viele Mitglieder haben Kredite aufgenommen, um zu kaufen.","quote":"","quoteLabel":"","kurz":"Ein gleichmäßiger Anstieg beweist keine Stabilität: Systeme driften oft lange stetig und kippen dann abrupt. Nahe an einem Umschlag erholt sich das System oft langsamer von kleinen Störungen, und die Schwankungen nehmen zu. Das zeigt sich am Kursverhalten selbst.","prueffrage":"Was weiß die Analystin über den Kursverlauf, außer dass er im Durchschnitt zwei Prozent pro Woche steigt?","rueckmeldung":[{"option":1,"text":"Wer die Stimmung antreibt und davon profitiert, ist ein guter Quellencheck für die Beiträge im Forum. Er sagt aber nichts darüber, wie nah das System an einem Umschlag ist, und die Stabilität des Anstiegs bleibt offen."},{"option":2,"text":"Ob ein so gleichmäßiger Anstieg Zufall sein könnte, ist hier nicht die Frage: Der Anstieg ist seit Wochen sichtbar. Gefragt ist, wie stabil er ist, und das sagt eine Zufallsabschätzung nicht."},{"option":3,"text":"Eine bestätigte Nachricht erklärt, warum der Kurs steigt, und das ist eine sinnvolle Prüfung. Sie sagt aber nicht, wie nah die Kante ist: Auch ein gut begründeter Anstieg kann kippen."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Dakos, V. (2011): Expecting the Unexpected. Indicators of Resilience as Early-Warning Signals for Critical Transitions. Diss. Wageningen University (Kap. 2 = Scheffer u. a. 2009)","oeffentlich":true,"url":"https://edepot.wur.nl/168815","seite":"31","abruf":"2026-10-12"},{"typ":"url","kurz":"Scheffer, M. u. a. (2009): Early-warning signals for critical transitions. Nature 461, 53–59 (Abstract)","oeffentlich":true,"doi":"10.1038/nature08227","url":"https://pubmed.ncbi.nlm.nih.gov/19727193/","abruf":"2026-10-12"},{"typ":"url","kurz":"Meadows, D.: Leverage Points: Places to Intervene in a System. Donella Meadows Project","oeffentlich":true,"url":"https://donellameadows.org/archives/leverage-points-places-to-intervene-in-a-system/","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"f53fd6ead47c4d23"}},{"id":"qx-a2-044","clusterId":"A","werkstueckRef":"A.23","stufe":2,"question":"Was übersieht die Nutzerin, wenn man den Wandel der Gruppe als instabiler werdendes System betrachtet?","scenario":"In einer Nachbarschaftsgruppe fielen früher Gerüchte schnell in sich zusammen, weil ein paar besonnene Leute sie einordneten. Die sind inzwischen ausgetreten. Seitdem schaukelt sich der Ton bei jedem Gerücht rasch hoch. Eine Nutzerin sagt: „Das Problem sind nur die Gerüchte selbst. Wenn die nicht wären, wäre alles ruhig.“","options":["Dass sich Gerüchte in großen Gruppen im Schnitt schneller verbreiten als in kleinen Gruppen.","Dass die besonnene Einordnung weggefallen ist, die solche Aufschaukelungen früher gedämpft hat.","Dass ein Gerücht umso glaubwürdiger wirkt, je häufiger man es liest (Wahrheitseffekt der Wiederholung).","Dass Gerüchte, die Ängste ansprechen, sich leichter verbreiten als Gerüchte ohne emotionalen Gehalt."],"correctIndex":1,"explanation":"Gerüchte gab es in der Gruppe schon vorher. Geändert hat sich vor allem, dass eine ausgleichende Schleife weggefallen ist: Die besonnene Einordnung wirkte als Bremse, die hitzige Reaktionen abgefangen hat. Systeme kippen oft dann, wenn solche Bremsen überlastet, ausgehebelt oder entfernt werden, etwa wenn Normen, Gesetze oder Peer Review wegfallen. Wer nur auf den Auslöser schaut, sieht nur den Funken und übersieht die fehlende Bremse; deshalb lohnt es sich, nicht nur nach den Antrieben zu fragen, sondern auch nach den Bremsen. Dass sich Gerüchte in großen Gruppen schneller verbreiten, stimmt im Schnitt, doch von einem Wachstum der Gruppe ist hier keine Rede. Dass Wiederholung ein Gerücht glaubwürdiger wirken lässt, ist ebenfalls richtig, erklärt aber nicht, warum der Ton erst nach dem Weggang der Besonnenen kippt. Und Gerüchte, die Ängste ansprechen, verbreiten sich leichter, doch Gerüchte gab es auch früher, ohne dass sich der Ton aufschaukelte.","coreRule":"⚡ Frag nicht nur, was antreibt, sondern auch, welche Bremse fehlt.","beleg":"Werkstück A.23 (Kontext & Tiefe: Indikator 2)","status":"entwurf","kurz":"Geändert hat sich nicht, dass es Gerüchte gibt, sondern dass die Bremse fehlt: Die besonnene Einordnung hat Aufschaukelungen früher abgefangen. Wer nur auf den Auslöser schaut, sieht den Funken und übersieht, was ihn nicht mehr löscht.","prueffrage":"Gab es in der Gruppe auch früher schon Gerüchte, und wie lange hielten sie sich damals?","rueckmeldung":[{"option":0,"text":"Im Schnitt verbreiten sich Gerüchte in großen Gruppen tatsächlich schneller. Von einer wachsenden Gruppe ist hier aber keine Rede, und der Ton kippt erst nach dem Weggang der Besonnenen."},{"option":2,"text":"Wiederholung kann ein Gerücht glaubwürdiger wirken lassen, das stimmt. Diesen Effekt gab es aber auch früher, als Gerüchte rasch in sich zusammenfielen. Er erklärt also nicht, was sich verändert hat."},{"option":3,"text":"Gerüchte, die Ängste ansprechen, verbreiten sich meist leichter. Doch Gerüchte gab es in der Gruppe schon immer, ohne dass sich der Ton aufschaukelte. Der Unterschied liegt woanders als im Inhalt der Gerüchte."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Meadows, D.: Leverage Points: Places to Intervene in a System. Donella Meadows Project","oeffentlich":true,"url":"https://donellameadows.org/archives/leverage-points-places-to-intervene-in-a-system/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"85dd7aa36f7d3e82"}},{"id":"qx-a2-045","clusterId":"A","werkstueckRef":"A.23","stufe":3,"question":"Eine Analystin hat gelernt, nach verstärkenden Rückkopplungen, versagenden Bremsen und aufgestauter Spannung zu suchen. Sie sieht inzwischen in jedem Kursausschlag, jedem Streit im Team und jedem Ausreißer in einer Statistik den Beginn eines Zusammenbruchs. Was ist an ihrem Vorgehen das Problem?","options":["Sie deutet gewöhnliche Schwankungen bei Kursen, Teamstimmung und Kundenzahlen als Vorboten eines Zusammenbruchs und macht ihre Warnungen so durch keine Beobachtung mehr widerlegbar.","Sie schließt aus aufgestauter Spannung in Team und Kursen auf einen Zusammenbruch, obwohl gemeinsames Auftreten von Spannung und Zusammenbruch nicht heißt, dass die Spannung ihn verursacht.","Sie wendet das Raster auf Kurse, Teamstimmung und Kundenzahlen an, die schon gekippt sind, und sucht damit rückblickend nach Ursachen statt nach künftigen Entwicklungen.","Sie lässt sich von spektakulären Zusammenbrüchen leiten, die leichter in den Sinn kommen als unauffällige Fälle, und überschätzt so die Gefahr bei Kursen und Kundenzahlen (Verfügbarkeitsheuristik)."],"correctIndex":0,"explanation":"Ein Denkwerkzeug wird unbrauchbar, wenn es überall anschlägt. Wer harmlose Schwankungen als Beweis für den nahenden Zusammenbruch liest, erkennt Muster im Rauschen (Apophenie). Ihr Satz „Das zeigt nur, wie knapp es war“ macht die Behauptung zusätzlich unwiderlegbar: Tritt der Kollaps ein, hatte sie recht, tritt er nicht ein, war es eben knapp. Eine Behauptung, die durch kein Ergebnis widerlegt werden kann, sagt nichts mehr aus. Dazu kommt: Auch seriöse Frühwarnsignale zeigen nur, dass ein System näher an die Kante rückt, nicht wann es kippt, und sie schlagen mitunter falschen Alarm. Brauchbar ist das Raster deshalb zur Beschreibung der Dynamik hinter einer Entwicklung (Motoren, Bremsen, Spannung, möglicher Auslöser), nicht als Prophezeiung.","coreRule":"⚡ Ein Prüfraster zeigt Architektur, keine Prophezeiung: Wer überall Kipppunkte sieht und jedes Ausbleiben als „knapp“ umdeutet, sieht Muster im Rauschen.","beleg":"Werkstück A.23 (Der Kipppunkt (Von der Nützlichkeit zur Gefahr); Red Flags: Langsameres Zurückfedern); Fn. ga-fruehwarnung (Scheffer u. a. 2009, Nature 461, S. 53–59) und Fn. ga-fruehsignale (Scheffer u. a. 2009, S. 54–58; Dakos 2011, S. 17–32)","status":"entwurf","scenario":"Eine Analystin nutzt ein Prüfraster für Kipppunkte. Sie fragt: Wo verstärkt sich etwas selbst? Welche Bremsen versagen? Wie viel Spannung hat sich aufgestaut? Seit sie damit arbeitet, warnt sie fast wöchentlich vor einem bevorstehenden Kollaps, ob bei Aktienkursen, Teamstimmung oder Kundenzahlen. Bisher ist keine ihrer Warnungen eingetreten, aber sie sagt: „Das zeigt nur, wie knapp es jedes Mal war.“","kurz":"Wer jede gewöhnliche Schwankung als Vorbote des Zusammenbruchs liest und ein Ausbleiben mit „es war knapp“ erklärt, kann nie widerlegt werden. Eine solche Warnung sagt nichts mehr aus.","prueffrage":"Wie viele ihrer Warnungen sind bisher eingetreten, und wie erklärt die Analystin die übrigen?","rueckmeldung":[{"option":1,"text":"Dass Spannung und Zusammenbruch zusammen auftreten können, ist richtig. Die Analystin behauptet aber keinen Ursachenzusammenhang aus Daten, sondern warnt vor einem künftigen Verlauf. Ihr Fehler liegt darin, dass sich ihre Warnung nicht widerlegen lässt."},{"option":2,"text":"Eine Rückschau suchte Ursachen eines Zusammenbruchs, der schon eingetreten ist. Hier ist aber keine ihrer Warnungen eingetreten, es gibt also nichts, was sie nachträglich erklären könnte. Sie sagt Kommendes voraus, und dort liegt das Problem."},{"option":3,"text":"Dass sie überall Gefahr sieht, spricht für eine Verzerrung der Wahrnehmung. Nichts im Szenario deutet aber darauf hin, dass spektakuläre Erinnerungen sie leiten, sie folgt einem festen Raster. Das Problem ist, dass „knapp“ jedes Ergebnis erklärt."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Dakos, V. (2011): Expecting the Unexpected. Indicators of Resilience as Early-Warning Signals for Critical Transitions. Diss. Wageningen University","oeffentlich":true,"url":"https://edepot.wur.nl/168815","seite":"31","abruf":"2026-10-12"},{"typ":"url","kurz":"Thornton, S.: Karl Popper. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"c86a19d93e37c9a9"}},{"id":"qx-a2-046","clusterId":"A","werkstueckRef":"A.23","stufe":4,"question":"Ein Team beobachtet über Monate ein Ökosystem. Die Messwerte zeigen: Nach kleinen Störungen erholt es sich immer langsamer, die Schwankungen werden größer, und jeder Zustand gleicht stärker dem vorigen. Eine Kollegin sagt: „Dann kippt das System in den nächsten Wochen, das ist jetzt sicher.“ Was ist die beste Einschätzung?","options":["Die Signale sprechen dafür, dass die Kante näher rückt, doch ob und wann das System in den nächsten Wochen kippt, sagen sie nicht verlässlich voraus.","Die Signale sprechen dafür, dass das System in den nächsten Wochen kippt, auch wenn der genaue Tag offen bleibt, denn solche Muster treten meist kurz vor dem Umbruch auf.","Die Signale sprechen eher dafür, dass das System bereits gekippt ist, denn ein System, das sich nur noch langsam erholt, steckt meist schon im neuen Zustand.","Die Signale sagen nur etwas über die Ursache der Störungen: Ohne bekannte Quelle lässt sich aus der langsamen Erholung nichts über die Nähe zur Kante schließen."],"correctIndex":0,"explanation":"Wenn sich ein System nahe einer Schwelle langsamer von kleinen Störungen erholt, stärker schwankt und jeder Zustand dem vorigen ähnlicher wird, rückt die Kante näher. Das ist ein allgemeines Muster, das in Modellen, in Klimadaten der Erdgeschichte, bei befischten Beständen und vor epileptischen Anfällen gefunden wurde. Es sagt aber nur etwas über die Nähe, nicht über den Zeitpunkt: Solche Signale schlagen mitunter falschen Alarm oder bleiben vor einem echten Umbruch stumm. Die Kollegin schließt also zu viel aus einem Warnsignal. Ein Anlass, genauer hinzusehen und Vorsorge zu treffen, ist es, aber keine Prognose mit Datum. Der Schluss auf einen Umbruch in den nächsten Wochen klingt nach einer Folgerung aus dem Muster, doch die Signale sagen nur etwas über die Nähe, nicht über den Zeitpunkt. Dass das System schon gekippt sei, klingt konsequent, widerspricht aber den Messwerten, denn es erholt sich ja noch, nur langsamer. Dass sich aus Messwerten allein keine Ursache ablesen lässt, stimmt, doch die Signale zeigen die Nähe zur Schwelle unabhängig davon, woher die Störungen kommen.","coreRule":"⚡ Frühwarnsignale zeigen die Nähe der Kante, nicht den Zeitpunkt des Sturzes.","beleg":"Werkstück A.23 (Red Flags: Langsameres Zurückfedern); Fn. ga-fruehsignale (Scheffer u. a. 2009, Nature 461(7260), S. 53–59, nach Dakos 2011, S. 21, 24, 27–29, 31)","status":"entwurf","scenario":"","kurz":"Langsamere Erholung, größere Schwankungen und wachsende Ähnlichkeit aufeinanderfolgender Zustände zeigen, dass die Kante näher rückt, nicht wann das System kippt. Wer aus dem Warnsignal einen Termin ableitet, schließt zu viel: Solche Signale schlagen mitunter falschen Alarm.","prueffrage":"Welche drei Veränderungen hat das Team gemessen, und wie würde sich ein stabiles System nach kleinen Störungen verhalten?","rueckmeldung":[{"option":1,"text":"Dass solche Muster oft vor Umbrüchen auftreten, stimmt. Daraus folgt aber nur, dass die Kante näher rückt, nicht, dass es in Wochen passiert: Die Signale schlagen mitunter falschen Alarm oder bleiben vor einem echten Umbruch stumm."},{"option":2,"text":"Das klingt konsequent, passt aber nicht zu den Messwerten: Das System erholt sich ja noch von Störungen, nur langsamer. Es steckt also noch im alten Zustand und rückt an die Schwelle heran, ohne sie schon überschritten zu haben."},{"option":3,"text":"Dass sich aus Messwerten allein keine Ursache ablesen lässt, stimmt. Die Signale sagen aber auch nichts über Ursachen, sondern zeigen am System selbst, wie nah es der Schwelle ist, ganz gleich, woher die Störungen kommen."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Dakos, V. (2011): Expecting the Unexpected. Indicators of Resilience as Early-Warning Signals for Critical Transitions. Diss. Wageningen University (Kap. 2 = Scheffer u. a. 2009)","oeffentlich":true,"url":"https://edepot.wur.nl/168815","seite":"31","abruf":"2026-10-12"},{"typ":"doi","kurz":"Dakos, V. u. a. (2008): Slowing down as an early warning signal for abrupt climate change. PNAS 105(38), 14308–14312","oeffentlich":true,"doi":"10.1073/pnas.0802430105","abruf":"2026-10-12"},{"typ":"url","kurz":"Scheffer, M. u. a. (2009): Early-warning signals for critical transitions. Nature 461, 53–59 (Abstract)","oeffentlich":true,"doi":"10.1038/nature08227","url":"https://pubmed.ncbi.nlm.nih.gov/19727193/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"7820c08e317dd998"}},{"id":"qx-a2-047","clusterId":"A","werkstueckRef":"A.24","stufe":1,"question":"Eine Forscherin sieht sich ihre Messdaten erst an und stellt dann fest, dass sich in einer Untergruppe ein „signifikanter“ Effekt zeigt. In ihrer Veröffentlichung schreibt sie, genau diesen Effekt habe sie von Anfang an erwartet. Welche Maßnahme hätte dieses Vorgehen am wirksamsten verhindert?","options":["Hypothese, Stichprobengröße und Auswertungsplan vor der Datenerhebung mit Zeitstempel hinterlegen; spätere Funde als explorativ kennzeichnen.","Die Stichprobe deutlich vergrößern, damit die Teststärke auch in den Untergruppen reicht; kleine echte Effekte würden dann sicher erkannt.","Die Auswertung verblinden, damit die Auswertenden nicht wissen, welche Teilnehmer zu welcher Gruppe gehören; so prägt keine Erwartung das Ergebnis.","Nach Erscheinen der Studie prüfen, wie viele vergleichbare Studien nie veröffentlicht wurden; diese unveröffentlichten Studien im Bericht vermerken."],"correctIndex":0,"explanation":"Wer erst die Daten ansieht und dann die Hypothese formuliert (HARKing), findet bei genügend Variablen und Untergruppen fast immer etwas: Es ist, als würde man erst schießen und dann die Zielscheibe malen. Dagegen hilft nur, die Wette vorher zu versiegeln. Wenn Hypothese und Plan vor den Daten feststehen und belegbar sind, lässt sich nachprüfen, ob das Ergebnis erwartet oder nachträglich zurechtgelegt wurde. Alles, was später zusätzlich auftaucht, bleibt erlaubt, zählt aber als Idee für die nächste Studie und nicht als Beweis. Eine Auswertung großer US-Herz-Kreislauf-Studien stützt das: Vor 2000, ohne Pflicht zur vorherigen Festlegung der Zielgröße, meldeten 17 von 30 Studien (57 Prozent) einen Nutzen, danach 2 von 25 (8 Prozent). Die Autoren halten für möglich, dass die Registrierung dazu beitrug.","coreRule":"⚡ Erst die Wette versiegeln, dann die Karten aufdecken: Hypothese vor den Daten.","quote":"Alles, was danach zusätzlich gefunden wird, ist erlaubt -- aber als *explorativ* zu kennzeichnen, als Idee für die nächste Studie, nicht als Beweis in dieser.","quoteLabel":"Merksatz:","beleg":"Werkstück A.24 (Werkzeug 2: Präregistrierung); Fn. ga-praeregistrierung (Kaplan/Irvin 2015, PLOS ONE 10(8), e0132382; Kerr 1998)","status":"entwurf","scenario":"Eine Studie wertet viele Variablen und Untergruppen aus. Bei genügend Auswertungswegen liefert der Zufall fast immer irgendwo ein „signifikantes“ Muster. Im Bericht steht später, die Hypothese sei von Anfang an klar gewesen.","kurz":"Nur eine vorab hinterlegte Hypothese samt Auswertungsplan lässt später prüfen, ob ein Effekt wirklich erwartet war. Wer erst die Daten ansieht, findet bei vielen Untergruppen fast immer etwas, wie beim Schießen und anschließenden Zielscheibenmalen.","prueffrage":"In wie vielen Untergruppen hat die Forscherin nach einem Effekt gesucht, und in wie vielen ist sie fündig geworden?","rueckmeldung":[{"option":1,"text":"Mehr Teilnehmende erhöhen die Teststärke und sind oft nützlich. Das Problem ist aber ein anderes: Wer viele Untergruppen auswertet, findet auch in großen Stichproben zufällige Muster und kann sie hinterher als erwartet ausgeben."},{"option":2,"text":"Verblindung schützt tatsächlich davor, dass Erwartungen die Auswertung färben. Sie legt aber nicht fest, was vorher behauptet wurde, und verhindert daher nicht, dass eine Hypothese erst nach dem Blick auf die Daten entsteht."},{"option":3,"text":"Unveröffentlichte Studien zu zählen macht Verzerrungen bei der Veröffentlichung sichtbar. Hier liegt das Problem aber früher: Die Hypothese wurde erst nach den Daten formuliert, und eine spätere Zählung verhindert das nicht."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Nosek, B. A.; Ebersole, C. R.; DeHaven, A. C.; Mellor, D. T. (2018): The preregistration revolution. PNAS 115(11), 2600–2606","oeffentlich":true,"doi":"10.1073/pnas.1708274114","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kaplan, R. M.; Irvin, V. L. (2015): Likelihood of Null Effects of Large NHLBI Clinical Trials Has Increased over Time. PLOS ONE 10(8), e0132382","oeffentlich":true,"doi":"10.1371/journal.pone.0132382","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kerr, N. L. (1998): HARKing: Hypothesizing After the Results are Known. Personality and Social Psychology Review 2(3), 196–217","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"a9b265f0eea8d803"}},{"id":"qx-a2-048","clusterId":"A","werkstueckRef":"A.24","stufe":2,"question":"Eine Zeitung titelt: „Mittel wirkt nicht: Ergebnis nicht signifikant (p = 0,06).“ Welche Überlegung ist hier am sinnvollsten?","options":["Ein p-Wert von 0,06 bedeutet, dass die Wirkung mit 94 Prozent Wahrscheinlichkeit echt ist, und die Zeitung hätte diese hohe Wahrscheinlichkeit nennen müssen.","Ein p-Wert knapp über 0,05 spricht dafür, dass der Effekt klein ist, denn ein großer Effekt hätte die Schwelle von 0,05 sicher unterschritten.","Die Schwelle von 0,05 ist eine Konvention, und eine Wirkung bleibt mit den Daten vereinbar, solange das Konfidenzintervall sie nicht ausschließt.","Ein p-Wert von 0,06 liegt so nah an der Schwelle von 0,05, dass er praktisch als signifikant gilt und die Zeitung „Mittel wirkt“ hätte titeln müssen."],"correctIndex":2,"explanation":"„Nicht signifikant“ heißt nicht „kein Effekt“. Es heißt nur, dass die Daten die Annahme „gar keine Wirkung“ nicht deutlich genug widerlegen. Die Schwelle von 5 Prozent ist eine Konvention, kein Naturgesetz: Ein Ergebnis mit p = 0,06 und eines mit p = 0,04 unterscheiden sich kaum, werden aber als „wirkt nicht“ und „wirkt“ verkauft. Auch ein signifikantes Ergebnis schließt den Zufall nicht aus, und ein nicht signifikantes beweist keine Wirkungslosigkeit. Die American Statistical Association warnte 2016 vor genau diesem Gebrauch des p-Werts, und 2019 forderten über 800 Forschende in Nature, „statistisch signifikant“ nicht länger als Ja-Nein-Urteil zu verwenden. Sinnvoll ist es, das Konfidenzintervall zu lesen: Es zeigt, welche Effektgrößen mit den Daten vereinbar sind, und damit auch, ob eine bedeutsame Wirkung noch möglich ist. Die Deutung von p = 0,06 als 94-prozentige Wahrscheinlichkeit für eine echte Wirkung klingt nach einer einfachen Übersetzung, verwechselt aber die Frage, wie gut die Daten zu „keine Wirkung“ passen, mit der Frage, wie wahrscheinlich die Wirkung ist. Dass ein großer Effekt die Schwelle sicher unterschritten hätte, klingt logisch, doch der p-Wert hängt auch von der Teilnehmerzahl ab, sodass selbst ein großer Effekt bei einer kleinen Studie knapp scheitern kann. Die Überschrift „Mittel wirkt“ kehrt den Fehler der Zeitung nur um, denn bei p = 0,06 ist die Wirkung ebenso wenig belegt wie ihr Fehlen.","coreRule":"⚡ Lies das Intervall, nicht nur das Etikett „signifikant“ oder „nicht signifikant“.","beleg":"Werkstück A.24 (Werkzeug 3: Konfidenzintervall); Fn. ga-signifikanz (Wasserstein/Lazar 2016, The American Statistician 70(2), S. 131–132; Amrhein u. a. 2019, Nature 567, S. 305–307)","status":"entwurf","scenario":"In der Meldung steht nur der p-Wert. Zur Größe des Effekts oder zu einem Konfidenzintervall wird nichts gesagt.","kurz":"„Nicht signifikant“ heißt nicht „kein Effekt“: Die Schwelle von 0,05 ist eine Konvention, und das Konfidenzintervall zeigt, welche Wirkungen die Daten noch zulassen. Der Fehler ist, aus einer knapp verfehlten Schwelle ein Ja-Nein-Urteil zu machen.","prueffrage":"Würde die Schlagzeile umgekehrt lauten, wenn p = 0,04 herausgekommen wäre, und wie groß wäre dieser Unterschied in den Daten?","rueckmeldung":[{"option":0,"text":"Die Rechnung „1 minus 0,06“ liegt nahe, beantwortet aber eine andere Frage. Der p-Wert sagt, wie gut die Daten zu „keine Wirkung“ passen, nicht, wie wahrscheinlich die Wirkung echt ist."},{"option":1,"text":"Ein kleiner Effekt würde zu p = 0,06 passen, aber ebenso ein großer: Der p-Wert hängt auch von der Teilnehmerzahl ab, und bei einer kleinen Studie kann selbst ein großer Effekt die Schwelle knapp verfehlen."},{"option":3,"text":"Dass sich p = 0,06 und p = 0,04 kaum unterscheiden, stimmt. Daraus folgt aber nicht, dass man die Schwelle großzügiger anwenden sollte: Auch „Mittel wirkt“ wäre bei p = 0,06 nicht belegt und kehrt den Fehler nur um."}],"familie":"studie-genau-lesen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"American Statistical Association (2016): ASA releases statement on statistical significance and p-values (Pressemitteilung, 7. März 2016)","oeffentlich":true,"url":"https://www.amstat.org/asa/files/pdfs/p-valuestatement.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Wasserstein, R. L.; Lazar, N. A. (2016): The ASA Statement on p-Values: Context, Process, and Purpose. The American Statistician 70(2), 129–133","oeffentlich":false,"doi":"10.1080/00031305.2016.1154108"},{"typ":"literatur","kurz":"Amrhein, V.; Greenland, S.; McShane, B. (2019): Scientists rise up against statistical significance. Nature 567, 305–307","oeffentlich":false,"doi":"10.1038/d41586-019-00857-9"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"c98a634c62fe775d"}},{"id":"qx-a2-049","clusterId":"A","werkstueckRef":"A.24","stufe":3,"question":"Was folgt aus diesen Angaben?","options":["Der Effekt ist nicht ursächlich belegt, weil die Stimmung der 689.003 Teilnehmer nur beobachtet wurde und Korrelation keine Ursache beweist.","Der Effekt ist wahrscheinlich ein Zufallsfund, weil bei 689.003 Teilnehmern und vielen Auswertungen irgendein Unterschied signifikant wird.","Der Effekt ist nachweisbar, aber mit d = 0,001 bis 0,02 praktisch winzig, weil Signifikanz nichts über die Größe eines Effekts aussagt.","Der Effekt ist groß, weil der p-Wert extrem klein ist und ein kleinerer p-Wert bei 689.003 Teilnehmern auf einen größeren Effekt hinweist."],"correctIndex":2,"explanation":"Mit einer hinreichend großen Stichprobe wird jeder noch so winzige Unterschied signifikant. Signifikanz sagt nur, dass die Daten schlecht zur Annahme „gar kein Effekt“ passen, nicht, wie groß der Effekt ist. Die gemeldeten Werte (d = 0,001 bis 0,02) liegen deutlich unter der Konvention für einen kleinen Effekt (ab d = 0,2) und sind im Alltag eines einzelnen Nutzers unsichtbar. Die Schlagzeile verwechselt „nachweisbar“ mit „bedeutend“. Die prüfende Frage lautet: Wie groß ist der Effekt in einer Einheit, die ich mir vorstellen kann?","coreRule":"⚡ Signifikanz beantwortet „Gibt es etwas?“, die Effektstärke „Wie viel?“.","beleg":"Werkstück A.24 (Werkzeug 4: Effektstärke); Fn. ga-effektstaerke (Kramer u. a. 2014, PNAS 111(24), S. 8788–8790; Cohen 1988)","status":"entwurf","scenario":"Eine Schlagzeile lautet: „Studie beweist: Gefühle stecken über soziale Netzwerke an.“ Im Studienbericht steht: Bei 689.003 Teilnehmern „steckte“ die Stimmung durch manipulierte Nachrichtenfeeds messbar an; das Ergebnis ist hochsignifikant (p-Wert extrem klein), die Effektstärke d liegt zwischen 0,001 und 0,02. Als Faustregel gilt: Ab d = 0,2 spricht man von einem kleinen, ab 0,5 von einem mittleren und ab 0,8 von einem großen Effekt.","kurz":"Der Effekt ist nachweisbar, aber mit d = 0,001 bis 0,02 winzig. Bei 689.003 Teilnehmern wird fast jeder Unterschied signifikant; ein kleiner p-Wert zeigt nur, wie sicher der Nachweis ist, nicht, wie groß der Effekt ist.","prueffrage":"Wie viel Stimmungsänderung steckt in diesem Wert, wenn du ihn in etwas Greifbares umrechnest?","rueckmeldung":[{"option":0,"text":"Der Grundsatz, dass Korrelation keine Ursache beweist, stimmt allgemein. Hier wurden die Feeds aber gezielt manipuliert, es liegt also ein Eingriff vor und nicht bloß eine Beobachtung. Offen bleibt die Größe des Effekts."},{"option":1,"text":"Bei vielen Auswertungen kann tatsächlich ein Zufallstreffer auftreten. Bei einem extrem kleinen p-Wert taugt das aber kaum als Erklärung: Der Effekt ist wohl real, nur sehr klein."},{"option":3,"text":"Ein kleiner p-Wert klingt nach großer Wirkung, misst aber nur die Sicherheit des Nachweises. Bei 689.003 Teilnehmern wird schon d = 0,001 signifikant, und die gemeldeten Werte liegen weit unter der Schwelle für einen kleinen Effekt."}],"familie":"studie-genau-lesen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Kramer, A. D. I.; Guillory, J. E.; Hancock, J. T. (2014): Experimental evidence of massive-scale emotional contagion through social networks. PNAS 111(24), 8788–8790","oeffentlich":true,"doi":"10.1073/pnas.1320040111","abruf":"2026-10-12"},{"typ":"url","kurz":"American Statistical Association (2016): ASA releases statement on statistical significance and p-values (Pressemitteilung)","oeffentlich":true,"url":"https://www.amstat.org/asa/files/pdfs/p-valuestatement.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Cohen, J. (1988): Statistical Power Analysis for the Behavioral Sciences. 2. Aufl. Hillsdale: Erlbaum","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"12ade6126f915502"}},{"id":"qx-a2-050","clusterId":"A","werkstueckRef":"A.24","stufe":4,"question":"Welche Frage prüft diesen Schluss am besten?","options":["Wie sieht das Verhältnis aus, wenn man Geimpfte und Ungeimpfte innerhalb derselben Altersgruppe vergleicht?","Wie zuverlässig wurde in den Krankenhäusern der Impfstatus der Schwerkranken erfasst, und wie vollständig sind die Meldungen?","Wie viele Schwerkranke wurden insgesamt gezählt, und reicht diese Zahl aus, um verlässliche Aussagen zu treffen?","Wer hat die Zahlen erhoben und veröffentlicht, und hat diese Stelle ein erkennbares Interesse an einem bestimmten Ergebnis?"],"correctIndex":0,"explanation":"Die Gesamtzahl vermischt Gruppen, die sich im Risiko stark unterscheiden. Sind die Gefährdetsten zugleich fast alle geimpft, stellen Geimpfte einen großen Teil der Schwerkranken, selbst wenn die Impfung das Risiko in jeder Altersgruppe deutlich senkt. Ein solcher Zusammenhang, der in der Gesamtheit anders aussieht als in den Teilgruppen, heißt Simpson-Paradox. Ein berühmtes Beispiel: Berkeley 1973 ließ 44 Prozent der männlichen, aber nur 35 Prozent der weiblichen Bewerber zu. Nach Fachbereichen aufgeschlüsselt zeigte sich kein Nachteil für Frauen, weil sie sich häufiger in Fächern mit niedrigen Zulassungsquoten beworben hatten. Der Vergleich innerhalb gleicher Gruppen entscheidet also, was die Zahlen aussagen. Vorsicht in der Gegenrichtung: Nicht jede Aufteilung ist die richtige, und welche gilt, verraten die Zahlen allein nicht. Die Erfassung des Impfstatus zu prüfen ist ein sinnvoller Datencheck, ändert aber nichts daran, dass die Gesamtzahl Gruppen mischt. Die Fallzahl schützt vor Zufallsschwankungen, nicht vor der Vermischung unterschiedlicher Risikogruppen. Und die Frage nach dem Interesse hinter den Zahlen betrifft die Quelle, nicht die Rechnung.","coreRule":"⚡ Teile die Gruppen auf, aber frag, welche Aufteilung der Zusammenhang wirklich verlangt.","beleg":"Werkstück A.24 (Werkzeug 5: Das Simpson-Paradox); Fn. ga-simpson (Bickel/Hammel/O'Connell 1975, Science 187(4175), S. 398–404; Morris 2021; Pearl 2014, The American Statistician 68(1), S. 8–13)","status":"entwurf","scenario":"In einem Land mit hoher Impfquote meldet eine Zeitung: „Mehr als die Hälfte der Schwerkranken im Krankenhaus ist geimpft. Die Impfung schützt also kaum.“ Bekannt ist außerdem: Die Ältesten sind fast vollständig geimpft und zugleich am stärksten gefährdet, schwer zu erkranken.","kurz":"Die Gesamtzahl mischt Gruppen mit sehr verschiedenem Risiko: Sind die am stärksten Gefährdeten fast alle geimpft, stellen Geimpfte viele Schwerkranke, auch wenn die Impfung in jeder Altersgruppe schützt. Erst der Vergleich innerhalb gleicher Gruppen zeigt, was die Zahlen aussagen.","prueffrage":"Unterscheiden sich die Geimpften und die Ungeimpften im Land außer durch die Impfung noch in etwas, das ihr Risiko für eine schwere Erkrankung beeinflusst?","rueckmeldung":[{"option":1,"text":"Zu prüfen, wie sauber der Impfstatus erfasst wurde, ist ein sinnvoller Datencheck. Selbst lückenlose Daten ließen die Gesamtzahl aber Gruppen mit sehr unterschiedlichem Risiko vermengen, und genau dort liegt der Schwachpunkt des Schlusses."},{"option":2,"text":"Eine ausreichende Fallzahl schützt vor Zufallsschwankungen, und danach zu fragen ist berechtigt. Hier liegt das Problem aber nicht im Zufall: Auch eine sehr große Zahl bliebe irreführend, wenn sie Gruppen mit unterschiedlichem Risiko zusammenwirft."},{"option":3,"text":"Nach der Quelle und ihrem Interesse zu fragen, ist grundsätzlich klug, betrifft aber die Herkunft der Zahlen, nicht die Rechnung. Auch bei einer völlig neutralen Stelle bliebe der Schluss aus der Gesamtzahl fragwürdig."}],"familie":"studie-genau-lesen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Morris, J. (2021): Israeli data: How can efficacy vs. severe disease be strong when 60% of hospitalized are vaccinated? Covid Data Science","oeffentlich":true,"url":"https://www.covid-datascience.com/post/israeli-data-how-can-efficacy-vs-severe-disease-be-strong-when-60-of-hospitalized-are-vaccinated","abruf":"2026-10-12"},{"typ":"url","kurz":"Pearl, J. (2013): Understanding Simpson's Paradox. UCLA Technical Report R-414 (Vorfassung zu The American Statistician 68(1), 2014)","oeffentlich":true,"url":"https://ftp.cs.ucla.edu/pub/stat_ser/r414.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Bickel, P. J.; Hammel, E. A.; O'Connell, J. W. (1975): Sex Bias in Graduate Admissions: Data from Berkeley. Science 187(4175), 398–404","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"025f407a1fd5c307"}}]`);export{t as n,n as t};